'Cr_Guide_Step_Book_Help' => 'বিক্রয় তালিকায় একটি বিক্রয়ের মেনু খুলে কুরিয়ারে পাঠান বেছে নিন, অথবা কয়েকটি বিক্রয়ে টিক দিয়ে একসাথে পাঠান।',
'Cr_Guide_Step_Errors' => 'ত্রুটির দিকে নজর রাখুন',
'Cr_Guide_Step_Errors_Help' => 'শেষ ২৪ ঘণ্টায় কোনো কুরিয়ার ত্রুটি নেই।',
