'Cr_Guide_Pick_Courier' => 'কী প্রয়োজন দেখতে একটি কুরিয়ার বেছে নিন',
'Cr_Guide_Add_This' => 'এই কুরিয়ার যোগ করুন',
'Cr_Guide_You_Need' => 'আপনার প্রয়োজন',
'Cr_Guide_No_Keys' => 'কোনো API কী নেই: সংযোগ করার কিছু নেই।',
