'Cr_Guide_Webhooks' => 'ওয়েবহুক ঠিকানা',
'Cr_Guide_How' => 'কীভাবে নিবন্ধন করবেন',
'Cr_Guide_How_It_Works' => 'এটি কীভাবে কাজ করে',
'Cr_Guide_Meaning' => 'অর্থ',
'Cr_Guide_T_Statuses' => 'অবস্থাসমূহ',
'Cr_Guide_Statuses_Note' => 'অবস্থা শুধু সামনের দিকে এগোয়, তাই দেরিতে আসা কোনো হালনাগাদ পার্সেলকে পেছনে টেনে আনে না। পৌঁছে দেওয়া পার্সেলকেও ফেরত আসছে বা ফেরত এসেছে হিসেবে জানানো যায়।',
'Cr_Guide_S_booked' => 'কুরিয়ারের কাছে অর্ডার আছে; এখনো কেউ সংগ্রহ করেনি। শুধু এই পর্যায়েই বুকিং বাতিল করা যায়।',
'Cr_Guide_S_picked_up' => 'কুরিয়ার পার্সেলটি সংগ্রহ করেছে।',
'Cr_Guide_S_in_transit' => 'হাবগুলোর মধ্যে চলাচলরত, কাস্টমসে বা আটকে আছে।',
'Cr_Guide_S_out_for_delivery' => 'আজ রাইডারের কাছে।',
'Cr_Guide_S_failed_attempt' => 'বাড়িতে কেউ নেই, গ্রহণে অস্বীকৃতি বা ভুল ঠিকানা। কুরিয়ার আবার চেষ্টা করবে বা ফেরত দেবে।',
'Cr_Guide_S_delivered' => 'ক্রেতার হাতে দেওয়া হয়েছে। COD পরিমাণ কুরিয়ার সংগ্রহ করেছে হিসেবে চিহ্নিত হয়।',
'Cr_Guide_S_returning' => 'আপনার কাছে ফেরত আসার পথে।',
'Cr_Guide_S_returned' => 'আপনার কাছে ফিরে এসেছে: এটি পর্যালোচনার অপেক্ষায় ফেরত অংশে থাকে, অথবা স্বয়ংক্রিয়ভাবে পুনরায় স্টকে নেওয়া হয়।',
'Cr_Guide_S_cancelled' => 'বুকিং বাতিল করা হয়েছে।',
'Cr_Guide_T_Booking' => 'অর্ডার বুকিং',
'Cr_Guide_B_Booking' => 'কুরিয়ারে পাঠান বিক্রয় থেকে ফর্মটি পূরণ করে: প্রাপক, ঠিকানা, COD হিসেবে বাকি পরিমাণ, এবং পণ্যের ওজন। নিজস্ব শহর তালিকা থাকা কুরিয়ারগুলো একটি বাছাই তালিকা দেখায়, এবং ওই শহরের জন্য আপনার পছন্দ মনে রাখা হয়। অ্যাগ্রিগেটর, DHL, FedEx, UPS ও Lalamove রেট তুলনা করুন সুবিধা দেয়: একটি দাম বেছে নিন এবং বুক করুন সেটি কিনে নেয়। বিক্রয় তালিকা থেকে একসাথে কয়েকটি বিক্রয় বুক করা যায়।',
'Cr_Guide_T_Cod' => 'ক্যাশ অন ডেলিভারি',
'Cr_Guide_B_Cod' => 'একটি COD পার্সেল সংগ্রহ হয়নি থেকে কুরিয়ার সংগ্রহ করেছে (ডেলিভারির সময়) হয়ে আপনাকে পরিশোধ করা হয়েছে পর্যায়ে যায়। যেসব কুরিয়ার পরিশোধের তথ্য জানায় তারা শেষ ধাপটি নিজেরাই সম্পন্ন করে; বাকিদের জন্য COD হালনাগাদ করুন ব্যবহার করুন। কুরিয়ার সেটিংসে একটি হিসাব বেছে নেওয়া থাকলে, পরিশোধটি বিক্রয়ে পেমেন্ট হিসেবে রেকর্ড হয়। পার্সেল সম্পন্ন হলে কুরিয়ার চার্জ ব্যয় হিসেবে সংরক্ষণ করা যায়।',
'Cr_Guide_T_Returns' => 'ফেরত আসা পার্সেল',
'Cr_Guide_B_Returns' => 'ডিফল্টভাবে ফেরত আসা পার্সেল কুরিয়ার শিপমেন্টের পর্যালোচনার অপেক্ষায় ফেরত অংশে থাকে। পুনরায় স্টকে নিন পুরো অর্ডারের জন্য বিক্রয় ফেরত তৈরি করে এবং আইটেমগুলো স্টকে ফিরিয়ে দেয়; বাদ দিন কিছুই ফেরত দেয় না, ক্ষতিগ্রস্ত বা হারানো পার্সেলের জন্য। কুরিয়ার সেটিংসে এর বদলে স্বয়ংক্রিয়ভাবে পুনরায় স্টকে নেওয়া যায়।',
'Cr_Guide_T_Customers' => 'ক্রেতার বার্তা ও ট্র্যাকিং পৃষ্ঠা',
'Cr_Guide_B_Customers' => 'কুরিয়ার সেটিংসের ক্রেতার নোটিফিকেশন আপনার টিক দেওয়া অবস্থাগুলোতে SMS, ইমেইল বা WhatsApp পাঠায়, প্রতি পার্সেলে একবার, আপনার নিজের লেখায়। আপনার অনলাইন স্টোরের ট্র্যাকিং পৃষ্ঠায় ক্রেতারা ট্র্যাকিং নম্বর, অথবা অর্ডার নম্বর ও ফোন দিয়ে পার্সেল অনুসরণ করতে পারেন। যেসব ক্রেতা প্রায়ই পার্সেল ফেরত দেন, বুকিংয়ের সময় তাদের পাশে ফেরত-ঝুঁকির ব্যাজ দেখায়।',
'Cr_Guide_T_Labels' => 'লেবেল',
'Cr_Guide_B_Labels' => 'কুরিয়ার নিজস্ব লেবেল দিলে (PDF, লিংক বা ছবি) লেবেল প্রিন্ট করুন সেটিই দেয়, নইলে ট্র্যাকিং বারকোড ও সংগ্রহের পরিমাণসহ একটি Stocky লেবেল দেয়। প্রিন্ট করতে এই সাইটের জন্য পপ-আপ অনুমতি দিন। DHL, FedEx ও UPS তাদের লেবেল শুধু একবার, বুকিংয়ের সময় দেয়, এবং Stocky পুনরায় প্রিন্টের জন্য সেটি রেখে দেয়।',
'Cr_Guide_T_Faq' => 'সমস্যা সমাধান',
'Cr_Guide_Q_Test' => 'সংযোগ পরীক্ষা ব্যর্থ হচ্ছে',
'Cr_Guide_A_Test' => 'টেস্ট-মোডের কী টেস্ট মোডের সাথে এবং লাইভ কী লাইভের সাথে ব্যবহার হয়; এগুলো আলাদা। সঠিক কারণ জানতে কুরিয়ার লগ খুলে কুরিয়ারের উত্তর পড়ুন।',
'Cr_Guide_Q_City' => 'কুরিয়ার শহর বা ঠিকানা গ্রহণ করছে না',
'Cr_Guide_A_City' => 'বুকিং ফর্মে কুরিয়ারের শহর তালিকা থেকে শহর বেছে নিন; কুরিয়ার শুধু নিজেদের নাম গ্রহণ করে। যেসব কুরিয়ার ডাক ঠিকানা নিয়ে কাজ করে তাদের রাজ্য, পোস্টাল কোড ও দুই অক্ষরের দেশ কোডও প্রয়োজন।',
'Cr_Guide_Q_Webhook' => 'অবস্থা নিজে থেকে বদলাচ্ছে না',
'Cr_Guide_A_Webhook' => 'যেসব কুরিয়ার পুশ করে, তাদের ক্ষেত্রে কুরিয়ারের কাছে ওয়েবহুক URL নিবন্ধিত আছে কি না দেখুন: কুরিয়ার লগে প্রতিটি প্রাপ্ত হালনাগাদ, অথবা কেন কোনোটি প্রত্যাখ্যাত হয়েছে (যেমন ভুল সিক্রেট) দেখা যায়। অন্য কুরিয়ারগুলো কুরিয়ার সেটিংসের সময়সূচিতে পরীক্ষা করা হয়, এবং এখনই অবস্থা দেখুন সঙ্গে সঙ্গে জিজ্ঞাসা করে।',
'Cr_Guide_Q_Stuck' => 'একটি শিপমেন্টে অবস্থা পরীক্ষার ত্রুটি দেখাচ্ছে',
'Cr_Guide_A_Stuck' => 'কুরিয়ার শেষ পরীক্ষাগুলো প্রত্যাখ্যান করেছে; কারণটি শিপমেন্টে ও কুরিয়ার লগে আছে। বারবার ব্যর্থ হলে শিপমেন্টটি আর স্বয়ংক্রিয়ভাবে পরীক্ষা করা হয় না: কারণটি ঠিক করুন, তারপর এখনই অবস্থা দেখুন ব্যবহার করুন।',
'Cr_Guide_Q_Label' => 'লেবেল প্রিন্ট করার সময় কিছুই খুলছে না',
'Cr_Guide_A_Label' => 'আপনার ব্রাউজার পপ-আপটি আটকে দিয়েছে। এই সাইটের জন্য পপ-আপ অনুমতি দিয়ে আবার চেষ্টা করুন।',
'Cr_Guide_Q_Cod' => 'একটি COD পরিশোধ বিক্রয়ে রেকর্ড হয়নি',
'Cr_Guide_A_Cod' => 'কুরিয়ার সেটিংসে ক্যাশ অন ডেলিভারির সুইচ চালু থাকা এবং একটি হিসাব বেছে নেওয়া প্রয়োজন। হিসাব ছাড়া পরিশোধ শুধু পরিশোধিত হিসেবে চিহ্নিত হয়।',
