'Restrict_Master_Data_By_Warehouse_Help' => 'চালু থাকলে, নির্দিষ্ট গুদামে নিযুক্ত ব্যবহারকারী শুধু সেই গুদামগুলোর সাথে সম্পর্কিত পণ্য, ক্রেতা, সরবরাহকারী, ব্র্যান্ড ও ক্যাটাগরি দেখতে পান। যেসব রেকর্ড এখনো কোথাও ব্যবহৃত হয়নি সেগুলো দৃশ্যমান থাকে, তাই নতুন তৈরি রেকর্ড কখনো লুকানো হয় না। বিক্রয়, ক্রয় ও ফেরত সবসময় সীমিত থাকে এবং এই সুইচ দ্বারা প্রভাবিত হয় না।',
'Restrict_Products_By_Warehouse' => 'গুদাম অনুযায়ী পণ্য সীমিত করুন',
'Restrict_Products_By_Warehouse_Help' => 'প্রতিটি পণ্যের একটি মূল গুদাম থাকে — যে শাখার জন্য এটি তৈরি করা হয়েছে। চালু থাকলে, নির্দিষ্ট গুদামে নিযুক্ত ব্যবহারকারী শুধু সেই পণ্যগুলো দেখতে, বিক্রি ও সম্পাদনা করতে পারেন যেগুলোর মূল গুদাম তাদের, এবং যেসব পণ্যের তাদের কোনো গুদামে প্রকৃত স্টক আছে (স্থানান্তরিত বা ক্রয়কৃত)। যেসব ব্যবহারকারী সব গুদামে প্রবেশ করতে পারেন তারা সবসময় সবকিছু দেখেন। অনলাইন স্টোরও একই নিয়ম মেনে চলে: এটি শুধু স্টোর সেটিংসে নির্বাচিত গুদামগুলোর পণ্য তালিকাভুক্ত করে।',
'Virtual_Combo_Stock' => 'ভার্চুয়াল কম্বো স্টক',
'Virtual_Combo_Stock_Help' => 'চালু থাকলে, কম্বো পণ্যের নিজস্ব কোনো স্টক থাকে না: এর প্রাপ্যতা হলো এর উপাদান পণ্যগুলো দিয়ে এখনো কতগুলো কম্বো পূরণ করা যায়, এবং কম্বো বিক্রি করলে উপাদানগুলো থেকে স্টক কমে। বন্ধ থাকলে, কম্বোগুলো প্রথমে একটি সমন্বয়ের মাধ্যমে স্টকে সংযোজন করতে হয়।',
'Virtual_Combo_Stock_Warning' => 'কম্বো বিক্রির আগেই এটি বেছে নেওয়া ভালো। কম্বো বিক্রি বা ফেরত হওয়ার পর পরিবর্তন করলে, ওই নথিগুলোর পরবর্তী সম্পাদনা, মুছে ফেলা ও ফেরত তাদের স্টক ভুলভাবে উল্টে দেয়।',
'Virtual_Combo_Stock_Confirm_On_Title' => 'ভার্চুয়াল কম্বো স্টক চালু করবেন?',
'Virtual_Combo_Stock_Confirm_On_Body' => 'কম্বোগুলো সরাসরি তাদের উপাদান পণ্য থেকে বিক্রি হবে, এবং তাদের নিজস্ব স্টক আর ব্যবহৃত হবে না।',
'Virtual_Combo_Stock_Confirm_Off_Title' => 'ভার্চুয়াল কম্বো স্টক বন্ধ করবেন?',
'Virtual_Combo_Stock_Confirm_Off_Body' => 'কম্বোগুলো তাদের নিজস্ব স্টকে ফিরে যাবে, যা বিক্রির আগে একটি সমন্বয়ের মাধ্যমে উপাদানগুলো থেকে সংযোজন করতে হবে।',
