'Default_Supplier_Hint' => 'সাধারণত যার কাছ থেকে আপনি এই পণ্যটি পুনরায় অর্ডার করেন। তাদের কাছ থেকে অর্ডার করার সব কিছু দেখতে পণ্য তালিকা সরবরাহকারী অনুযায়ী ফিল্টার করুন।',
