'Tg_Guide_GetUpdates_Note' => '{chatId} খুঁজুন। গ্রুপ বা চ্যানেলের ID ঋণাত্মক হয়, যেমন {example} — মাইনাস চিহ্নসহ পুরোটা কপি করুন।',
'Tg_Guide_Step3_Title' => 'এখানে সংযুক্ত করুন',
'Tg_Guide_Step3_Body' => '{settings} ট্যাবে বট টোকেন ও চ্যাট ID পেস্ট করুন, {allEvents} অথবা শুধু প্রয়োজনীয়গুলো ({events}…) বেছে নিন, {enable} চালু করে সংরক্ষণ করুন। তারপর {sendTest} চাপুন।',
'Tg_Guide_State_Enabled' => 'চালু',
'Tg_Guide_State_Saved_Off' => 'সংরক্ষিত, তবে বন্ধ',
'Tg_Guide_State_Not_Configured' => 'এখনো কনফিগার করা হয়নি',
'Tg_Guide_Chat_Id' => 'চ্যাট {id}',
'Tg_Guide_How_Sent' => 'বার্তা কীভাবে পাঠানো হয়',
'Tg_Guide_A_Title' => 'সঙ্গে সঙ্গে — কিছু ইনস্টল করতে হবে না',
'Tg_Guide_A_Body' => 'Stocky-তে সংরক্ষিত একটি বিক্রয়, ক্রয়, পেমেন্ট বা ব্যয় — POS-এ হোক বা অ্যাডমিনে — সংরক্ষণের {rightAfter} একই রিকোয়েস্টে Telegram-এ পাঠানো হয়। কোনো ক্রন এন্ট্রি বা কিউ ওয়ার্কার লাগে না, আর ক্যাশিয়ারকে কখনো Telegram-এর জন্য অপেক্ষা করতে হয় না: বার্তা যাওয়ার আগেই বিক্রয়ের উত্তর দেওয়া হয়ে যায়।',
'Tg_Guide_Right_After' => 'ঠিক পরেই',
'Tg_Guide_B_Title' => 'ক্রন এন্ট্রি — পুনরায় চেষ্টা ও ব্যাকগ্রাউন্ড ইভেন্টের জন্য',
'Tg_Guide_B_Body' => 'দুই ধরনের বার্তা বরং Telegram-এর নিজস্ব কিউতে অপেক্ষা করে: যে বার্তা পাঠানো ব্যর্থ হয়েছে (Telegram কিছুক্ষণের জন্য অপ্রাপ্য), যা পরের কয়েক মিনিটে আরও তিনবার পর্যন্ত পুনরায় চেষ্টা করা হয়; এবং অ্যাডমিনের বাইরে ঘটা ইভেন্ট — WooCommerce বা Shopify থেকে ইমপোর্টকৃত অর্ডার, artisan কমান্ড। এই ক্রন এন্ট্রি শুধু এগুলোই পাঠায়, আর কিছু নয়:',
'Tg_Guide_B_Note' => 'প্রতি মিনিটই ঠিক আছে: অপেক্ষমাণ কিছু না থাকলে রান সঙ্গে সঙ্গে শেষ হয়। cPanel-এ এটি {cronJobs}-এ বসবে — {php} পুরোনো হলে PHP 8.2+-এর পূর্ণ পাথ ব্যবহার করুন। Windows-এ Task Scheduler ব্যবহার করুন: প্রোগ্রাম {php2}, আর্গুমেন্ট {args}, শুরু হবে {path}-এ।',
'Tg_Guide_N_Waiting' => '{n}টি পাঠানোর অপেক্ষায়',
'Tg_Guide_Nothing_Waiting' => 'কিছুই অপেক্ষমাণ নেই',
'Tg_Guide_N_Gave_Up' => '{n}টি পুনরায় চেষ্টার পর বাদ দেওয়া হয়েছে',
'Tg_Guide_Growing_Hint' => '— এই সংখ্যা বাড়তে থাকলে ক্রন এন্ট্রি চলছে না।',
'Tg_Guide_Without_Cron' => 'ক্রন এন্ট্রি ছাড়াও Stocky-তে সংরক্ষিত সবকিছু সঙ্গে সঙ্গে পৌঁছায়; শুধু পুনরায় চেষ্টা ও ইমপোর্টকৃত অর্ডার হারাবেন।',
'Tg_Guide_Else_Title' => 'বাকি সবকিছু',
'Tg_Guide_Else_Body' => 'ব্যাকগ্রাউন্ডে ঘটা ইভেন্টের বার্তা প্ল্যাটফর্ম নিজেই পৌঁছে দেয় — কিছুই সেটআপ করতে হবে না।',
'Tg_Guide_Not_Arrive' => 'যদি বার্তা না পৌঁছায়',
'Tg_Guide_Err_401' => '{code} — বট টোকেন ভুল। BotFather থেকে আবার পেস্ট করুন।',
'Tg_Guide_Err_400' => '{code} — চ্যাট ID ভুল, অথবা বটটি গ্রুপে নেই। ব্যক্তিগত চ্যাটের জন্য আগে বটকে বার্তা দিন।',
'Tg_Guide_Err_403' => '{code} — বটটিকে আবার গ্রুপে যোগ করুন, অথবা চ্যানেলের অ্যাডমিন হিসেবে যোগ করুন।',
'Tg_Guide_Test_Works' => 'পরীক্ষা কাজ করে কিন্তু বিক্রয় আসে না',
'Tg_Guide_Test_Works_Item' => '{label} — ইভেন্টটিতে টিক দেওয়া আছে কিনা (অথবা {allEvents} বেছে নেওয়া আছে কিনা) এবং সুইচ চালু আছে কিনা দেখুন।',
'Tg_Guide_Imported_Never' => 'ইমপোর্টকৃত অর্ডার কখনো আসে না',
