'Jumia_Hero_Title' => 'Jumia মার্কেটপ্লেস সিঙ্ক',
'Jumia_Hero_Desc' => 'আপনার Jumia Seller Center তালিকায় মূল্য ও স্টক পাঠান এবং মার্কেটপ্লেসের অর্ডার বিক্রয় হিসেবে ইমপোর্ট করুন।',
