'Jumia_Account_Email' => 'অ্যাকাউন্টের ইমেইল (User ID)',
'Jumia_Prices_Stock' => 'মূল্য ও স্টক',
'Jumia_Push_Card_Title' => 'Jumia-তে মূল্য ও স্টক পাঠান',
'Jumia_Push_Desc' => 'যেসব পণ্যের (ও ভ্যারিয়েন্টের) SKU Jumia তালিকার {sellerSku}-এর সাথে মেলে, সেগুলোর বর্তমান মূল্য ও পরিমাণ পাঠায়। হালনাগাদগুলো Seller Center ফিড হিসেবে জমা হয় এবং অ্যাসিঙ্ক্রোনাসভাবে প্রয়োগ হয় — ফিড ID লগ ট্যাবে রেকর্ড হয়, আর প্রতিটি আইটেমের প্রত্যাখ্যান Seller Center-এর ফিড স্ট্যাটাস স্ক্রিনে দেখা যায়।',
'Jumia_Push_Prices_Stock' => 'মূল্য ও স্টক পাঠান',
'Jumia_Orders_Desc' => 'মার্কেটপ্লেসের অর্ডার বিক্রয় হিসেবে ইমপোর্ট করে ({ref}-এর মতো রেফারেন্সসহ), Seller SKU দিয়ে আপনার পণ্যের সাথে মিলিয়ে। আগে ইমপোর্টকৃত ও বাতিল অর্ডার বাদ দেওয়া হয়, তাই নিয়মিত আনা নিরাপদ। শুধু ডেলিভারি হওয়া অর্ডারের পেমেন্ট পরিশোধিত হিসেবে চিহ্নিত হয় (Jumia-তে মূলত COD)।',
'Jumia_Guide_1' => 'Jumia {sellerCenter}-এ Settings → {integrationMgmt} খুলে একটি API কী তৈরি করুন।',
'Jumia_Guide_2' => 'আপনার দেশের API URL (যেমন নাইজেরিয়ার জন্য {ng}, কেনিয়ার জন্য {ke}, মিশরের জন্য {eg}), আপনার Seller Center অ্যাকাউন্টের ইমেইল এবং কী লিখুন — তারপর {test} চালান।',
'Jumia_Guide_3' => 'নিশ্চিত করুন প্রতিটি Jumia তালিকার {sellerSku} Stocky-র পণ্য কোডের সমান — স্টক পাঠানো ও অর্ডার মেলানো দুটোতেই এটিই পরিচয় হিসেবে ব্যবহৃত হয়।',
'Jumia_Guide_4' => 'ইনভেন্টরি বদলানোর পর মূল্য ও স্টক পাঠান; নিয়মিত অর্ডার আনুন (এই API-তে Jumia-র কোনো ওয়েবহুক নেই)।',
'Jumia_Guide_5' => 'নতুন তালিকা তৈরি Seller Center-এই থাকে — Jumia-তে ক্যাটাগরি-নির্দিষ্ট অ্যাট্রিবিউট ও ছবি পর্যালোচনা লাগে, যা শুধু তাদের পোর্টালই ভালোভাবে সামলায়।',
'Mc_Hero_Title' => 'Mailchimp অডিয়েন্স সিঙ্ক',
'Mc_Hero_Desc' => 'একটি Mailchimp অডিয়েন্স আপনার ক্রেতাদের দিয়ে পূর্ণ রাখুন, যাতে আপনার প্রকৃত ক্রেতাদের নিয়ে ইমেইল ক্যাম্পেইন চালাতে পারেন।',
'Mc_Account_Audience' => 'অ্যাকাউন্ট ও অডিয়েন্স',
'Mc_Api_Key_Placeholder' => 'যেমন a1b2c3…-us14 (Account → Extras → API keys)',
'Mc_Audience' => 'অডিয়েন্স',
'Mc_N_Members' => '({n} জন সদস্য)',
'Mc_Load_Audiences_To_Pick' => 'একটি বেছে নিতে অডিয়েন্স লোড করুন',
'Mc_Load_Audiences' => 'অডিয়েন্স লোড করুন',
'Mc_Double_Opt_In_Label' => 'ডাবল অপট-ইন — নতুন সদস্যরা যোগ দেওয়ার আগে একটি নিশ্চিতকরণ ইমেইল পাবেন',
'Mc_Recommended_GDPR' => '(GDPR-এর জন্য প্রস্তাবিত)',
'Mc_Auto_Sync_New' => 'নতুন ক্রেতা তৈরি হওয়ার সাথে সাথে স্বয়ংক্রিয়ভাবে সিঙ্ক করুন',
'Mc_With_Email' => 'ইমেইলসহ',
'Mc_Push_Desc' => 'ইমেইল ঠিকানা আছে এমন প্রত্যেক ক্রেতাকে (নাম ও ফোনসহ) নির্বাচিত অডিয়েন্সে যোগ বা হালনাগাদ করে। বিদ্যমান সদস্যদের সাবস্ক্রিপশন অবস্থা অপরিবর্তিত থাকে — যারা আনসাবস্ক্রাইব করেছেন তাদের আবার সাবস্ক্রাইব করা হয় না। ইমেইল ছাড়া ক্রেতারা বাদ থাকেন।',
'Mc_Double_Opt_In_Off' => 'ডাবল অপট-ইন বন্ধ',
'Mc_Double_Opt_In_Off_Desc' => 'নতুন সদস্যরা নিশ্চিতকরণ ইমেইল ছাড়াই সাবস্ক্রাইবড হিসেবে যুক্ত হবেন। শুধু সেইসব ক্রেতার জন্য এটি করুন যারা ইতিমধ্যে মার্কেটিং বার্তা পেতে সম্মতি দিয়েছেন।',
'Mc_Guide_1' => 'Mailchimp-এ {path} খুলুন এবং একটি কী তৈরি করুন (এটি {suffix} দিয়ে শেষ হয় — সেই অংশটিই আপনার ডেটাসেন্টার)।',
'Mc_Guide_2' => 'কীটি এখানে পেস্ট করে সংরক্ষণ করুন, তারপর {load}-এ ক্লিক করে যে অডিয়েন্স পূর্ণ করবেন সেটি বেছে নিন।',
'Mc_Guide_3' => 'আপনার ক্রেতারা ইতিমধ্যে মার্কেটিং ইমেইলে সম্মতি না দিয়ে থাকলে {doi} চালু রাখুন।',
'Mc_Double_Opt_In_Lower' => 'ডাবল অপট-ইন',
'Mc_Guide_4' => 'প্রাথমিকভাবে পূর্ণ করতে {push} চালান; নতুন ক্রেতারা যেন স্বয়ংক্রিয়ভাবে যুক্ত হন সেজন্য {autoSync} চালু করুন।',
'Mc_Auto_Sync_Lower' => 'স্বয়ংক্রিয় সিঙ্ক',
'Mc_Consent_Matters' => 'সম্মতি গুরুত্বপূর্ণ',
'Mc_Consent_Desc' => 'যারা কখনো মার্কেটিংয়ে সম্মতি দেননি তাদের ইমেইল পাঠালে GDPR/CAN-SPAM লঙ্ঘন হতে পারে এবং আপনার Mailchimp অ্যাকাউন্ট স্থগিত হতে পারে। ডাবল অপট-ইন নিশ্চিতকরণের দায়িত্ব Mailchimp-কে দেয় — এটিই নিরাপদ ডিফল্ট।',
'Mc_No_Audiences' => 'এই অ্যাকাউন্টে কোনো অডিয়েন্স পাওয়া যায়নি।',
'Presta_Hero_Desc' => 'PrestaShop-এর webservice API-এর মাধ্যমে আপনার স্টোরের সাথে পণ্য, স্টক ও অর্ডার সিঙ্ক করুন।',
'Presta_Webservice_Key' => 'Webservice কী',
'Presta_Key_Placeholder' => 'Advanced Parameters → Webservice থেকে',
'Presta_Key_Help' => 'PrestaShop-এ webservice চালু করুন (Advanced Parameters → Webservice), products, stock_availables, orders ও customers-এ অনুমতিসহ একটি কী তৈরি করুন এবং এখানে পেস্ট করুন। শুধু-লেখা হিসেবে সংরক্ষিত।',
'Presta_Shop_Language_ID' => 'শপের ভাষার ID',
'Presta_Language_Help' => 'পাঠানোর সময় পণ্যের নামের জন্য ব্যবহৃত ভাষার id (1 = শপের প্রথম ভাষা)।',
'Presta_Push_Desc' => 'PrestaShop-এ অনুপস্থিত সাধারণ পণ্যগুলো (বর্তমান স্টকসহ) তৈরি করে। আগে থেকে যুক্ত পণ্য ও ভ্যারিয়েন্ট পণ্য বাদ দেওয়া হয় — পণ্যের বিবরণ PrestaShop-এই সম্পাদনা করুন, অথবা স্থানীয় কপি হালনাগাদ করতে আনুন।',
'Presta_Pull_Desc' => 'PrestaShop-এর পণ্য ইমপোর্ট করে, বিদ্যমানগুলোর সাথে রেফারেন্স (SKU) দিয়ে মিলিয়ে এবং বাকিগুলো তৈরি করে। কম্বিনেশনগুলো তাদের মূল পণ্য হিসেবে ইমপোর্ট হয়।',
'Presta_Reset_Confirm' => 'পণ্যের লিংক রিসেট করবেন? অর্ডারের ইতিহাসে লিংক থেকে যাবে।',
'Presta_Stock_Desc' => 'প্রতিটি যুক্ত পণ্যের জন্য শপের স্টক (stock_availables) হালনাগাদ করে।',
'Presta_Orders_Desc' => 'শপের অর্ডার বিক্রয় হিসেবে ইমপোর্ট করে ({ref}-এর মতো রেফারেন্সসহ), নতুনগুলো আগে। আগে ইমপোর্টকৃত ও বাতিল অর্ডার বাদ দেওয়া হয়, তাই নিয়মিত আনা নিরাপদ। PrestaShop-এ কোনো ওয়েবহুক নেই — ব্যস্ত সময়ের পরে এটি চালান।',
'Presta_Guide_1' => 'আপনার PrestaShop ব্যাক অফিসে {path} খুলে webservice চালু করুন।',
'Presta_Guide_2' => 'একটি নতুন কী যোগ করুন, {products} ও {stock}-এ {vae} এবং {orders} ও {customers}-এ {view} অনুমতি দিয়ে।',
'Presta_Guide_3' => 'সংযোগ ট্যাবে স্টোরের URL ও কী পেস্ট করুন, সংরক্ষণ করুন এবং {test} চালান।',
'Presta_Guide_4' => 'শপে আগে থেকেই ক্যাটালগ থাকলে প্রথমে পণ্য আনুন (রেফারেন্স/SKU দিয়ে মেলে); অনুপস্থিত সাধারণ পণ্য তৈরি করতে পাঠান।',
'Presta_Guide_5' => 'পরিমাণ বদলালেই স্টক পাঠান এবং নিয়মিত অর্ডার আনুন — PrestaShop-এ কোনো ওয়েবহুক নেই, তাই আপনি আনলেই কেবল অর্ডার আসে।',
'Presta_Identity_Title' => 'পণ্যের পরিচয় হলো রেফারেন্স (SKU)',
'Presta_Identity_Desc' => 'Stocky-র পণ্য কোড PrestaShop-এর রেফারেন্সের সাথে মেলানো হয়। দুই দিকেই রেফারেন্স সামঞ্জস্যপূর্ণ রাখুন; কম্বিনেশন (ভ্যারিয়েন্ট) অর্ডারে রেফারেন্স দিয়ে মেলানো হয়, তবে এই সংস্করণে পাঠানো হয় না।',
