'Gs_Guide_2' => '{consent} কনফিগার করুন (External)। এটি "Testing" অবস্থায় থাকা পর্যন্ত আপনার Google অ্যাকাউন্টকে টেস্ট ইউজার হিসেবে যোগ করুন — মনে রাখবেন, টেস্টিং মোডের রিফ্রেশ টোকেনের মেয়াদ ৭ দিন পর শেষ হয়, তাই স্থায়ী সংযোগের জন্য অ্যাপটি {publish} করুন।',
