'Xero_Push_Invoices_Desc' => 'প্রতিটি বিক্রয়ের জন্য একটি AUTHORISED চালান তৈরি করে (চালান নম্বর = বিক্রয়ের রেফ), বিক্রয়ের লাইন আইটেমের সাথে ডেলিভারি, ছাড় ও কর লাইনসহ, যাতে Xero-র মোট বিক্রয়ের মোটের সমান হয়। Xero-তে আগে থেকে থাকা বিক্রয় বাদ দেওয়া হয় — চালান কখনো সম্পাদনা করা হয় না। অনুপস্থিত কন্টাক্ট তাৎক্ষণিকভাবে তৈরি হয়।',
