'Xero_Guide_2' => 'সংযোগ ট্যাবে দেখানো রিডাইরেক্ট URI নিবন্ধন করুন।',
'Xero_Guide_3' => 'অ্যাপের {clientId} কপি করুন এবং একটি {clientSecret} তৈরি করুন; দুটোই এখানে পেস্ট করে সংরক্ষণ করুন।',
'Xero_Guide_4' => '{connect}-এ ক্লিক করুন, সাইন ইন করুন এবং সংযুক্ত করার প্রতিষ্ঠান বেছে নিন।',
'Xero_Guide_5' => 'হিসাবের কোডগুলো যাচাই করুন: বিক্রয় হিসাবে চালানের লাইন যায়; পরিশোধিত বিক্রয়ে পেমেন্টও রেকর্ড করতে চাইলে একটি ব্যাংক হিসাবের কোড দিন।',
'Xero_Guide_6' => 'প্রথমে ক্রেতা, তারপর চালান পাঠান। চালান নম্বর হলো বিক্রয়ের রেফ, তাই লিংক রিসেট করলেও Xero ডুপ্লিকেট প্রত্যাখ্যান করে।',
'Xero_Tax_Inclusive_Title' => 'পরিমাণ করসহ যেমন আছে তেমনই পাঠানো হয়',
'Xero_Tax_Inclusive_Desc' => 'চালানে NoTax লাইন ব্যবহার হয় যা বিক্রয়কে হুবহু প্রতিফলিত করে (আইটেম + ডেলিভারি − ছাড় + কর), তাই Xero-র মোট সবসময় Stocky-র মোটের সমান। আপনার হিসাবরক্ষক Xero-র ভেতরে কর ও ডেলিভারি লাইন সঠিক হিসাবে পুনঃনির্ধারণ করতে পারেন।',
