'Salla_Push_Desc' => 'SKU দিয়ে Salla-তে সাধারণ পণ্য তৈরি বা হালনাগাদ করে। এই সংস্করণে ভ্যারিয়েন্ট পণ্য বাদ দেওয়া হয় — সেগুলো Salla থেকে আনুন, অথবা SKU দিয়ে মেলান।',
