'Salla_Reset_Confirm' => 'পণ্য ও ভ্যারিয়েন্টের লিংক রিসেট করবেন? অর্ডারের ইতিহাসে লিংক থেকে যাবে।',
'Salla_Stock_Desc' => 'প্রতিটি যুক্ত পণ্য (SKU দিয়ে) ও যুক্ত ভ্যারিয়েন্টের বর্তমান পরিমাণ পাঠায়।',
'Salla_Orders_Desc' => 'নতুন Salla অর্ডার সাধারণত ওয়েবহুকের মাধ্যমে নিজে থেকেই এসে বিক্রয়ে পরিণত হয়। ওয়েবহুক সেটআপের আগে দেওয়া অর্ডার পূরণ করতে এটি দিয়ে আনুন — আগে ইমপোর্টকৃত অর্ডার বাদ দেওয়া হয়।',
'Salla_Guide_1' => '{link}-এ একটি (প্রাইভেট) অ্যাপ তৈরি করুন এবং {mode} অনুমোদন পদ্ধতি বেছে নিন।',
'Salla_Guide_2' => 'অ্যাপের {clientId} ও {clientSecret} সংযোগ ট্যাবে কপি করে সংরক্ষণ করুন।',
'Salla_Guide_3' => 'অ্যাপের সেটিংসে সংযোগ ট্যাবে দেখানো OAuth কলব্যাক URL সেট করুন।',
'Salla_Guide_4' => 'অ্যাপের Webhooks পেজে: {signature} নিরাপত্তা পদ্ধতি বেছে নিন, এর সিক্রেট এখানকার ওয়েবহুক সিক্রেট ফিল্ডে কপি করুন, সংযোগ ট্যাবে দেখানো ওয়েবহুক URL সেট করুন এবং অন্তত {e1}, {e2}, {e3}, {e4}, {e5} ও {e6}-এ সাবস্ক্রাইব করুন।',
'Salla_Guide_5' => '{connect}-এ ক্লিক করে আপনার স্টোরে অ্যাপটি অনুমোদন করুন। (Easy Mode-এর অ্যাপগুলো এর বদলে {webhook} ওয়েবহুকের মাধ্যমে স্বয়ংক্রিয়ভাবে সংযুক্ত হয়।)',
'Salla_Guide_6' => 'পণ্য আনুন বা পাঠান, তারপর স্টক পাঠান। নতুন অর্ডার স্বয়ংক্রিয়ভাবে আসে এবং {ref}-এর মতো রেফারেন্সসহ বিক্রয়ের অধীনে দেখা যায়।',
'Salla_Identity_Title' => 'পণ্যের পরিচয় হলো SKU',
'Salla_Identity_Desc' => 'Stocky-র পণ্য কোড Salla-র SKU-এর সাথে মেলানো হয়। দুই দিকেই SKU সামঞ্জস্যপূর্ণ রাখুন; ভ্যারিয়েন্ট পণ্য আনার সময় ও অর্ডারে মেলানো হয়, তবে এই সংস্করণে পাঠানো হয় না।',
