'Fbr_Token_Placeholder' => 'PRAL / IRIS ই-ইনভয়েসিং পোর্টাল থেকে টোকেনটি পেস্ট করুন',
'Fbr_Guide_What_Title' => 'FBR ডিজিটাল ইনভয়েসিং কী?',
'Fbr_Guide_What_Body' => 'SRO 69(I)/2025 অনুযায়ী, ফেডারেল বোর্ড অব রেভিনিউ (পাকিস্তান) সমন্বিত ব্যবসাগুলোকে PRAL ডিজিটাল ইনভয়েসিং (DI) API-এর মাধ্যমে রিয়েল টাইমে বিক্রয় চালান ইলেকট্রনিকভাবে জানাতে বাধ্য করে। প্রতিটি গৃহীত বিক্রয় একটি দাপ্তরিক FBR চালান নম্বর পায়, এবং রসিদে সেই নম্বরের সাথে একটি যাচাইকরণ QR কোড দেখাতে হবে।',
'Fbr_Guide_Steps_Title' => 'চালু করার ধাপসমূহ',
'Fbr_Guide_Step_1' => 'FBR IRIS ই-ইনভয়েসিং পোর্টালে নিবন্ধন করুন এবং একটি {sandbox} সিকিউরিটি টোকেন সংগ্রহ করুন।',
'Fbr_Guide_Step_2' => 'কনফিগারেশন ট্যাবে আপনার বিক্রেতার প্রোফাইল (NTN/CNIC, ব্যবসার নাম, প্রদেশ, ঠিকানা) কনফিগার করুন, টোকেন পেস্ট করুন এবং পরিবেশ {sandbox}-এ রেখে ইন্টিগ্রেশন চালু করুন।',
'Fbr_Guide_Step_3' => 'FBR আপনাকে যে সিনারিও বরাদ্দ করেছে তা অনুযায়ী পরীক্ষামূলক বিক্রয় করুন (স্যান্ডবক্স সিনারিও ফিল্ডে সিনারিও বেছে নিন)। সেগুলো {valid} হিসেবে ফিরে আসছে কিনা নিশ্চিত হতে নথি ট্যাব দেখুন।',
'Fbr_Guide_Step_4' => 'FBR আপনার স্যান্ডবক্স পরীক্ষা অনুমোদন করলে পোর্টাল থেকে {production} টোকেন সংগ্রহ করুন, এখানে পেস্ট করুন এবং পরিবেশ {production}-এ পরিবর্তন করুন।',
'Fbr_Guide_Step_5' => 'বিক্রয় গৃহীত হলে রসিদে স্বয়ংক্রিয়ভাবে FBR চালান নম্বর ও QR কোড দেখানো হয় — পয়েন্ট অফ সেলে কোনো অতিরিক্ত ধাপের প্রয়োজন নেই।',
'Fbr_Sandbox_Lower' => 'স্যান্ডবক্স',
'Fbr_Production_Lower' => 'প্রোডাকশন',
'Fbr_Guide_Note_1' => 'পণ্য ফর্মে প্রতিটি পণ্যের HS কোড নির্ধারণ করুন (ফিল্ড "HS কোড")। এখানে কনফিগার করা ডিফল্ট HS কোড শুধু HS কোডবিহীন পণ্যের জন্য ব্যবহৃত হয়।',
