'Woo_Automatic_Sync' => 'স্বয়ংক্রিয় সিঙ্ক',
'Woo_Auto_Sync_Intro' => 'এই পেজ না খুলেই Stocky-তে করা পরিবর্তনগুলো ঘটার সাথে সাথে WooCommerce-এ পাঠান। প্রতিটি পুশ কাজটি সংরক্ষণের ঠিক পরে চলে, তাই ক্যাশিয়ারকে কখনো WooCommerce-এর জন্য অপেক্ষা করতে হয় না। ফলাফল লগ ট্যাবে দেখা যায়।',
'Woo_Auto_Sync_Products_Help' => 'Stocky-তে তৈরি, সম্পাদিত বা ডুপ্লিকেট করা পণ্য WooCommerce-এ পাঠানো হয় (বিবরণ, দাম, ভ্যারিয়েন্ট, ছবি, স্টক)। বাল্ক ইমপোর্ট পুশ করা হয় না; ইমপোর্টের পর পণ্য ট্যাবে সিঙ্ক — POS → WooCommerce ব্যবহার করুন।',
'Woo_Auto_Sync_Stock_Help' => 'যেকোনো স্টক চলাচল (POS বিক্রয়, বিক্রয়, ফেরত, ক্রয়, সমন্বয়, স্থানান্তর) WooCommerce-এ সংশ্লিষ্ট পণ্যের পরিমাণ হালনাগাদ করে। শুধু WooCommerce-এর সাথে আগে থেকে সংযুক্ত পণ্যগুলো হালনাগাদ হয়।',
'Woo_Sync_Tuning' => 'সিঙ্ক টিউনিং',
'Woo_Sync_Tuning_Intro' => 'ডিফল্ট মানগুলো বেশিরভাগ স্টোরের জন্য উপযুক্ত। আপনার হোস্টিংয়ে সিঙ্ক ধীর হলে বা টাইম আউট হলে তবেই এগুলো পরিবর্তন করুন। প্রতিটি মান একটি নিরাপদ সীমার মধ্যে রাখা হয়, এবং কোনো ফিল্ড খালি করলে তার ডিফল্ট মান ফিরে আসে।',
'Woo_Sync_Guide' => 'WooCommerce সিঙ্ক নির্দেশিকা',
'Woo_Guide_Getting_Keys' => 'API কী সংগ্রহ',
'Woo_Guide_Keys_1' => 'WooCommerce-এ: WooCommerce → Settings → Advanced → REST API।',
'Woo_Guide_Keys_2' => 'Add key করুন, Read/Write বেছে নিন, তারপর Consumer key ও Consumer secret কপি করুন।',
'Woo_Guide_Keys_3' => 'স্টোরের URL: শেষে স্ল্যাশ ছাড়া আপনার সাইটের URL (যেমন {example})।',
'Woo_Guide_WP_Title' => 'WP ব্যবহারকারীর নাম ও অ্যাপ্লিকেশন পাসওয়ার্ড (ঐচ্ছিক)',
'Woo_Guide_WP_Intro' => 'এই ফিল্ডগুলো শুধু পণ্যের ছবির জন্য ব্যবহৃত হয়। WooCommerce API (স্টোরের URL + Consumer key/secret) পণ্য, স্টক, ক্যাটাগরি, ব্র্যান্ড, ক্রেতা ও অর্ডারের সিঙ্ক পরিচালনা করে; WordPress REST API মিডিয়া লাইব্রেরি পরিচালনা করে (ছবি খোঁজা ও আপলোড)।',
'Woo_Guide_WP_1' => 'পণ্য বা স্টক সিঙ্ক করার সময় Stocky পণ্যের ছবি সংযুক্ত করতে পারে: প্রথমে ফাইলের নাম দিয়ে WordPress মিডিয়া লাইব্রেরিতে বিদ্যমান ছবি খোঁজে; না পেলে WordPress API-এর মাধ্যমে ছবিটি আপলোড করে।',
'Woo_Guide_WP_2' => 'এমন একজন WordPress ব্যবহারকারী ব্যবহার করুন যিনি মিডিয়া পরিচালনা করতে পারেন (যেমন Administrator)। WordPress-এ একটি অ্যাপ্লিকেশন পাসওয়ার্ড তৈরি করুন: Users → Profile (বা আপনার ব্যবহারকারী) → Application Passwords — একটি নতুন যোগ করে এখানে পেস্ট করুন।',
'Woo_Guide_WP_3' => 'এগুলো খালি রাখলেও সব ডেটার (পণ্য, স্টক, ক্যাটাগরি, ব্র্যান্ড, ক্রেতা, অর্ডার) সিঙ্ক কাজ করবে; শুধু পণ্যের ছবি সংযুক্তি (খোঁজা/আপলোড) বাদ যাবে।',
'Woo_Guide_How_To_Enable' => 'কীভাবে চালু করবেন',
'Woo_Guide_Enable_1' => 'উপরে স্টোরের URL, Consumer key ও Consumer secret লিখুন, তারপর সংরক্ষণ-এ ক্লিক করুন।',
'Woo_Guide_Enable_2' => 'ক্রেডেনশিয়াল যাচাই করতে সংযোগ পরীক্ষা ব্যবহার করুন।',
'Woo_Guide_Enable_3' => 'যখন সিঙ্ক প্রয়োজন তখন যেকোনো ট্যাব থেকে ম্যানুয়াল সিঙ্ক ব্যবহার করুন।',
'Woo_Guide_Enable_4' => 'নতুন ও সম্পাদিত পণ্য এবং প্রতিটি স্টক পরিবর্তন ঘটার সাথে সাথে WooCommerce-এ পাঠাতে উপরে স্বয়ংক্রিয় সিঙ্ক চালু করুন।',
'Woo_Guide_Manual_Sync' => 'ম্যানুয়াল সিঙ্ক (প্রয়োজন অনুযায়ী)',
'Woo_Guide_Manual_1' => 'সিঙ্ক উভয় দিকে কাজ করে: Stocky → WooCommerce এবং WooCommerce → Stocky।',
'Woo_Guide_Manual_2' => 'সব WooCommerce ট্যাবে (পণ্য, স্টক ইত্যাদি) ম্যানুয়াল সিঙ্ক পাওয়া যায়; প্রয়োজন অনুযায়ী সিঙ্ক চালাতে প্রতিটি ট্যাবের সিঙ্ক অপশন ব্যবহার করুন।',
'Woo_Guide_Auto_1' => 'পণ্য: চালু থাকলে, Stocky-তে আপনার তৈরি, সম্পাদিত বা ডুপ্লিকেট করা পণ্য সংরক্ষণের ঠিক পরে WooCommerce-এ পাঠানো হয়, তারপর তার স্টক।',
'Woo_Guide_Auto_2' => 'স্টক: চালু থাকলে, প্রতিটি স্টক পরিবর্তন (POS বিক্রয়, বিক্রয়, ফেরত, ক্রয়, সমন্বয়, স্থানান্তর) WooCommerce-এ পরিমাণ হালনাগাদ করে। শুধু WooCommerce-এর সাথে আগে থেকে সংযুক্ত পণ্যগুলো হালনাগাদ হয়।',
'Woo_Guide_Auto_3' => 'স্বয়ংক্রিয় সিঙ্ক শুধু Stocky থেকে WooCommerce-এ পরিবর্তন পাঠায়। WooCommerce থেকে Stocky-তে ডেটা আনা (অর্ডার, ক্রেতা, পণ্য) সবসময় অর্ডার, ক্রেতা ও পণ্য ট্যাবের বোতাম দিয়ে করা হয়।',
'Woo_Guide_Auto_4' => 'বাল্ক পণ্য ইমপোর্ট স্বয়ংক্রিয়ভাবে পাঠানো হয় না। ইমপোর্টের পর পণ্য ট্যাবে সিঙ্ক — POS → WooCommerce ব্যবহার করুন।',
'Woo_Guide_Auto_5' => 'প্রতিটি স্বয়ংক্রিয় পুশ লগ ট্যাবে রেকর্ড করা হয়, তাই কী পাঠানো হয়েছে তা দেখতে ও ত্রুটি শনাক্ত করতে পারেন।',
'Woo_Guide_First_Setup' => 'প্রথমবারের সেটআপ',
'Woo_Guide_First_1' => 'আপনার বিদ্যমান ক্যাটালগ সংযুক্ত করতে এগুলো একবার, এই ক্রমে চালান: ক্যাটাগরি ট্যাবে সিঙ্ক — POS → WooCommerce, তারপর ব্র্যান্ড ট্যাব, তারপর পণ্য ট্যাব, এবং শেষে স্টক ট্যাবে স্টক সিঙ্ক করুন। এরপর WooCommerce হালনাগাদ রাখতে উপরে স্বয়ংক্রিয় সিঙ্ক চালু করুন।',
'Woo_Guide_First_2' => 'বড় পণ্য ও স্টক সিঙ্ক ছোট ছোট ব্যাচে চলে এবং ট্যাবে অগ্রগতি দেখায়। সিঙ্ক শেষ না হওয়া পর্যন্ত পেজটি খোলা রাখুন; যেকোনো সময় এটি থামাতে পারেন।',
'Woo_Guide_First_3' => 'কয়েক মিনিট ধরে সিঙ্ক এগোচ্ছে না মনে হলে লগ ট্যাব দেখুন, তারপর সাপোর্টের সাথে যোগাযোগ করুন।',
'Woo_Guide_Notes_1' => 'স্টোরের URL বা API কী পরিবর্তন করলে ম্যাপিং (পণ্য, ক্যাটাগরি, ব্র্যান্ড, ক্রেতা) রিসেট হয়; আইটেমগুলো (নতুন) স্টোরে আবার সিঙ্ক হবে।',
'Woo_Guide_Notes_2' => 'ডুপ্লিকেট পণ্য এড়াতে ও নিরাপদে পুনরায় সংযুক্ত করতে Stocky ও WooCommerce-এর মধ্যে SKU একই রাখুন।',
