'Pg_Store_Feature_Not_In_Plan' => 'অনলাইন স্টোরের গেটওয়ে ও অফলাইন পেমেন্ট পদ্ধতি অনলাইন অর্ডার ফিচারের অংশ, যা আপনার বর্তমান প্ল্যানে অন্তর্ভুক্ত নেই।',
'Pg_Intro_Title' => 'এখানকার প্রতিটি গেটওয়ে অনলাইন স্টোরের চেকআউটে দেখানো হয়, যখন এর ক্রেডেনশিয়াল সংরক্ষিত থাকে এবং সুইচ চালু থাকে।',
'Pg_Intro_Desc' => 'প্রতিটি ট্যাবের নিজস্ব চালু/বন্ধ সুইচ আছে, যা টগল করার সঙ্গে সঙ্গেই সংরক্ষিত হয়: কোনো গেটওয়ে বন্ধ করলে এর ক্রেডেনশিয়াল থেকে যায়, চেকআউটে শুধু এটি দেখানো বন্ধ হয়। Stripe কী সব জায়গায় যৌথভাবে ব্যবহৃত হয় (অ্যাডমিন ও অনলাইন স্টোর একই Stripe ইন্টিগ্রেশন ব্যবহার করে)। অফলাইন পেমেন্টে ক্যাশ অন ডেলিভারি ও মোবাইল মানি রয়েছে, যা সিস্টেমের বাইরে পরিশোধ করা হয়।',
'Pg_Label_Stripe_Key' => 'Stripe কী',
'Pg_Label_Stripe_Secret' => 'Stripe সিক্রেট',
