'Pg_Label_Razorpay_Key_Id' => 'Razorpay কী ID',
'Pg_Label_Razorpay_Key_Secret' => 'Razorpay কী সিক্রেট',
'Pg_Razorpay_Help' => 'স্টোরফ্রন্টে Razorpay Checkout ব্যবহার করে (কার্ড, UPI, নেটব্যাংকিং, ওয়ালেট)। টেস্ট নাকি লাইভ, তা কী-জোড়া দিয়ে নির্ধারিত হয় (rzp_test_/rzp_live_) — আলাদা কোনো স্যান্ডবক্স সুইচ নেই। দুটি কী সংরক্ষিত হলেই চেকআউটে Razorpay দেখানো হয়।',
