'Pg_Bkash_Sandbox_Help' => 'চালু থাকলে আপনার স্যান্ডবক্স ক্রেডেনশিয়াল দিয়ে tokenized.sandbox.bka.sh ব্যবহার হয়; tokenized.pay.bka.sh-এ আসল bKash অ্যাকাউন্টে চার্জ করতে বন্ধ করুন।',
'Pg_Bkash_Help' => 'bKash Tokenized Checkout ব্যবহার করে (bKash মার্চেন্ট পোর্টাল থেকে পাওয়া মার্চেন্ট ক্রেডেনশিয়াল)। BDT-তে চার্জ হয়। চারটি ক্রেডেনশিয়ালই সংরক্ষিত হলে চেকআউটে bKash দেখানো হয়।',
