'Pg_Paymob_Help' => 'Paymob Unified Checkout ব্যবহার করে (মিশর, সৌদি আরব, সংযুক্ত আরব আমিরাত, পাকিস্তান ও ওমানে কার্ড, ওয়ালেট ও স্থানীয় পদ্ধতি)। পাঁচটি ক্রেডেনশিয়ালই Paymob Dashboard → Settings → Account Info + Payment Integrations থেকে পাওয়া যায়।',
'Pg_Paymob_Webhook_Help' => 'প্রতিটি পেমেন্টের জন্য ওয়েবহুক স্বয়ংক্রিয়ভাবে সেট হয় — ড্যাশবোর্ডে কিছু সেট করতে হবে না। রেফারেন্সের জন্য ব্যাকআপ কলব্যাক URL:',
