'Pg_Myfatoorah_Country_Help' => 'আপনার MyFatoorah অ্যাকাউন্টের দেশের ISO কোড — KWT, SAU, QAT, EGY, ARE, BHR, OMN অথবা JOR। লাইভ API হোস্ট নির্বাচন করে; স্যান্ডবক্স মোডে উপেক্ষা করা হয়।',
'Pg_Myfatoorah_Currency_Help' => 'আপনার MyFatoorah অ্যাকাউন্টের মুদ্রা (KWD, SAR, AED, QAR, BHD, OMR, JOD, EGP…) এবং আপনার স্টোরের মূল মুদ্রার সঙ্গে মিলতে হবে।',
