'Pg_Xpay_Help' => 'চেকআউট পেজে বসানো একটি XPay এলিমেন্টে কার্ডের তথ্য দেওয়া হয় (কোনো রিডাইরেক্ট নেই)। অর্ডার তৈরির আগে প্রতিটি পেমেন্ট সার্ভারে পুনরায় যাচাই করা হয়। দ্রষ্টব্য: XPay-এর অফিশিয়াল প্লাগইনের মতোই, XPay-এর SDK-র জন্য ব্রাউজারে API HMAC সিক্রেট প্রয়োজন।',
