'Pg_Paypal_Help' => 'হোস্টেড PayPal চেকআউট (Orders API v2)। ক্রেতা PayPal-এ অনুমোদন দেন এবং ফিরে এলে পেমেন্ট সার্ভারে ক্যাপচার হয় — মাঝপথে ছেড়ে দেওয়া অনুমোদন কখনো অর্ডারকে পরিশোধিত হিসেবে চিহ্নিত করে না।',
'Pg_Paystack_Webhook_Url_Help' => 'এটি আপনার Paystack ড্যাশবোর্ডে যোগ করুন। ক্রেতার ব্রাউজার কখনো ফিরে না এলে এটিই সার্ভার-টু-সার্ভার ব্যাকআপ হিসেবে অর্ডার নিষ্পত্তি করে।',
