'Shp_Scheduler_Hint' => 'শিডিউলার প্রতি ৫ মিনিটে পরীক্ষা করে, নিচের ব্যবধানগুলোর জন্য এটিই সবচেয়ে সূক্ষ্ম মান। সিঙ্ক সবসময় হাতেও শুরু করা যায়।',
'Shp_Instant_Push_Hint' => 'কোনো বিক্রয়, রিটার্ন বা সমন্বয় সংরক্ষণ হওয়ামাত্র শুধু সংশ্লিষ্ট পণ্যগুলোর স্টক পুশ পাঠানো হয়, ফলে পরবর্তী নির্ধারিত রানের অপেক্ষা ছাড়াই কয়েক সেকেন্ডের মধ্যে শপ সঠিক থাকে। আর কিছু ইনস্টল করতে হবে না — বিক্রয়ের সাড়া দেওয়ার পর পুশটি চলে, তাই ক্যাশ কাউন্টারকে কখনো Shopify-এর জন্য অপেক্ষা করতে হয় না।',
'Shp_Switch_Inventory_First' => 'প্রথমে {tab}-এ ইনভেন্টরি চালু করুন।',
'Shp_Leave_Off_Lag' => 'এটি বন্ধ রাখলে POS বিক্রয় শুধু পরবর্তী ইনভেন্টরি পুশে Shopify-তে পৌঁছায় — সর্বোচ্চ {n} মিনিট পরে।',
'Shp_Default_Interval' => 'ডিফল্ট ব্যবধান (মিনিট)',
'Shp_Default_Interval_Hint' => 'যেসব ধাপ নিজস্ব ব্যবধান সেট করে না সেগুলোতে ব্যবহৃত হয়।',
'Shp_What_Runs_Auto' => 'কী কী স্বয়ংক্রিয়ভাবে চলে',
'Shp_Plan_Hint' => 'প্রতিটি ধাপ হলো এক দিকে একটি ডেটার ধরন। অর্ডার সবসময় শুধু Shopify {from} আসে।',
'Shp_From' => 'থেকে',
'Shp_Add_Step' => 'ধাপ যোগ করুন',
'Shp_Using_Default_Plan' => 'ডিফল্ট পরিকল্পনা ব্যবহার হচ্ছে',
'Shp_Default_Plan_Desc' => 'প্রতি {n} মিনিটে অর্ডার আনা হয় এবং স্টক পুশ করা হয়। নিজের মতো বেছে নিতে একটি ধাপ যোগ করুন — তালিকাটি আবার খালি করলে এই ডিফল্ট ফিরে আসে।',
'Shp_N_Min' => '{n} মিনিট',
'Shp_Step_Entity_Off' => 'আগের ট্যাবে {entity} বন্ধ আছে — এই ধাপটি বাদ দেওয়া হবে।',
'Shp_Inactive_Lc' => 'নিষ্ক্রিয়',
'Shp_No_Locations' => 'ওই শপে কোনো লোকেশন নেই',
'Shp_Could_Not_Load_Locations' => 'লোকেশন লোড করা যায়নি — প্রথমে সংযোগটি পরীক্ষা করুন',
'Shp_Store_Updated' => 'স্টোর হালনাগাদ হয়েছে',
'Shp_Store_Connected' => 'স্টোর সংযুক্ত হয়েছে',
'Shp_Could_Not_Save_Store' => 'এই স্টোরটি সংরক্ষণ করা যায়নি',
'Shp_G_Lead_Store' => 'এই শপকে হালনাগাদ রাখতে যা যা দরকার। এখানকার সবকিছু এই স্টোরের জন্য নির্দিষ্ট — ওয়েবহুক URL ও id-গুলো আসল।',
'Shp_G_Lead_Store_Cmd' => 'এই শপকে হালনাগাদ রাখতে যা যা দরকার। এখানকার সবকিছু এই স্টোরের জন্য নির্দিষ্ট — ওয়েবহুক URL ও id-গুলো আসল, তাই কমান্ডগুলো সরাসরি কপি করে সার্ভারে চালানো যায়।',
'Shp_G_Lead_Generic' => 'একটি Shopify শপ কীভাবে ERP-এর সঙ্গে হালনাগাদ থাকে। কোনো স্টোরের নিজস্ব অবস্থা দেখতে উপরে সেটি বেছে নিন, অথবা যেমন আছে তেমনই পড়ুন — যে স্টোরই সংযুক্ত করুন, ওয়েবহুক URL একই থাকে।',
'Shp_G_Lead_Generic_Cron' => 'একটি Shopify শপ কীভাবে ERP-এর সঙ্গে হালনাগাদ থাকে। কোনো স্টোরের নিজস্ব অবস্থা দেখতে উপরে সেটি বেছে নিন, অথবা যেমন আছে তেমনই পড়ুন — যে স্টোরই সংযুক্ত করুন, ওয়েবহুক URL ও cron লাইন একই থাকে।',
'Shp_G_Ways_Note' => 'বেশিরভাগ শপ দুটিই চালায়: প্রথমটি শপকে মিনিটে মিনিটে হালনাগাদ রাখে, দ্বিতীয়টি প্রথমটির বাদ পড়া যেকোনো কিছু ধরে ফেলে — যে ওয়েবহুক কখনো আসেনি, Shopify অ্যাডমিনে সরাসরি করা কোনো সম্পাদনা, বা যে রাতে সাইট বন্ধ ছিল।',
'Shp_G_Both_Need' => 'দুটি পদ্ধতিরই প্রথমে এটি দরকার',
'Shp_G_Credentials' => 'Shopify ক্রেডেনশিয়াল',
'Shp_G_Cred_Intro' => 'জানুয়ারি ২০২৬ থেকে Shopify আর অ্যাডমিনের ভেতরে কাস্টম অ্যাপ তৈরি করে না, তাই সংযোগ দুই ধরনের:',
'Shp_G_Cred_Dev' => '{app} (এখন সংযুক্ত যেকোনো শপ) — {path}। এই স্টোর যা সিঙ্ক করে তার জন্য Admin API স্কোপ অনুমোদন করুন, শপে অ্যাপটি ইনস্টল করুন, তারপর অ্যাপের Settings পেজ থেকে {clientId} ও {clientSecret} কপি করে {edit}-এ বসান। ERP নিজেই এগুলোর বিনিময়ে অ্যাকসেস টোকেন নেয় এবং প্রতি ২৪ ঘণ্টায় মেয়াদ শেষ হওয়ার আগে তা নবায়ন করে। client secret ওয়েবহুকও সাইন করে, তাই আর কিছু লাগে না। অ্যাপ ও শপ একই Shopify অর্গানাইজেশনে থাকতে হবে।',
'Shp_G_Dev_App' => 'Dev Dashboard অ্যাপ',
'Shp_G_Cred_Legacy' => '{app} (২০২৬-এর আগে অ্যাডমিনে তৈরি) — এর {token} ({prefix}) এবং ওয়েবহুক সাইনিং সিক্রেট হিসেবে এর {secret} দিয়ে আগের মতোই কাজ করে চলে। এটি টোকেনের মান নয়, এবং দুটি উল্টাপাল্টা বসানোই ওয়েবহুক প্রত্যাখ্যাত হওয়ার সাধারণ কারণ।',
'Shp_G_Legacy_App' => 'পুরোনো কাস্টম অ্যাপ',
'Shp_G_Api_Secret_Key' => 'API সিক্রেট কী',
'Shp_G_Stored' => 'সংরক্ষিত',
'Shp_G_Missing_Refused' => 'নেই — ডেলিভারি প্রত্যাখ্যাত হবে',
'Shp_G_Targets' => '{path} যে ERP গুদামের স্টক এই শপ বিক্রি করে, এবং যে Shopify লোকেশনে সেই স্টক লেখা হয়। এগুলো ছাড়া ইনভেন্টরি সিঙ্ক ও অর্ডার ইমপোর্ট দুটিই চলতে অস্বীকার করে।',
'Shp_G_Currently' => 'বর্তমানে: গুদাম {warehouse}, লোকেশন {location}',
'Shp_G_Not_Set_Lc' => 'সেট করা নেই',
'Shp_G_Ready' => 'প্রস্তুত',
'Shp_G_Incomplete' => 'অসম্পূর্ণ',
'Shp_G_Manual_Syncs' => 'আপনি হাতে যেসব সিঙ্ক শুরু করেন',
'Shp_G_Manual_Body' => '{centre} থেকে শুরু করা সিঙ্ক সঙ্গে সঙ্গে সাড়া দেয় এবং ব্যাকগ্রাউন্ডে ছোট ছোট অংশে চলে, প্রতিটি অংশ আগেরটি যেখানে থেমেছিল সেখান থেকে শুরু করে। সময় ফুরিয়ে যাওয়া কোনো ওয়েব রিকোয়েস্টের কারণে বড় ক্যাটালগ কখনো মাঝপথে কেটে যায় না, এবং পেজ বন্ধ করলেও এটি থামে না।',
'Shp_G_Worker_Managed' => 'এর জন্য আপনার প্ল্যাটফর্ম ওয়ার্কার চালায়, তাই কিছু ইনস্টল করতে হবে না।',
'Shp_G_Worker_Cron' => 'এর জন্য ওয়ার্কার হলো আরও একটি cron লাইন:',
'Shp_G_Cron_Copied' => 'cron লাইন কপি হয়েছে',
'Shp_G_Worker_Busy' => 'ওয়ার্কার ব্যস্ত থাকলে, খোলা সিঙ্ক সেন্টার পেজ কয়েক সেকেন্ড পর নিজেই রানটি চালিয়ে নেয়, একবারে একটি ছোট রিকোয়েস্ট করে — তাই আপনার চোখের সামনেই সিঙ্ক সবসময় শেষ হয়।',
'Shp_G_Pick_How' => 'তারপর বেছে নিন কীভাবে এটি হালনাগাদ থাকবে',
'Shp_G_Right_Away' => 'সঙ্গে সঙ্গে',
'Shp_G_Stock_Live' => 'স্টক লাইভ',
'Shp_G_Stock_Not_Live' => 'স্টক লাইভ নয়',
'Shp_G_Realtime_Lead' => 'প্রতিটি পরিবর্তন ঘটার সঙ্গে সঙ্গে, কয়েক সেকেন্ডে পাঠানো হয়। এর দুটি অংশ, এবং সেগুলো আলাদা সুইচ: {webhooks} শপের নিজস্ব ইভেন্ট নিয়ে আসে, আর {push} স্টক বাইরে পাঠায়।',
'Shp_G_Webhooks_Lc' => 'ওয়েবহুক',
'Shp_G_Instant_Push_Lc' => 'তাৎক্ষণিক স্টক পুশ',
'Shp_G_Webhooks_Heading' => 'ওয়েবহুক — শপ → ERP',
'Shp_G_Webhooks_Body' => 'অর্ডার, অর্ডারের অবস্থার পরিবর্তন, এবং Shopify-তে করা পণ্য, ক্রেতা ও স্টকের সম্পাদনা। স্টোরটি খুলে এর {tab}-এ {button} চাপুন — দুবার চাপলেও সমস্যা নেই। Shopify এখানে পোস্ট করে:',
'Shp_G_Webhooks_Tab' => 'ওয়েবহুক ট্যাব',
'Shp_G_Webhooks_Note' => 'ঠিকানাটি ইন্টারনেট থেকে HTTPS-এ পৌঁছানোর যোগ্য হতে হবে — Shopify {localhost} বা কোনো {test} ডোমেইনে ডেলিভারি করবে না। প্রতিটি ডেলিভারি একবারই রেকর্ড হয়, তাই Shopify-এর পুনঃচেষ্টায় ডুপ্লিকেট অর্ডার তৈরি হতে পারে না, এবং ব্যর্থ ডেলিভারি পুনরায় চালানো যায়। ধাপ ১-এর সাইনিং সিক্রেট সংরক্ষণ না করা পর্যন্ত ডেলিভারি প্রত্যাখ্যাত হয়।',
'Shp_G_Push_Heading' => 'তাৎক্ষণিক স্টক পুশ — ERP → শপ',
'Shp_G_People_Miss' => 'এই সেটিংটিই লোকে প্রায়ই খেয়াল করেন না',
'Shp_G_Push_P1' => 'POS বিক্রয় নিজে থেকে Shopify-তে পৌঁছায় {not}। বন্ধ রাখলে শপ শুধু পরবর্তী ইনভেন্টরি পুশ ধাপে বিষয়টি জানতে পারে — আর সেই সময়ের মধ্যে এটি এমন একটি ইউনিট বিক্রি করে ফেলতে পারে যা আপনি আগেই ক্যাশ কাউন্টারে বিক্রি করেছেন।',
'Shp_G_Not' => 'না',
'Shp_G_Push_P2' => '{path}-এ {setting}-এ টিক দিন। সেটআপ এটুকুই — কোনো ওয়ার্কার নেই, কোনো cron নেই। এরপর প্রতিটি বিক্রয়, রিটার্ন ও সমন্বয় সংরক্ষণের ঠিক পরেই শুধু সংশ্লিষ্ট পণ্যগুলোর একটি পুশ পাঠায়, এবং বিশ লাইনের একটি বিক্রয়ে একটিই পুশ হয়, বিশটি নয়। ক্যাশ কাউন্টার কখনো এর জন্য অপেক্ষা করে না।',
'Shp_G_This_Store' => 'এই স্টোর:',
'Shp_G_Push_On' => 'চালু — পরিবর্তনের সঙ্গে সঙ্গে স্টক পুশ',
'Shp_G_Push_Off' => 'বন্ধ — স্টক শুধু সময়সূচি অনুযায়ী',
'Shp_G_Push_Note' => 'শুধু যেসব পণ্যের আগে থেকেই Shopify ম্যাপিং আছে, এবং শুধু এই স্টোরের গুদামের নড়াচড়াই পুশ করা হয়। বাল্ক অপারেশন — কোনো পণ্য মোছা, কোনো গুদাম রিসেট করা — কোনো ইভেন্ট ছাড়াই স্টক লেখে, আর এটিই নির্ধারিত ইনভেন্টরি ধাপটিও রেখে দেওয়ার একটি কারণ।',
'Shp_G_Nothing_Else' => 'আর কিছু ইনস্টল করতে হবে না',
'Shp_G_Nothing_Else_Body' => 'কোনো অংশেরই queue worker বা cron এন্ট্রি লাগে না। আগত ওয়েবহুক Shopify-এর পাঠানো রিকোয়েস্টের মধ্যেই সামলানো হয়; বাইরে যাওয়া স্টক পুশ সেই একই প্রসেসে চলে যা বিক্রয়টি সম্পন্ন করেছে, রেসপন্স ফেরত যাওয়ার {after} — তাই ক্যাশ কাউন্টার কখনো Shopify-এর অপেক্ষায় থাকে না, আর কোনো শপ সাড়া দেওয়া বন্ধ করলে দশ সেকেন্ড পর হাল ছেড়ে দিয়ে পরবর্তী নির্ধারিত ইনভেন্টরি পুশের ওপর ছেড়ে দেওয়া হয়।',
'Shp_G_After' => 'পরে',
'Shp_G_Exception' => 'একটি ব্যতিক্রম: ব্যাকগ্রাউন্ড টাস্কের করা স্টক পরিবর্তনের পরে কোনো রেসপন্স থাকে না, তাই এটি বদলে {queue}-এ কিউ করা হয়।',
'Shp_G_Queue_Managed' => 'আপনার প্ল্যাটফর্ম আগে থেকেই ওই কিউতে একটি ওয়ার্কার চালায়, তাই সেগুলোও নিজে থেকেই চলে যায়।',
'Shp_G_Queue_Cron' => 'সেগুলোও দ্রুত পাঠাতে চাইলে ওই কিউটি খালি করুন:',
'Shp_G_On_Schedule' => 'সময়সূচি অনুযায়ী',
'Shp_G_On_Lc' => 'চালু',
'Shp_G_Off_Lc' => 'বন্ধ',
'Shp_G_Scheduled_Lead' => 'সবকিছু কিছুক্ষণ পরপর দুই দিকেই পুনরায় যাচাই করা হয়। রিয়েল টাইমের চেয়ে ধীর, তবে যেসব শপ তাৎক্ষণিক পুশ ব্যবহার করে না সেখানে এটিই স্টক পাঠায়, বাদ পড়া ওয়েবহুক ধরে ফেলে, এবং পুরো ক্যাটালগ সরানোর একমাত্র উপায়।',
'Shp_G_Nothing_To_Install' => 'কিছু ইনস্টল করতে হবে না',
'Shp_G_Managed_Body' => 'শিডিউলার আপনার হয়ে চালানো হয়: প্রতি পাঁচ মিনিটে আপনার প্ল্যাটফর্ম প্রতিটি স্টোরকে জিজ্ঞাসা করে এর পরিকল্পনার কোনো ধাপ নির্ধারিত সময়ে পৌঁছেছে কি না, এবং যেগুলো পৌঁছেছে সেগুলো চালায়। কোনো cron এন্ট্রি যোগ করতে হয় না, কোনো সার্ভার রক্ষণাবেক্ষণ করতে হয় না।',
'Shp_G_Managed_Note' => 'পাঁচ মিনিটই একটি পরিকল্পনার সবচেয়ে সূক্ষ্ম ব্যবধান, কারণ ধাপের সবচেয়ে ছোট ব্যবধান পাঁচ মিনিট। দীর্ঘ ব্যবধান হুবহু মানা হয় — ৩০ মিনিটে সেট করা একটি ধাপ ছয়বার পরীক্ষা করা হয় এবং একবার চলে।',
'Shp_G_Cron_Entry' => 'cron এন্ট্রি',
'Shp_G_Cron_Body' => 'এটি ছাড়া নির্ধারিত কিছুই চলে না। একটি লাইন, শুধু এই মডিউলের জন্য — আপনি আর যা কিছু নির্ধারণ করে রেখেছেন তার পাশে এটি যোগ করুন:',
'Shp_G_Cron_Note' => 'প্রতি পাঁচ মিনিট হলো একটি পরিকল্পনার সবচেয়ে সূক্ষ্ম ব্যবধান, কারণ ধাপের সবচেয়ে ছোট ব্যবধান পাঁচ মিনিট। এর চেয়ে বড় এন্ট্রি দিলে সেটিই সর্বনিম্ন সীমা হয়ে যায় — {every15} দিলে ৫ মিনিটে সেট করা ধাপ প্রতি ১৫ মিনিটে চলে। Windows-এ Task Scheduler ব্যবহার করুন: প্রোগ্রাম {php}, আর্গুমেন্ট {args}, শুরুর ফোল্ডার {path}।',
'Shp_G_Switch_On' => 'এটি চালু করুন, এবং পরিকল্পনা বেছে নিন',
'Shp_G_Plan_Body' => '{path} সুইচটি ঠিক করে শিডিউলার আদৌ কাজ করতে পারবে কি না; পরিকল্পনা ঠিক করে এটি কী করবে। একটি {step} হলো নিজস্ব ব্যবধানসহ এক দিকে একটি ডেটার ধরন — {ex1}, {ex2}। যে ধাপের নিজস্ব ঘর ফাঁকা থাকে সেখানে ডিফল্ট ব্যবধান ব্যবহৃত হয়।',
'Shp_G_Step_Lc' => 'ধাপ',
'Shp_G_Ex1' => 'অর্ডার · Shopify → ERP প্রতি ১৫ মিনিটে',
'Shp_G_Ex2' => 'ইনভেন্টরি · ERP → Shopify প্রতি ৩০ মিনিটে',
'Shp_G_Plan_Note' => 'পরিকল্পনা খালি রাখলে স্টোরটি ডিফল্ট ব্যবধানে অর্ডার আনে ও স্টক পুশ করে, যা বেশিরভাগ শপ চায়। অর্ডার শুধু আনা যায়: ক্রেতা অর্ডার দেন Shopify-তেই।',
'Shp_G_Schedule_On' => 'সময়সূচি চালু',
'Shp_G_Schedule_Off' => 'সময়সূচি বন্ধ — শুধু ম্যানুয়াল',
'Shp_G_When_Runs' => 'একটি ধাপ আসলে কখন চলে',
'Shp_G_When_Body' => 'একটি ধাপ তখন নির্ধারিত হয় যখন সেই একই ধাপ সর্বশেষ যতক্ষণ আগে {started}, তা এর ব্যবধানের চেয়ে বেশি — রানের ইতিহাস থেকে পড়া হয়। তাই হাতে শুরু করা সিঙ্ক পরবর্তী স্বয়ংক্রিয় সিঙ্ককে পিছিয়ে দেয়, এবং বারবার ব্যর্থ হওয়া ধাপ প্রতি টিকে নয়, এর ব্যবধান অনুযায়ী পুনরায় চেষ্টা করা হয়। স্টোরের সারসংক্ষেপে প্রতিটি ধাপের সর্বশেষ রান, পরবর্তী নির্ধারিত সময় এবং আটকে থাকলে তার কারণ দেখায়। সময়সূচিতে দেওয়ার আগে প্রথম ক্যাটালগ পুশ সিঙ্ক সেন্টার থেকে হাতে চালান — প্রথমে ড্রাই রান হিসেবে।',
'Shp_G_Started_Lc' => 'শুরু হয়েছিল',
'Shp_G_Where_Setting' => 'কোন সেটিং কোথায়',
'Shp_G_Where_Note' => 'এগুলোর সবই একটি বিদ্যমান স্টোরে থাকে: {path}, তারপর পেনসিল আইকন (অথবা স্টোরের নিজস্ব পেজে {edit})।',
'Shp_G_Product_Images' => 'পণ্যের ছবি',
'Shp_G_Img1' => '{push}-এ পণ্যের সঙ্গে ছবিও যায় — প্রথমে প্রধান ছবি, তারপর গ্যালারি, তারপর নিজস্ব ছবিসহ প্রতিটি ভ্যারিয়েন্টের একটি করে, সর্বোচ্চ পঞ্চাশটি পর্যন্ত।',
'Shp_G_Products_Push' => 'পণ্য পুশ',
'Shp_G_Img2' => 'ভ্যারিয়েন্টের ছবি পণ্যের সঙ্গে আপলোড হয় এবং তারপর {assigned}, Shopify এভাবেই এটি সাজায়: একটি ভ্যারিয়েন্ট পণ্যের ছবিগুলোর একটিকে নির্দেশ করে। প্রধান ছবি পুনরায় ব্যবহার করা ভ্যারিয়েন্ট সেটি দুবার আপলোড করে না।',
'Shp_G_Assigned' => 'সেই ভ্যারিয়েন্টে নির্ধারিত হয়',
'Shp_G_Img3' => 'ফাইল হিসেবে সংরক্ষিত ছবি Shopify-তে লিংক নয়, {uploaded} করা হয়, তাই এই ইনস্টলেশন ইন্টারনেট থেকে পৌঁছানো না গেলেও এটি কাজ করে। পেস্ট করা লিংক হিসেবে যোগ করা ছবি সেই URL হিসেবেই Shopify-কে দেওয়া হয়, যা সর্বজনীনভাবে পৌঁছানোর যোগ্য হতে হবে।',
'Shp_G_Uploaded' => 'আপলোড',
'Shp_G_Img4' => 'ছবিগুলো শুধু আসলেই পরিবর্তন হলে আবার পাঠানো হয় — শুধু দাম বদলানো পুশ শপের ছবিতে হাত দেয় না, কারণ ছবি পাঠালে পুরো সেটটাই প্রতিস্থাপিত হয়।',
'Shp_G_Img5' => 'ERP-তে কোনো ছবি সরালে Shopify-তে তা মোছা হয় {not}। সেখানেও মুছে দিন, নইলে শপে সেটি দেখাতেই থাকবে।',
'Shp_G_Commands' => 'জানা দরকার এমন কমান্ড',
'Shp_G_Command_Copied' => 'কমান্ড কপি হয়েছে',
'Shp_G_Foot' => 'প্রতিটি সিঙ্ক {logs}-এ লেখে, এবং প্রতিটি স্টোরের সারসংক্ষেপে দেখায় প্রতিটি ধাপ সর্বশেষ কখন চলেছে, পরবর্তী কখন নির্ধারিত, এবং কিছু আটকে থাকলে কী সেটি আটকাচ্ছে। কোনো সিঙ্ক প্রত্যাশামতো কাজ না করলে প্রথমে সেখানেই দেখুন।',
