'Agt_Tax_Map_Hint' => 'তালিকায় না থাকা হারগুলো OUT (Outra) হিসেবে পাঠানো হয়; ০% সবসময় ISE (Isento)।',
'Agt_Series' => 'সিরিজ',
'Agt_Series_Hint' => 'AGT প্রতিটি ডকুমেন্টের ধরন, বছর ও প্রতিষ্ঠানের জন্য একটি নম্বর সিরিজ অনুমোদন করে। সংশ্লিষ্ট ধরন ও বছরের সক্রিয় সিরিজ ছাড়া চালান ইস্যু করা যায় না।',
