'Agt_Check' => 'যাচাই করুন',
'Agt_Correct_Confirm' => 'এই প্রত্যাখ্যাত ডকুমেন্টের জন্য নতুন নম্বরসহ একটি সংশোধনী ইস্যু করবেন?',
'Agt_Correct' => 'সংশোধন করুন',
'Agt_Guide_What_Title' => 'এটি কী করে',
'Agt_Guide_What_Body' => 'প্রতিটি সম্পন্ন বিক্রয় একটি AGT ইলেকট্রনিক চালান হিসেবে ইস্যু হয় (তৈরির সময় পরিশোধিত হলে FR, অন্যথায় FT) এবং প্রতিটি গৃহীত ফেরত একটি ক্রেডিট নোট (NC) হিসেবে। প্রতিটি ডকুমেন্ট তার AGT সিরিজের পরবর্তী নম্বর পায়, আপনার AGT কী দিয়ে স্বাক্ষরিত হয় এবং AGT-তে পাঠানো হয়, যা কয়েক মিনিট পরে এটি যাচাই করে। রসিদ ও PDF চালানে AGT নম্বর, নিরাপত্তা নির্যাস ও একটি QR কোড ছাপা হয়।',
'Agt_Guide_Steps_Title' => 'সেটআপ',
'Agt_Guide_Step_1' => 'Portal do Contribuinte-এ ই-ইনভয়েসিংয়ে যোগ দিন (adesão) এবং আপনার AGT প্রাইভেট কী ডাউনলোড করুন।',
'Agt_Guide_Step_2' => 'কনফিগারেশন ট্যাবে আপনার NIF, প্রতিষ্ঠান ও কী লিখুন, Homologação বেছে নিন, সংরক্ষণ করুন এবং সংযোগ পরীক্ষা ব্যবহার করুন।',
'Agt_Guide_Step_3' => 'সিরিজ ট্যাবে, চলতি বছরের জন্য আপনি যে ডকুমেন্টের ধরনগুলো ব্যবহার করেন (FR, FT, NC) প্রতিটির জন্য একটি করে সিরিজের অনুরোধ করুন।',
'Agt_Guide_Step_4' => 'আপনার IVA হারগুলো AGT কোডের সাথে মিলিয়ে দিন এবং ০% লাইনের জন্য অব্যাহতি কোড নির্ধারণ করুন।',
'Agt_Guide_Step_5' => 'সিস্টেম সেটিংস > বৈশিষ্ট্য থেকে মডিউলটি চালু করুন, একটি পরীক্ষামূলক বিক্রয় করুন এবং ডকুমেন্ট ট্যাবে এটি বৈধ হয় কিনা যাচাই করুন।',
'Agt_Guide_Step_6' => 'AGT আপনাকে প্রোডাকশনের জন্য অনুমোদন দিলে Produção-তে পরিবর্তন করুন এবং প্রোডাকশন সিরিজের অনুরোধ করুন।',
'Agt_Guide_Note_1' => 'পাঠানো বিক্রয় বা ফেরত আর সম্পাদনা বা মুছে ফেলা যায় না। বিক্রয় ফেরত (ক্রেডিট নোট) দিয়ে এটি সংশোধন করুন।',
'Agt_Guide_Note_2' => 'AGT প্রত্যাখ্যাত ডকুমেন্টগুলো নতুন নম্বর দিয়ে সংশোধন করা হয়, যা প্রত্যাখ্যাতটিকে উল্লেখ করে; পুরোনো নম্বর কখনো পুনরায় ব্যবহার হয় না।',
'Agt_Guide_Note_3' => 'অফলাইন POS বিক্রয়গুলো সিঙ্ক হওয়ার সময় পাঠানো হয়। ২৪ ঘণ্টার বেশি দেরিতে পাঠানো ডকুমেন্টের জন্য AGT জরিমানা করে।',
'Agt_Guide_Note_4' => 'একটি লাইনে পণ্যের কর ও অর্ডারের কর একসাথে থাকতে পারে না; AGT-এর প্রতি লাইনে একটি IVA হার প্রয়োজন। শিপিং একটি করমুক্ত লাইন হিসেবে পাঠানো হয়।',
'Agt_Guide_Note_5' => 'AGT মোট হিসাব প্রতি লাইনে গণনা করে এবং রাউন্ডিংয়ের কারণে Stocky-এর মোট থেকে কয়েক সেন্ট পার্থক্য হতে পারে।',
