'Dgi_No_Documents' => 'এখনও কোনো সার্টিফাইড চালান নেই — e-MCF সংযোগ চালু হলে সার্টিফিকেশন শুরু হবে।',
'Dgi_Guide_What_Title' => 'এটি এখন কী করে',
'Dgi_Guide_What_Body' => 'মডিউল চালু থাকলে রসিদ ও PDF চালানে facture normalisée-এর জন্য আবশ্যক বিক্রেতার NIF, RCCM ও Id. Nat. ছাপা হয়। পূর্ণ সার্টিফিকেশন (DGI প্রদত্ত DEF নম্বর, কাউন্টার, প্রমাণীকরণ কোড ও QR) e-MCF ডেভেলপার API সংযুক্ত হলে যোগ করা হবে।',
