'Dgi_Guide_Step_2' => 'API ডকুমেন্টেশন (রুট, DTO, কর গ্রুপ) এবং পরীক্ষামূলক ক্রেডেনশিয়াল ডাউনলোড করুন।',
'Dgi_Guide_Step_3' => 'সংযোগ সম্পন্ন ও পরীক্ষা করার জন্য এগুলো আপনার প্ল্যাটফর্ম অ্যাডমিনিস্ট্রেটরকে পাঠান।',
'Dgi_Guide_Step_4' => 'পরীক্ষার পর DGI-তে হোমোলোগেশন ফাইল জমা দিন।',
