'VG_Opt_Step3' => 'একটি মান লিখুন (যেমন লাল) এবং Enter চাপুন। প্রতিটি মানের জন্য পুনরাবৃত্তি করুন; কমা দিয়েও মান আলাদা করা যায়। কোনো মান সরাতে তার x-এ ক্লিক করুন।',
'VG_Opt_Step4' => 'দ্বিতীয় বা তৃতীয় অপশনের জন্য "অপশন যোগ করুন"-এ ক্লিক করুন (সর্বোচ্চ ৩টি অপশন)।',
'VG_Opt_Step5' => '"ভ্যারিয়েন্ট তৈরি করুন"-এ ক্লিক করুন। প্রতিটি সমন্বয়ের জন্য একটি সারি তৈরি হয় এবং তার নাম স্বয়ংক্রিয়ভাবে গঠিত হয়, যেমন "লাল / S"।',
'VG_Opt_Step6' => 'প্রতিটি সারিতে ক্রয়মূল্য ও দাম লিখুন, অথবা "সবগুলোতে প্রয়োগ করুন"-এ একটি মান লিখে ক্রয়মূল্য বা দাম-এ ক্লিক করে সেটি সব সারিতে কপি করুন।',
'VG_Opt_Step7' => 'কোড আপনার জন্য তৈরি হয়ে যায়। নিজের কোড লিখুন অথবা আরেকটি তৈরি করতে রিফ্রেশ আইকনে ক্লিক করুন।',
'VG_Opt_Step8' => 'ঐচ্ছিক: কোনো অপশনে "রঙের সোয়াচ" টিক দিন এবং প্রতিটি মানের জন্য একটি রং বেছে নিন; স্টোর এটি রঙিন বিন্দু হিসেবে দেখায়।',
'VG_Rows_Title' => 'ভ্যারিয়েন্টের সারি',
'VG_Rows_Text' => 'প্রতিটি সারিতে ছবি, কোড, বারকোড, ক্রয়মূল্য, দাম, পাইকারি দাম ও সর্বনিম্ন বিক্রয়মূল্য থাকে। পণ্য তৈরির সময় প্রতিটি ভ্যারিয়েন্টের জন্য গুদাম অনুযায়ী প্রারম্ভিক স্টকও লেখা যায়। "অসম্পূর্ণ" ট্যাগ মানে সারিটিতে কোনো একটি অপশনের মান নেই।',
'VG_List_Title' => 'সাধারণ তালিকা মোড',
'VG_List_Text' => 'একটি ভ্যারিয়েন্টের নাম লিখে Enter চাপুন (বা যোগ করুন-এ ক্লিক করুন) একটি সারি যোগ করতে, তারপর তার কোড ও দাম পূরণ করুন। এটি প্রচলিত পদ্ধতি এবং বিদ্যমান পণ্যের জন্য উপলব্ধ থাকে।',
'VG_Edit_Title' => 'পরে সম্পাদনা',
'VG_Edit_1' => 'একটি মান যোগ করে "ভ্যারিয়েন্ট তৈরি করুন"-এ ক্লিক করুন: শুধু অনুপস্থিত সমন্বয়গুলো যোগ হয়। বিদ্যমান সারিগুলোর কোড, দাম ও ইতিহাস অপরিবর্তিত থাকে।',
'VG_Edit_2' => 'কোনো মান বা অপশন সরালে সেটি ব্যবহারকারী সারিগুলোও সরে যায়। আগে সংরক্ষিত সারিগুলো নিশ্চিতকরণের পর পণ্য সংরক্ষণ করলে মুছে ফেলা হয়।',
'VG_Edit_3' => 'যে ভ্যারিয়েন্টে এখনও স্টক আছে তা সরানো যায় না। আগে এর স্টক সমন্বয় বা স্থানান্তর করুন।',
'VG_Edit_4' => '"সাধারণ তালিকা"-এ গেলে সারি ও তাদের নাম থাকে, কিন্তু অপশনের সংজ্ঞাগুলো বাদ পড়ে।',
'VG_Store_Title' => 'অনলাইন স্টোরে',
'VG_Store_Text' => 'ক্রেতারা প্রতিটি অপশনের একটি মান বেছে নেন, যেমন প্রথমে রং তারপর আকার। যে সমন্বয়গুলো নেই সেগুলো নিষ্ক্রিয় থাকে এবং স্টকে না থাকাগুলো কেটে দেখানো হয়। বেছে নেওয়া ভ্যারিয়েন্টটিই কার্টে যায়।',
'Style' => 'স্টাইল',
'Max_Options_Reached' => 'একটি পণ্যে সর্বোচ্চ ৩টি অপশন থাকতে পারে।',
'Variants_Removed' => '{count}টি ডুপ্লিকেট ভ্যারিয়েন্ট সরানো হয়েছে।',
'Remove_Option_Confirm' => 'এই অপশনটি সরাবেন? শুধু এটির কারণে আলাদা ভ্যারিয়েন্টগুলো একত্রিত হয়ে যাবে।',
'Saved_Variants_Removed_On_Save' => 'এখানে সরানো সংরক্ষিত ভ্যারিয়েন্টগুলো পণ্য সংরক্ষণ করলে মুছে ফেলা হবে।',
'Remove_Option_Values_Confirm' => 'এই মানটি সরালে এটি ব্যবহারকারী {count}টি ভ্যারিয়েন্টও সরে যাবে। চালিয়ে যাবেন?',
'Options_Required' => 'মানসহ অন্তত একটি অপশন যোগ করুন, অথবা সাধারণ তালিকায় যান।',
