'Variant_Missing_Option_Values' => 'প্রতিটি ভ্যারিয়েন্টে প্রতিটি অপশনের একটি মান থাকতে হবে।',
'Fashion_Theme' => 'ফ্যাশন ও পোশাক থিম',
'Fashion_Theme_Hint' => 'সম্পাদকীয় ধাঁচের পোশাকের স্টোরফ্রন্ট: সেরিফ শিরোনাম, বড় ছবি, ক্যাটাগরি টাইল, ক্যাটাগরি ট্যাবসহ নতুন পণ্য, একটি লুকবুক ব্যানার এবং একটি সেল সারি। পণ্যের কার্ডে আকারগুলো দেখায় (বিক্রি শেষ আকারগুলো কাটা) এবং হোভার করলে গ্যালারির দ্বিতীয় ছবিতে বদলে যায়। আপনার প্রধান রং সেলের দাম ও ব্যাজে ব্যবহৃত হয়। হিরো স্লাইডার ও লুকবুক ব্যানারগুলো নিচে যোগ করার পর দেখা যায়।',
