'Size_Guide_Image_Hint' => 'ঐচ্ছিক। একটি চার্টের ছবি আপলোড করুন (যেমন কীভাবে মাপবেন তার একটি অঙ্কন)। শুধু ছবিযুক্ত গাইড সেই ছবিটিকেই চার্ট হিসেবে দেখায়।',
