'Pos_Sales_Agent_Hint' => 'নির্বাচিত এজেন্ট এই বিক্রয়ের কমিশন পান। কোনো এজেন্ট না থাকলে কমিশন বিক্রয়কর্মীর সাথে যুক্ত এজেন্টের কাছে যায়।',
