'Comm_G_Intro_Title' => 'এক বাক্যে কমিশন যেভাবে কাজ করে',
'Comm_G_Intro' => 'একটি সম্পন্ন বিক্রয় সংরক্ষণ করা হলে, বিক্রয়ের বিক্রয় এজেন্টের সাথে মিলে যাওয়া নিয়মগুলো অপেক্ষমাণ কমিশন তৈরি করে। আপনি কমিশন রিপোর্টে সেগুলো অনুমোদন করেন এবং কমিশনের রসিদ দিয়ে পরিশোধ করেন। পরে বিক্রয়ে পরিবর্তন হলে (পেমেন্ট, ফেরত, সম্পাদনা, মুছে ফেলা) এর কমিশন স্বয়ংক্রিয়ভাবে পুনরায় হিসাব করা হয়।',
