'Comm_G_Your_Setup_Help' => 'এই ওয়ার্কস্পেসের সরাসরি অবস্থা। প্রতিটি ধাপ সম্পন্ন হলে সবুজ হয়ে যায়।',
'Comm_G_Optional' => 'প্রস্তাবিত',
'Comm_G_Step_Program' => 'একটি কমিশন প্রোগ্রাম তৈরি করুন',
'Comm_G_Step_Program_Help' => 'একটি প্রোগ্রাম আপনার নিয়মগুলোকে একত্রে রাখে, যেমন "২০২৬ বিক্রয় দল" বা "গ্রীষ্মকালীন ক্যাম্পেইন"। এটি অবশ্যই সক্রিয় থাকতে হবে এবং আজকের তারিখ এর কার্যকর শুরু ও কার্যকর শেষ তারিখের মধ্যে পড়তে হবে।',
'Comm_G_Step_Program_Warn' => 'আপনার প্রোগ্রাম আছে, কিন্তু আজ কোনোটিই সক্রিয় নয়। সক্রিয় বক্স এবং কার্যকর শুরু / কার্যকর শেষ তারিখ পরীক্ষা করুন।',
'Comm_G_Step_Agent' => 'আপনার বিক্রয় এজেন্ট যোগ করুন',
'Comm_G_Step_Agent_Help' => 'বিক্রয় এজেন্ট হলেন সেই ব্যক্তি যিনি কমিশন পান। এজেন্ট কর্মী হতে পারেন অথবা রেফারার বা রিসেলারের মতো বাইরের মানুষও হতে পারেন।',
'Comm_G_Step_Link' => 'এজেন্টদের ব্যবহারকারী অ্যাকাউন্টের সাথে যুক্ত করুন',
'Comm_G_Step_Link_Help' => 'কোনো এজেন্টকে একজন ব্যবহারকারীর সাথে যুক্ত করলে সেই ব্যবহারকারীর করা বিক্রয় স্বয়ংক্রিয়ভাবে এজেন্টের নামে জমা হয়, প্রতিটি বিক্রয়ে এজেন্ট বেছে নিতে হয় না।',
'Comm_G_Step_Link_Warn' => '{n} জন সক্রিয় এজেন্ট কোনো ব্যবহারকারীর সাথে যুক্ত নন। কেউ বিক্রয়ে তাদের বেছে নিলেই কেবল তারা কমিশন পান।',
'Comm_G_Step_Rule' => 'অন্তত একটি নিয়ম যোগ করুন',
'Comm_G_Step_Rule_Help' => 'একটি নিয়ম বলে কত পরিশোধ করতে হবে, যেমন বিক্রয়ের মোটের ৫%। এটি অবশ্যই সক্রিয় থাকতে হবে এবং আজ সক্রিয় এমন একটি প্রোগ্রামের অন্তর্ভুক্ত হতে হবে।',
'Comm_G_Step_Rule_Warn' => 'আপনার নিয়ম আছে, কিন্তু আজ সক্রিয় কোনো প্রোগ্রামের ভেতরে কোনোটিই সক্রিয় নয়।',
'Comm_G_Step_Sale' => 'একটি সম্পন্ন বিক্রয় করুন',
'Comm_G_Step_Sale_Help' => 'একটি সম্পন্ন বিক্রয় সংরক্ষণ করা হলে কমিশন তৈরি হয় (বিক্রয় তৈরি, বিক্রয় সম্পাদনা বা POS)। আপনার নিয়ম তৈরির আগে করা বিক্রয়ের হিসাব করা হয় না।',
'Comm_G_Step_Sale_Done' => 'এ পর্যন্ত {n}টি কমিশন হিসাব করা হয়েছে।',
'Comm_G_Step_Approve' => 'কমিশন অনুমোদন করুন',
'Comm_G_Step_Approve_Help' => 'কমিশন রিপোর্টে যে অপেক্ষমাণ সারিগুলোর সাথে আপনি একমত সেগুলোতে টিক দিন এবং অনুমোদিত-এ ক্লিক করুন। এই মুহূর্তে কিছুই অপেক্ষমাণ নেই।',
'Comm_G_Step_Approve_Warn' => '{n}টি কমিশন অনুমোদনের অপেক্ষায় আছে।',
'Comm_G_Step_Pay' => 'আপনার এজেন্টদের পরিশোধ করুন',
'Comm_G_Step_Pay_Help' => 'কমিশনের রসিদে একজন এজেন্ট বেছে নিন, তার অনুমোদিত কমিশনগুলোতে টিক দিন এবং রসিদটি সংরক্ষণ করুন। সেগুলো পরিশোধিত হয়ে যায়। এই মুহূর্তে পরিশোধের অপেক্ষায় কিছু নেই।',
'Comm_G_Step_Pay_Warn' => '{n}টি অনুমোদিত কমিশন পরিশোধের অপেক্ষায় আছে।',
'Comm_G_Try_Rule' => 'একটি নিয়ম পরীক্ষা করুন',
'Comm_G_Try_Rule_Help' => 'একটি বিক্রয় ও একটি নিয়ম লিখে দেখুন নিয়মটি ঠিক কত পরিশোধ করবে। সিস্টেম যে হিসাব ব্যবহার করে এটিও সেই একই হিসাব।',
'Comm_G_Sale_Total' => 'বিক্রয়ের মোট',
'Comm_G_None' => 'কোনোটিই নয়',
'Comm_G_Commission' => 'এই নিয়মের কমিশন',
'Comm_G_No_Commission' => 'কোনো কমিশন নেই',
'Comm_G_Calc_Base' => 'ভিত্তি পরিমাণ ({source}): {base}',
'Comm_G_Calc_Zero_Base' => 'ভিত্তি পরিমাণ ০, তাই এই নিয়ম কিছুই তৈরি করে না। উৎস হিসেবে পরিশোধিত পরিমাণ থাকলে, কোনো পেমেন্ট রেকর্ড না হওয়া পর্যন্ত অপরিশোধিত বিক্রয় কিছুই অর্জন করে না।',
'Comm_G_Calc_Below_Min' => 'ভিত্তি পরিমাণ {min}-এর সর্বনিম্ন সীমার নিচে, তাই এই নিয়ম এই বিক্রয়ের জন্য কিছুই তৈরি করে না।',
'Comm_G_Calc_Pct' => '{base}-এর {value}% = {amount}',
'Comm_G_Calc_Fixed' => 'নির্দিষ্ট পরিমাণ: প্রতি বিক্রয়ে {amount}, বিক্রয়ের আকার যা-ই হোক',
'Comm_G_Calc_Capped' => 'সর্বোচ্চ সীমার চেয়ে বেশি, তাই এটি কমিয়ে {cap} করা হয়েছে',
'Comm_G_Calc_Zero' => 'ফলাফল ০, তাই কোনো কমিশন তৈরি হয় না।',
'Comm_G_The_Flow' => 'ধাপে ধাপে প্রক্রিয়া',
'Comm_G_Flow_Program' => 'প্রোগ্রাম',
'Comm_G_Flow_Program_Help' => 'একটি প্রোগ্রাম তৈরি করুন এবং এটি কোন তারিখগুলোতে কার্যকর তা নির্ধারণ করুন।',
'Comm_G_Flow_Agent' => 'বিক্রয় এজেন্ট',
'Comm_G_Flow_Agent_Help' => 'যারা কমিশন পান তাদের যোগ করুন এবং কর্মীদের তাদের ব্যবহারকারী অ্যাকাউন্টের সাথে যুক্ত করুন।',
'Comm_G_Flow_Rule' => 'নিয়ম',
'Comm_G_Flow_Rule_Help' => 'প্রোগ্রামের ভেতরে নিয়ম যোগ করুন: শতাংশ বা নির্দিষ্ট, সব এজেন্টের জন্য বা একজন এজেন্টের জন্য।',
'Comm_G_Flow_Sale' => 'বিক্রয়',
'Comm_G_Flow_Sale_Help' => 'একটি সম্পন্ন বিক্রয় সংরক্ষণ করা হয়। মিলে যাওয়া প্রতিটি নিয়ম একটি করে অপেক্ষমাণ কমিশন তৈরি করে।',
'Comm_G_Flow_Approve' => 'অনুমোদন',
'Comm_G_Flow_Approve_Help' => 'কমিশন রিপোর্টে অপেক্ষমাণ কমিশনগুলো পর্যালোচনা করে অনুমোদন বা বাতিল করুন।',
'Comm_G_Flow_Pay' => 'পরিশোধ',
'Comm_G_Flow_Pay_Help' => 'এজেন্টের জন্য একটি কমিশনের রসিদ রেকর্ড করুন। এর অন্তর্ভুক্ত কমিশনগুলো পরিশোধিত হয়ে যায়।',
'Comm_G_How_It_Works' => 'যেভাবে কাজ করে',
'Comm_G_T_Credit' => 'কোন এজেন্ট কমিশন পান?',
'Comm_G_Credit_Intro' => 'প্রতিটি বিক্রয় সর্বোচ্চ একজন এজেন্টের নামে জমা হয়। সিস্টেম এই ক্রমে যাচাই করে:',
'Comm_G_Credit_Picked' => 'বিক্রয়ে বেছে নেওয়া বিক্রয় এজেন্ট: বিক্রয় তৈরি ও বিক্রয় সম্পাদনায় বিক্রয় এজেন্ট ফিল্ড, অথবা POS-এ "বিক্রেতা" বোতাম। সেই এজেন্টকে পরে নিষ্ক্রিয় করা হলে বিক্রয়টি কিছুই অর্জন করে না; এটি পরের বিকল্পগুলোতে যায় না।',
'Comm_G_Credit_Seller' => 'অন্যথায়, POS-এ বেছে নেওয়া বিক্রয়কর্মীর সাথে যুক্ত এজেন্ট (যখন POS-এর বিক্রয়কর্মী সুইচ চালু থাকে)।',
'Comm_G_Credit_Cashier' => 'অন্যথায়, যে ব্যবহারকারী বিক্রয়টি সংরক্ষণ করেছেন তার সাথে যুক্ত এজেন্ট।',
'Comm_G_Credit_Nobody' => 'এগুলোর কোনোটিতে সক্রিয় এজেন্ট পাওয়া না গেলে বিক্রয়টি কোনো কমিশন অর্জন করে না।',
'Comm_G_Credit_Note' => 'POS-এ এজেন্ট "স্বয়ংক্রিয়"-তে রাখলে ২ ও ৩ নম্বর বিকল্প ব্যবহৃত হয়। "স্বয়ংক্রিয়"-এর পাশে দেখানো নামটিই সেই এজেন্ট যার নামে জমা হবে।',
'Comm_G_T_When' => 'কমিশন কখন হিসাব ও হালনাগাদ করা হয়?',
'Comm_G_When_Intro' => 'সম্পন্ন অবস্থাসহ একটি বিক্রয় নিচের যেকোনো জায়গায় সংরক্ষণ করা হলে প্রথমবার কমিশন তৈরি হয়:',
'Comm_G_When_Create' => 'বিক্রয় তৈরি: যখন বিক্রয়টি সম্পন্ন হিসেবে সংরক্ষণ করা হয়।',
'Comm_G_When_Edit' => 'বিক্রয় সম্পাদনা: একটি সম্পন্ন বিক্রয় সংরক্ষণ করলে এর বর্তমান মোট, পেমেন্ট ও এজেন্ট দিয়ে নতুন করে হিসাব করা হয়, বাতিল করা কমিশনসহ।',
'Comm_G_When_Pos' => 'POS: যখন একটি বিক্রয় সম্পন্ন হয়, পরে সম্পন্ন হওয়া খসড়াসহ।',
'Comm_G_When_Payment' => 'একটি সম্পন্ন বিক্রয়ে পেমেন্ট যোগ করা, যার ফলে পরিশোধিত পরিমাণ নিয়মগুলো বিক্রয়ের পরে নেওয়া পেমেন্টও ধরতে পারে।',
'Comm_G_When_Cod' => 'কুরিয়ারের ক্যাশ অন ডেলিভারি: যখন কুরিয়ারের সংগৃহীত নগদ বিক্রয়ে পেমেন্ট হিসেবে রেকর্ড করা হয়।',
'Comm_G_When_Not_Intro' => 'এগুলো কমিশন তৈরি করে না:',
'Comm_G_When_Not_Status' => 'অপেক্ষমাণ বা অর্ডারকৃত হিসেবে সংরক্ষিত বিক্রয়। সম্পাদনা করে সম্পন্ন হিসেবে সংরক্ষণ করলে এগুলো কমিশন অর্জন শুরু করে।',
'Comm_G_When_Not_Before' => 'প্রোগ্রাম বা নিয়ম তৈরির আগে সংরক্ষিত বিক্রয়। এগুলোর হিসাব পটভূমিতে করা হয় না। এমন একটি বিক্রয় বিক্রয় সম্পাদনায় খুলে সংরক্ষণ করলে বিক্রয়ের তারিখে সক্রিয় নিয়মগুলো দিয়ে এর হিসাব করা হয়।',
'Comm_G_When_Not_Import' => 'ফাইল থেকে ইমপোর্ট করা বিক্রয়।',
'Comm_G_When_Not_Online' => 'অনলাইন স্টোরে দেওয়া অর্ডার।',
'Comm_G_T_Statuses' => 'কমিশনের অবস্থা',
'Comm_G_Meaning' => 'এর অর্থ',
'Comm_G_S_Pending' => 'সবেমাত্র একটি বিক্রয় থেকে হিসাব করা হয়েছে। এখনও কেউ পরীক্ষা করেননি। কমিশন রিপোর্টে এটি অনুমোদন বা বাতিল করুন।',
'Comm_G_S_Approved' => 'পরীক্ষিত ও সম্মত। এটি এজেন্টের পাওনা এবং একটি কমিশনের রসিদে অন্তর্ভুক্ত করা যায়। বিক্রয় বদলে পরিমাণ বদলালে এটি আরেকবার পর্যালোচনার জন্য অপেক্ষমাণ-এ ফিরে যায়।',
'Comm_G_S_Paid' => 'একটি কমিশনের রসিদে অন্তর্ভুক্ত। চূড়ান্ত: পরিশোধিত কমিশন কখনও বদলানো হয় না। পরে বিক্রয় বদলালে পার্থক্যটি আলাদা একটি সমন্বয় হিসেবে যোগ হয়।',
'Comm_G_S_Cancelled' => 'পরিশোধ করা হবে না। পরে পেমেন্ট বা ফেরত এলেও এটি বাতিলই থাকে। বিক্রয় সম্পাদনায় বিক্রয়টি সংরক্ষণ করলে, অথবা রিপোর্টে টিক দিয়ে পুনরায় হিসাব করুন-এ ক্লিক করলে, এটি আবার হিসাব করা হয়।',
'Comm_G_Field' => 'ফিল্ড',
'Comm_G_T_Programs' => 'কমিশন প্রোগ্রাম',
'Comm_G_Programs_Body' => 'প্রোগ্রাম হলো নিয়মের একটি আধার, সাধারণত প্রতিটি সময়কাল বা ক্যাম্পেইনের জন্য একটি। কোনো নিয়ম শুধু তখনই কাজ করে যখন এর প্রোগ্রাম সক্রিয় থাকে এবং বিক্রয়ের তারিখ প্রোগ্রামের তারিখের মধ্যে পড়ে। একই সময়ে একাধিক প্রোগ্রাম সক্রিয় থাকতে পারে, এবং সবগুলোই প্রযোজ্য হয়।',
'Comm_G_F_Program_Name' => 'প্রোগ্রামটি চিনতে সাহায্য করে এমন যেকোনো নাম, যেমন "Q4 ২০২৬" বা "ব্ল্যাক ফ্রাইডে"।',
'Comm_G_F_Program_Active' => 'প্রোগ্রামের সব নিয়ম একসাথে স্থগিত করতে টিক তুলে দিন। ইতিমধ্যে তৈরি কমিশনে কোনো প্রভাব পড়ে না।',
'Comm_G_F_Program_From' => 'এই দিনের আগের তারিখের বিক্রয় প্রোগ্রাম উপেক্ষা করে। কোনো শুরুর তারিখ না চাইলে খালি রাখুন।',
'Comm_G_F_Program_To' => 'এই দিনের পরের তারিখের বিক্রয় প্রোগ্রাম উপেক্ষা করে। কখনও শেষ না হওয়া প্রোগ্রামের জন্য খালি রাখুন।',
'Comm_G_T_Agents' => 'বিক্রয় এজেন্ট',
'Comm_G_Agents_Body' => 'বিক্রয় এজেন্ট হলেন সেই ব্যক্তি যিনি কমিশন পান। এজেন্টকে সিস্টেমের ব্যবহারকারী হতে হবে না: বাইরের রেফারার বা রিসেলাররাও এজেন্ট হতে পারেন, এবং কোনো বিক্রয়ে তাদের বেছে নেওয়া হলেই তারা কমিশন পান।',
'Comm_G_F_Agent_Name' => 'বিক্রয়, রিপোর্ট ও রসিদে দেখানো নাম।',
'Comm_G_F_Agent_Code' => 'ঐচ্ছিক রেফারেন্স, যেমন কর্মী নম্বর। এজেন্টের তালিকায় খোঁজা যায়।',
'Comm_G_F_Agent_User' => 'এজেন্টকে একজন কর্মী ব্যবহারকারীর সাথে যুক্ত করে। সেই ব্যবহারকারীর করা বিক্রয় (বা POS-এ যার জন্য তাকে বিক্রয়কর্মী হিসেবে বেছে নেওয়া হয়) তখন স্বয়ংক্রিয়ভাবে এই এজেন্টের নামে জমা হয়।',
'Comm_G_F_Agent_Active' => 'নিষ্ক্রিয় এজেন্টরা নতুন বিক্রয়ে কিছুই পান না এবং এজেন্ট নির্বাচকগুলো থেকে অদৃশ্য হয়ে যান। তাদের আগের কমিশনগুলো থেকে যায়।',
'Comm_G_T_Rules' => 'কমিশনের নিয়ম: প্রতিটি ফিল্ডের ব্যাখ্যা',
'Comm_G_Rules_Body' => 'একটি নিয়ম নির্ধারণ করে একটি বিক্রয়ে কত পরিশোধ করা হবে। সংরক্ষণের আগে কোনো নিয়ম যাচাই করতে উপরের "একটি নিয়ম পরীক্ষা করুন" বক্স ব্যবহার করুন।',
'Comm_G_F_Rule_Program' => 'নিয়মটি যে প্রোগ্রামের অন্তর্ভুক্ত। সেই প্রোগ্রাম সক্রিয় ও মেয়াদের মধ্যে থাকলেই কেবল নিয়মটি কাজ করে।',
'Comm_G_F_Rule_Type' => 'শতাংশ ভিত্তি পরিমাণের একটি অংশ পরিশোধ করে। নির্দিষ্ট প্রতিটি যোগ্য বিক্রয়ে একই পরিমাণ পরিশোধ করে, বিক্রয়ের আকার যা-ই হোক।',
'Comm_G_F_Rule_Source' => 'শতাংশ কিসের উপর থেকে নেওয়া হয়। বিক্রয়ের মোট হলো বিক্রয়ের সর্বমোট। পরিশোধিত পরিমাণ হলো কমিশন হিসাবের সময় ক্রেতা যা পরিশোধ করেছিলেন।',
'Comm_G_F_Rule_Value' => 'ধরন অনুযায়ী শতাংশ (৫ মানে ৫%) অথবা নির্দিষ্ট পরিমাণ।',
'Comm_G_F_Rule_Min' => 'ঐচ্ছিক। যেসব বিক্রয়ের ভিত্তি পরিমাণ এর নিচে সেগুলো এই নিয়ম থেকে কিছুই পায় না। সীমার ঠিক সমান বিক্রয় কমিশন পায়।',
'Comm_G_F_Rule_Cap' => 'ঐচ্ছিক। একটি বিক্রয়ে এই নিয়ম সর্বোচ্চ যত পরিশোধ করতে পারে। শতাংশ ও নির্দিষ্ট উভয় নিয়মে কাজ করে।',
'Comm_G_F_Rule_Applies' => 'সব এজেন্ট: প্রত্যেক এজেন্ট এই নিয়ম থেকে কমিশন পান। নির্দিষ্ট এজেন্ট: শুধু আপনার নির্বাচিত এজেন্ট। কোনো এজেন্ট নির্বাচন না করা নির্দিষ্ট এজেন্ট নিয়ম কাউকে কখনও পরিশোধ করে না।',
'Comm_G_F_Rule_Priority' => '"শুধু সর্বোচ্চ অগ্রাধিকারের নিয়মটি পরিশোধ করে" সেট করা প্রোগ্রামে, সর্বোচ্চ সংখ্যার যোগ্য নিয়মটি জেতে এবং বাকিগুলো বাদ পড়ে। সমান হলে, নির্দিষ্ট এজেন্ট নিয়ম সব এজেন্ট নিয়মকে হারায়। "মিলে যাওয়া প্রতিটি নিয়ম পরিশোধ করে" সেট করা প্রোগ্রামে, অগ্রাধিকার শুধু ক্রম নির্ধারণ করে।',
'Comm_G_F_Rule_Active' => 'শুধু এই নিয়মটি স্থগিত করতে টিক তুলে দিন। এর ইতিমধ্যে তৈরি কমিশনে কোনো প্রভাব পড়ে না।',
'Comm_G_T_Stacking' => 'একটি বিক্রয়ে একাধিক নিয়ম',
'Comm_G_Stacking_Body' => 'প্রতিটি প্রোগ্রাম নির্ধারণ করে এর নিয়মগুলো কীভাবে একত্রিত হয় (প্রোগ্রামের "একাধিক নিয়ম মিললে" সেটিং)।

শুধু সর্বোচ্চ অগ্রাধিকারের নিয়মটি পরিশোধ করে (নতুন প্রোগ্রামের ডিফল্ট): নিয়মগুলো সর্বোচ্চ অগ্রাধিকার থেকে নিচের দিকে যাচাই করা হয়, এবং বিক্রয়ের জন্য প্রথম যোগ্য নিয়মটি পরিশোধ করে। বিক্রয় নিয়মের সর্বনিম্ন সীমায় পৌঁছালে এবং ফলাফল ০-এর বেশি হলে নিয়মটি যোগ্য হয়। এতে স্তর তৈরি সহজ হয়: অগ্রাধিকার ১০-এ "১০,০০০ বা তার বেশি বিক্রয়ে ৭%" এবং অগ্রাধিকার ০-এ "৫%"। সারাকে বিশেষ হার দিতে, সব এজেন্ট নিয়মের চেয়ে বেশি অগ্রাধিকারসহ তার জন্য একটি নির্দিষ্ট এজেন্ট নিয়ম যোগ করুন।

মিলে যাওয়া প্রতিটি নিয়ম পরিশোধ করে: মিলে যাওয়া সব নিয়ম পরিশোধ করে এবং পরিমাণগুলো যোগ হয়। ৩%-এর একটি সব এজেন্ট নিয়ম এবং সারার জন্য ২%-এর একটি নির্দিষ্ট এজেন্ট নিয়ম মিলে সারা ৫% পান।

প্রোগ্রামগুলো একে অপরের থেকে আলাদা: প্রতিটি সক্রিয় প্রোগ্রাম নিজে নিজে পরিশোধ করে, তাই একটি বিক্রয় একই সময়ে একটি মূল প্রোগ্রাম ও একটি ক্যাম্পেইন প্রোগ্রাম থেকে কমিশন অর্জন করতে পারে।',
'Comm_G_T_Paying' => 'কমিশনের রসিদ দিয়ে এজেন্টদের পরিশোধ',
'Comm_G_Paying_Body' => 'কমিশনের রসিদ খুলে যোগ করুন-এ ক্লিক করুন। এজেন্ট বেছে নিন: তার অনুমোদিত কমিশনগুলো তালিকায় আসে। যেগুলো পরিশোধ করছেন সেগুলোতে টিক দিন; পরিমাণ ঘরে সেগুলোর মোট বসে যায়, এবং আপনি তা বদলাতে পারেন। রেফারেন্স স্বয়ংক্রিয়ভাবে পূরণ হয় (CR-000001, CR-000002...), এবং আপনি পেমেন্ট পদ্ধতি, তারিখ ও একটি নোট যোগ করতে পারেন।

রসিদ সংরক্ষণ করলে টিক দেওয়া কমিশনগুলো পরিশোধিত হিসেবে চিহ্নিত হয় এবং রসিদের সাথে যুক্ত হয়। শুধু অনুমোদিত কমিশন পরিশোধ করা যায়, তাই আগে কমিশন রিপোর্টে সেগুলো অনুমোদন করুন।

ঋণাত্মক সমন্বয়ও (এজেন্টকে বেশি পরিশোধ করা অর্থ) তালিকায় আসে। এজেন্টের পরের কমিশনগুলোর সাথে এগুলোতেও টিক দিন যাতে সেই পেমেন্ট থেকে এগুলো বাদ যায়।

রসিদ শুধু পরিশোধের একটি রেকর্ড: এটি কোনো ব্যয় তৈরি করে না বা আপনার অ্যাকাউন্টে অর্থ স্থানান্তর করে না। আপনি ব্যয় বা হিসাবরক্ষণে পরিশোধ ট্র্যাক করলে সেখানেও রেকর্ড করুন।',
'Comm_G_T_Snapshot' => 'বিক্রয় বদলালে',
'Comm_G_Snapshot_Body' => 'কমিশন বিক্রয়কে অনুসরণ করে। কমিশনযুক্ত কোনো বিক্রয় বদলালেই এর বর্তমান হিসাব থেকে সেগুলো পুনরায় হিসাব করা হয়: বিক্রয়ের মোট থেকে গৃহীত ফেরত বাদ দিয়ে, এবং পরিশোধিত পরিমাণ থেকে অর্থ ফেরত বাদ দিয়ে।

অপরিশোধিত কমিশন (অপেক্ষমাণ বা অনুমোদিত) শুধু হালনাগাদ হয়। কোনো অনুমোদিত কমিশনের পরিমাণ বদলালে এটি অপেক্ষমাণ-এ ফিরে যায় যাতে কেউ আবার পরীক্ষা করেন। যেটি আর পাওনা নয় (বিক্রয় মুছে ফেলা, পুরোপুরি ফেরত, এজেন্ট বদল) তা সরিয়ে দেওয়া হয়।

পরিশোধিত কমিশন কখনও বদলানো হয় না। পার্থক্যটি সমন্বয় চিহ্নিত একটি নতুন অপেক্ষমাণ সারি হয়: বেশি পাওনা হলে ধনাত্মক (যেমন পরিশোধিত পরিমাণ বিক্রয়ের বাকি অংশ পরিশোধ হয়েছে), এজেন্টকে বেশি পরিশোধ করা হলে ঋণাত্মক (যেমন ফেরতের পরে)। এটি অনুমোদন করে এজেন্টের পরের রসিদে অন্তর্ভুক্ত করুন।

প্রতিটি কমিশন প্রথম অর্জনের সময়কার নিয়মের শর্তাবলি (ধরন, হার, সীমা, সর্বোচ্চ সীমা) ধরে রাখে। পরে কোনো নিয়ম বদলালে বা বন্ধ করলে পুরোনো বিক্রয় পুনরায় হিসাবের সময় সেগুলোর দাম নতুন করে নির্ধারিত হয় না।',
'Comm_G_T_Permissions' => 'কে কী করতে পারেন',
'Comm_G_Permission' => 'অনুমতি',
'Comm_G_Lets_You' => 'যা করার সুযোগ দেয়',
'Comm_G_P_View' => 'কমিশনের সব পৃষ্ঠা দেখা: প্রোগ্রাম, এজেন্ট, নিয়ম, রসিদ, রিপোর্ট ও এই নির্দেশিকা।',
'Comm_G_P_Add' => 'প্রোগ্রাম, এজেন্ট ও নিয়ম তৈরি করা, এবং কমিশনের রসিদ রেকর্ড করা (এজেন্টদের পরিশোধ)।',
'Comm_G_P_Edit' => 'প্রোগ্রাম, এজেন্ট ও নিয়ম সম্পাদনা করা, এবং কমিশন রিপোর্টে কমিশন অনুমোদন বা বাতিল করা।',
'Comm_G_P_Delete' => 'প্রোগ্রাম, এজেন্ট ও নিয়ম মুছে ফেলা।',
'Comm_G_T_Faq' => 'প্রশ্ন ও উত্তর',
'Comm_G_Q_Empty' => 'আমি সব সেটআপ করেছি কিন্তু কমিশন রিপোর্ট খালি।',
'Comm_G_A_Empty' => 'যাচাই করুন যে: নিয়ম তৈরির পরে বিক্রয়টি সংরক্ষণ করা হয়েছে; বিক্রয়টি সম্পন্ন; বিক্রয়ে একজন এজেন্ট আছেন (বিক্রয়ে বেছে নেওয়া, অথবা যে ব্যবহারকারী এটি করেছেন তিনি একজন এজেন্টের সাথে যুক্ত); প্রোগ্রামটি সক্রিয় এবং বিক্রয়ের তারিখ এর তারিখের মধ্যে; নিয়মটি সক্রিয় এবং সেই এজেন্টের ক্ষেত্রে প্রযোজ্য; এবং বিক্রয়টি নিয়মের সর্বনিম্ন সীমার সমান বা বেশি। রিপোর্টের তারিখ ফিল্টারও দেখুন: এটি কমিশন হিসাবের তারিখ অনুযায়ী ফিল্টার করে।',
'Comm_G_Q_Twice' => 'একটি বিক্রয়ে একজন এজেন্ট দুটি কমিশন পেয়েছেন।',
'Comm_G_A_Twice' => 'দুটি নিয়ম পরিশোধ করেছে: হয় প্রোগ্রামটি "মিলে যাওয়া প্রতিটি নিয়ম পরিশোধ করে"-এ সেট করা, অথবা নিয়মগুলো দুটি আলাদা সক্রিয় প্রোগ্রামে আছে (প্রতিটি প্রোগ্রাম নিজে নিজে পরিশোধ করে)। শুধু একটি পরিশোধ করা উচিত হলে প্রোগ্রামটি "শুধু সর্বোচ্চ অগ্রাধিকারের নিয়মটি পরিশোধ করে"-এ সেট করুন। একটি বিক্রয় আবার সংরক্ষণ করলে কখনও কমিশন দ্বিগুণ হয় না।',
'Comm_G_Q_Rate' => 'কোনো নিয়মের হার বদলালে কি পুরোনো কমিশন বদলায়?',
'Comm_G_A_Rate' => 'না। প্রতিটি কমিশন যে নিয়মের অধীনে অর্জিত হয়েছে তার শর্তাবলি ধরে রাখে, পরে বিক্রয় পুনরায় হিসাব করা হলেও। নতুন হার এখন থেকে অর্জিত কমিশনে ব্যবহৃত হয়।',
'Comm_G_Q_Return' => 'ক্রেতা পণ্য ফেরত দিয়েছেন। কমিশনের কী হয়?',
'Comm_G_A_Return' => 'এটি স্বয়ংক্রিয়ভাবে কমে যায়। গৃহীত ফেরত বিক্রয়ের মোট কমায় এবং অর্থ ফেরত পরিশোধিত পরিমাণ কমায়। কমিশন এখনও পরিশোধ না হলে এটি হালনাগাদ হয় (পুরো ফেরতের ক্ষেত্রে সরিয়ে দেওয়া হয়)। ইতিমধ্যে পরিশোধ হয়ে থাকলে একটি ঋণাত্মক সমন্বয় যোগ হয় এবং এজেন্টের পরের রসিদ থেকে বাদ যায়।',
'Comm_G_Q_Wrong_Agent' => 'আমি ভুল এজেন্টের নামে জমা করেছি। কীভাবে ঠিক করব?',
'Comm_G_A_Wrong_Agent' => 'বিক্রয়টি সম্পাদনা করুন, সঠিক বিক্রয় এজেন্ট বেছে নিন এবং সংরক্ষণ করুন। কমিশনগুলো সঠিক এজেন্টের কাছে চলে যায়। প্রথম এজেন্টকে ইতিমধ্যে পরিশোধ করা হয়ে থাকলে তার জন্য একটি ঋণাত্মক সমন্বয় যোগ হয়।',
'Comm_G_Q_Inactive' => 'কোনো এজেন্টকে নিষ্ক্রিয় করলে কী হয়?',
'Comm_G_A_Inactive' => 'তারা নতুন বিক্রয়ে কমিশন পাওয়া বন্ধ করেন এবং এজেন্ট নির্বাচকগুলো থেকে লুকিয়ে যান। তাদের বিদ্যমান কমিশনগুলো থেকে যায়, এখনও অনুমোদন ও পরিশোধ করা যায়, এবং তাদের বিক্রয়ের পরিবর্তন অনুসরণ করে। যে বিক্রয় সেই এজেন্টকে বেছে নিয়ে সংরক্ষণ করা হয়েছে তা অন্য কোনো এজেন্টের কাছে যাবে না।',
'Comm_G_Q_Partial' => 'পরিশোধিত পরিমাণ নিয়ম আংশিক পেমেন্ট কীভাবে সামলায়?',
'Comm_G_A_Partial' => 'অপরিশোধিত বিক্রয় কিছুই অর্জন করে না। প্রথমবার অর্থ গৃহীত হলে (চেকআউটে বা পেমেন্ট যোগ করার সময়) কমিশন তৈরি হয় এবং আরও পেমেন্ট এলে বাড়তে থাকে। এর একটি অংশ ইতিমধ্যে পরিশোধ হয়ে থাকলে বাকিটা একটি ধনাত্মক সমন্বয় হিসেবে আসে।',
'Comm_G_Q_Undo' => 'আমি কি একটি পরিশোধ বা বাতিলকরণ ফিরিয়ে নিতে পারি?',
'Comm_G_A_Undo' => 'পরিশোধ, না: পরিশোধিত চূড়ান্ত এবং রসিদ সম্পাদনা বা মুছে ফেলা যায় না, তাই সংরক্ষণের আগে টিক দেওয়া কমিশন ও পরিমাণ যাচাই করুন। বাতিলকরণ, হ্যাঁ: কমিশন রিপোর্টে সারিটিতে টিক দিয়ে পুনরায় হিসাব করুন-এ ক্লিক করুন, অথবা বিক্রয় সম্পাদনায় বিক্রয়টি আবার সংরক্ষণ করুন।',
'Comm_G_Q_Dates' => 'প্রোগ্রামের তারিখ কোন তারিখ ব্যবহার করে?',
'Comm_G_A_Dates' => 'বিক্রয়ের নিজস্ব তারিখ, সংরক্ষণের দিন নয়। গত মাসের তারিখের একটি বিক্রয় শুধু গত মাসে কার্যকর প্রোগ্রামগুলো ব্যবহার করে।',
'Comm_G_When_Changes' => 'এরপর, ইতিমধ্যে কমিশনযুক্ত কোনো বিক্রয়ের যেকোনো পরিবর্তন নিজে থেকেই সেগুলো হালনাগাদ করে: পেমেন্ট সম্পাদনা বা মুছে ফেলা, ফেরত ও অর্থ ফেরত, অবস্থা সম্পন্ন থেকে বদলানো, অথবা বিক্রয় মুছে ফেলা।',
'Comm_G_F_Program_Mode' => 'এই প্রোগ্রামের একাধিক নিয়ম একই বিক্রয়ের সাথে মিললে কী হয়। "শুধু সর্বোচ্চ অগ্রাধিকারের নিয়মটি পরিশোধ করে": নিয়মগুলো সর্বোচ্চ অগ্রাধিকার থেকে নিচের দিকে যাচাই করা হয় এবং প্রথম যোগ্য নিয়মটি পরিশোধ করে। "মিলে যাওয়া প্রতিটি নিয়ম পরিশোধ করে": সবগুলো পরিশোধ করে এবং পরিমাণগুলো যোগ হয়।',
'Comm_G_Q_Mode_Old' => 'আমি অগ্রাধিকার সেট করেছি, কিন্তু নিয়মগুলো এখনও যোগ হচ্ছে।',
'Comm_G_A_Mode_Old' => 'সেই প্রোগ্রামটি "মিলে যাওয়া প্রতিটি নিয়ম পরিশোধ করে"-এ সেট করা। এই সেটিং আসার আগে তৈরি প্রোগ্রামগুলো সেই আচরণ ধরে রাখে যাতে তাদের পরিশোধ না বদলায়। প্রোগ্রামটি সম্পাদনা করে "শুধু সর্বোচ্চ অগ্রাধিকারের নিয়মটি পরিশোধ করে" বেছে নিন।',
'Comm_G_Q_Negative' => 'ঋণাত্মক কমিশন কেন আছে?',
'Comm_G_A_Negative' => 'এটি একটি সমন্বয়: বিক্রয় এখন যা অর্জন করে তার চেয়ে এজেন্টকে বেশি পরিশোধ করা হয়েছে, কারণ ফেরত, অর্থ ফেরত, কম মোট, এজেন্ট বদল বা বিক্রয় মুছে ফেলা। এটি অনুমোদন করে এজেন্টের পরের রসিদে টিক দিন যাতে এটি কেটে নেওয়া হয়।',
'Comm_Rule_Mode' => 'একাধিক নিয়ম মিললে',
'Comm_Mode_Highest' => 'শুধু সর্বোচ্চ অগ্রাধিকারের নিয়মটি পরিশোধ করে',
'Comm_Mode_All' => 'মিলে যাওয়া প্রতিটি নিয়ম পরিশোধ করে (যোগ হয়)',
'Comm_Mode_Highest_Short' => 'সর্বোচ্চ অগ্রাধিকার জেতে',
'Comm_Mode_All_Short' => 'নিয়মগুলো যোগ হয়',
'Comm_Mode_Highest_Help' => 'নিয়মগুলো সর্বোচ্চ অগ্রাধিকার থেকে নিচের দিকে যাচাই করা হয়; বিক্রয়ের জন্য প্রথম যোগ্য নিয়মটি পরিশোধ করে এবং বাকিগুলো বাদ পড়ে। স্তরের জন্য উপযুক্ত, যেমন অগ্রাধিকার ১০-এ ১০,০০০-এর বেশিতে ৭% এবং অগ্রাধিকার ০-এ বাকি সবকিছুতে ৫%।',
'Comm_Mode_All_Help' => 'এজেন্টের সাথে মিলে যাওয়া প্রতিটি নিয়ম বিক্রয়ে পরিশোধ করে, তাই পরিমাণগুলো যোগ হয়। অগ্রাধিকার শুধু ক্রম নির্ধারণ করে।',
'Comm_Priority_Help_Highest' => 'এই প্রোগ্রাম শুধু সর্বোচ্চ অগ্রাধিকারের যোগ্য নিয়মটি পরিশোধ করে। যে নিয়মগুলোর উপর এটির জেতা উচিত সেগুলোর চেয়ে এই নিয়মকে বেশি অগ্রাধিকার দিন। সমান হলে, নির্দিষ্ট এজেন্ট নিয়ম সব এজেন্ট নিয়মকে হারায়।',
'Comm_Priority_Help_All' => 'এই প্রোগ্রাম মিলে যাওয়া প্রতিটি নিয়ম পরিশোধ করে, তাই এই নিয়ম অন্যগুলোর সাথে যোগ হয়। অগ্রাধিকার শুধু ক্রম নির্ধারণ করে।',
'Comm_Recalculate' => 'পুনরায় হিসাব করুন',
'Comm_Recalculate_Help' => 'টিক দেওয়া সারিগুলোর বিক্রয় তাদের বর্তমান হিসাব থেকে আবার হিসাব করে, বাতিল করা কমিশনসহ।',
'Comm_Adjustment' => 'সমন্বয়',
'Comm_Adjustment_Help' => 'ইতিমধ্যে পরিশোধিত কোনো কমিশনের সংশোধন, কারণ পরে বিক্রয় বদলেছে। ঋণাত্মক পরিমাণ এজেন্টের পরের রসিদ থেকে বাদ যায়।',
'Comm_Cancel_Confirm' => 'নির্বাচিত কমিশনগুলো বাতিল করবেন?',
'Comm_Cancel_Confirm_Help' => 'এগুলো পরিশোধ করা হবে না, এবং পরে পেমেন্ট বা ফেরত এলেও বাতিল থাকবে। বিক্রয় সম্পাদনায় বিক্রয়টি সংরক্ষণ করলে বা পুনরায় হিসাব করুন-এ ক্লিক করলে এগুলো আবার হিসাব করা হয়।',
'Fashion_Tiles_Hint' => 'স্বয়ংক্রিয় ক্যাটাগরি টাইলের বদলে আপনার নিজের টাইল (ছবি, শিরোনাম ও লিংক) যোগ করুন।',

// Online Store: Car Dealership theme
'Car_Dealership_Theme' => 'গাড়ির ডিলারশিপ থিম',
