'Rst_Guide_Step_Db_Help' => 'রেস্টুরেন্টের কিছু টেবিল অনুপস্থিত। সর্বশেষ ডেটাবেস আপডেট (tenant migrations) চালান এবং এই পৃষ্ঠাটি রিলোড করুন।',
'Rst_Guide_Step_Settings' => 'রেস্টুরেন্ট সেটিংস',
'Rst_Guide_Step_Settings_Ok' => 'অর্ডারের ধরন: {types}। একটি ডিফল্ট শাখা নির্ধারিত আছে।',
'Rst_Guide_Step_Settings_Help' => 'আপনি কোন ধরনের অর্ডার নেন, রেস্টুরেন্টের বিক্রয় কোন শাখার স্টক ব্যবহার করবে, সার্ভিস চার্জ, টিপ ও রাউন্ডিং বেছে নিন।',
'Rst_Guide_Step_Floor' => 'ডাইনিং এলাকা ও টেবিল',
'Rst_Guide_Step_Floor_Ok' => '{areas}টি এলাকা, {tables}টি টেবিল।',
'Rst_Guide_Step_Floor_Help' => 'আপনার এলাকাগুলো (ইনডোর, টেরেস…) এবং আসন সংখ্যাসহ সেগুলোর টেবিল যোগ করুন। "একাধিক যোগ করুন" একবারে T1–T20 তৈরি করে।',
'Rst_Guide_Step_Stations' => 'কিচেন স্টেশন',
'Rst_Guide_Step_Stations_Ok' => '{n}টি স্টেশন।',
'Rst_Guide_Step_Stations_Help' => 'স্টেশনগুলো (গ্রিল, ফ্রায়ার, ঠান্ডা খাবার, ডেজার্ট, পানীয়…) কিচেন ডিসপ্লে ভাগ করে, যাতে প্রত্যেক রাঁধুনি কেবল নিজের খাবারগুলো দেখেন।',
'Rst_Guide_Step_Dishes' => 'খাবার ও অ্যাড-অন',
'Rst_Guide_Step_Dishes_Ok' => '{n}টি খাবার সেট আপ করা হয়েছে, {groups}টি অ্যাড-অন গ্রুপ।',
'Rst_Guide_Step_Dishes_Help' => 'খাবারগুলো আপনার সাধারণ পণ্যই। রেস্টুরেন্ট › মেনুতে এগুলোকে একটি স্টেশন, প্রস্তুতির সময়, খাদ্যাভ্যাস ট্যাগ ও অ্যাড-অন গ্রুপ (সাইজ, অতিরিক্ত) দিন।',
'Rst_Guide_Step_Payments' => 'পেমেন্ট',
'Rst_Guide_Step_Payments_Ok' => 'নগদসহ {n}টি পেমেন্ট পদ্ধতি প্রস্তুত, এবং ওয়াক-ইন বিলের জন্য একজন ডিফল্ট ক্রেতা আছে।',
'Rst_Guide_Step_Payments_Help' => 'বিলের জন্য অন্তত একটি সক্রিয় পেমেন্ট পদ্ধতি, একটি নগদ পদ্ধতি (ফেরত নগদ থেকে দেওয়া হয়) এবং সিস্টেম সেটিংসে একজন ডিফল্ট ক্রেতা প্রয়োজন।',
'Rst_Guide_Step_Staff' => 'কর্মীদের অনুমতি',
'Rst_Guide_Step_Staff_Help' => 'যে রোলগুলো অর্ডার নিতে পারে: {waiters}, কিচেন ডিসপ্লে ব্যবহার করতে পারে: {kitchen}, পেমেন্ট নিতে পারে: {cashiers}। প্রতিটি রোলকে কেবল সেই কাজের জন্য যা দরকার তা-ই দিন ("কে কী করেন" দেখুন)।',
'Rst_Guide_Step_First' => 'আপনার প্রথম বিল',
'Rst_Guide_Step_First_Ok' => 'এখন পর্যন্ত {n}টি বিল নেওয়া হয়েছে।',
'Rst_Guide_Step_First_Help' => 'ফ্লোর প্ল্যানে একটি পরীক্ষামূলক টেবিলে অতিথি বসান, একটি খাবার যোগ করুন, পাঠান, কিচেন ডিসপ্লেতে প্রস্তুত চিহ্নিত করুন এবং পেমেন্ট নিন।',
'Rst_Guide_Step_Qr' => 'QR টেবিল অর্ডারিং',
'Rst_Guide_Step_Qr_On' => 'চালু। {n}টি টেবিলে QR কোড আছে।',
'Rst_Guide_Step_Qr_Help' => 'অতিথিরা টেবিলের কোড স্ক্যান করেন, ফোনে খাবার বেছে নেন এবং টেবিলের অর্ডারে পাঠান। রেস্টুরেন্ট সেটিংসে এটি চালু করুন, তারপর কোডগুলো প্রিন্ট করুন।',
'Rst_Guide_Step_Booking' => 'অনলাইন টেবিল বুকিং',
'Rst_Guide_Step_Booking_On' => 'চালু। অনলাইন স্টোর থেকে আসা বুকিংগুলো নিশ্চিত করার জন্য রিজার্ভেশনে আসে।',
'Rst_Guide_Step_Booking_Help' => 'অতিথিদের অনলাইন স্টোর থেকে টেবিল বুক করতে দিন। রেস্টুরেন্ট সেটিংসে বুকিংয়ের সময়, ব্যবধান ও সর্বোচ্চ দলের আকার নির্ধারণ করুন।',
'Rst_Guide_Step_Store' => 'অনলাইন স্টোর ও রেস্টুরেন্ট থিম',
'Rst_Guide_Step_Store_On' => 'রেস্টুরেন্ট থিম সক্রিয়। অনলাইন অর্ডার কিচেনে পৌঁছায়: {mode}।',
'Rst_Guide_Step_Store_Help' => 'অনলাইন স্টোর › সেটিংসে "রেস্টুরেন্ট" থিম বেছে নিন: হোমপেজটি অ্যাড-অন, পিকআপ / ডেলিভারি ও টেবিল বুকিংসহ আপনার মেনু হয়ে যাবে।',
'Rst_Guide_How' => 'এটি কীভাবে কাজ করে',
'Rst_Guide_Service' => 'একটি সার্ভিস, ধাপে ধাপে',
'Rst_Guide_Service_1_T' => 'বসান',
'Rst_Guide_Service_1' => 'ফ্লোর প্ল্যানে একটি খালি টেবিল বেছে নিন, অতিথির সংখ্যা ও ওয়েটার লিখুন, তারপর "অতিথিদের বসান ও অর্ডার নিন"। বুক করা দলকে তাদের বুকিং থেকে বসানো হয়।',
'Rst_Guide_Service_2_T' => 'অর্ডার',
'Rst_Guide_Service_2' => 'অর্ডার স্ক্রিনে খাবারে ট্যাপ করুন। অ্যাড-অন, আসন ও কোর্স বেছে নিন; কিচেনের জন্য একটি নোট যোগ করুন। কোনো কোর্স পরে শুরু করতে সেটি আটকে রাখুন।',
'Rst_Guide_Service_3_T' => 'পাঠান',
'Rst_Guide_Service_3' => '"পাঠান" নতুন খাবারগুলো একটি কিচেন টিকিটে তোলে। যে খাবার এখনও পাঠানো হয়নি তা পরিবর্তন বা সরানো যায়; পাঠানোর পরে কেবল কারণসহ ভয়েড করা যায়।',
'Rst_Guide_Service_4_T' => 'রান্না',
'Rst_Guide_Service_4' => 'কিচেন ডিসপ্লে প্রতিটি স্টেশনে টিকিটটি দেখায়। রাঁধুনিরা এটি শুরু করেন, খাবার শেষ হলে টিক দেন এবং সবকিছু প্রস্তুত হলে বাম্প করেন।',
'Rst_Guide_Service_5_T' => 'পরিবেশন',
'Rst_Guide_Service_5' => 'প্রস্তুত খাবার ফ্লোর প্ল্যান ও অর্ডার স্ক্রিনে দেখায়। ওয়েটার সেগুলো নিয়ে যান এবং "পরিবেশিত চিহ্নিত করুন"-এ ট্যাপ করেন।',
'Rst_Guide_Service_6_T' => 'বিল',
'Rst_Guide_Service_6' => '"বিল ও পেমেন্ট" বিল প্রিন্ট করে ও পেমেন্ট নেয়: পুরো বিল, সমানভাবে ভাগ বা আইটেম অনুযায়ী। প্রতিটি পেমেন্ট একটি সাধারণ POS বিক্রয়।',
'Rst_Guide_Service_7_T' => 'খালি করুন',
'Rst_Guide_Service_7' => 'সব পরিশোধ হলে অর্ডারটি বন্ধ হয় এবং টেবিলটি "পরিষ্কার করা প্রয়োজন" হয়ে যায় (অথবা রেস্টুরেন্ট সেটিংস অনুযায়ী সরাসরি খালি)।',
'Rst_Guide_Roles' => 'কে কী করেন',
'Rst_Guide_Roles_Help' => 'রেস্টুরেন্টের অনুমতিগুলো গ্রুপ অনুমতিতে রোল অনুযায়ী দেওয়া হয়। একজন ব্যবহারকারী একাধিক রোলের অনুমতি পেতে পারেন।',
'Rst_Guide_Job' => 'কাজ',
'Rst_Guide_Give' => 'এই অনুমতিগুলো দিন',
'Rst_Guide_Job_Waiter' => 'ওয়েটার',
'Rst_Guide_Job_Cook' => 'রাঁধুনি',
'Rst_Guide_Job_Cashier' => 'ক্যাশিয়ার',
'Rst_Guide_Job_Host' => 'হোস্ট / ফ্রন্ট ডেস্ক',
'Rst_Guide_Job_Supervisor' => 'সুপারভাইজার',
'Rst_Guide_Job_Manager' => 'ম্যানেজার',
'Rst_Guide_Menu' => 'মেনু, স্টেশন ও অ্যাড-অন',
'Rst_Guide_Menu_1' => 'আপনার বিক্রি করা প্রতিটি পণ্যই একটি খাবার হতে পারে। রেস্টুরেন্ট › মেনু (অথবা পণ্য ফর্মের "খাবারের বিবরণ" কার্ড) রেস্টুরেন্টের তথ্য যোগ করে।',
'Rst_Guide_Menu_2' => 'অ্যাড-অন গ্রুপে মূল্যসহ বিকল্প থাকে: "সাইজ" (১টি বেছে নিন) বা "অতিরিক্ত" (সর্বোচ্চ ৩টি)। প্রতিটি অর্ডারে, অনলাইনেও, নিয়মগুলো যাচাই করা হয়।',
'Rst_Guide_Menu_3' => 'একটি অ্যাড-অন উপকরণ খরচ করতে পারে: "অতিরিক্ত চিজ"-কে আপনার চিজ পণ্যের সাথে যুক্ত করুন, প্রতিটিতে সেই স্টক কমবে।',
'Rst_Guide_Menu_4' => 'এক সুইচে কোনো খাবারকে আজকের জন্য শেষ হিসেবে চিহ্নিত করুন; আগামীকাল এটি নিজে থেকেই ফিরে আসবে। খাবারের সময় (সকালের নাশতা, দুপুরের খাবার, রাতের খাবার) কোনো খাবার কখন দেওয়া হবে তা সীমিত করে।',
'Rst_Guide_Menu_5' => 'রেসিপি হলো একটি কম্বো পণ্য: ভার্চুয়াল কম্বো স্টক চালু থাকলে খাবারটি বিক্রি করলে এর উপাদানগুলো স্টক থেকে কমে।',
'Rst_Guide_Kitchen' => 'কিচেন ডিসপ্লে',
'Rst_Guide_Kitchen_1' => 'কিচেনের একটি স্ক্রিনে রেস্টুরেন্ট › কিচেন খুলুন। স্টেশন বেছে নিন; স্টেশনবিহীন খাবার প্রতিটি স্টেশনে দেখায়।',
'Rst_Guide_Kitchen_2' => 'অপেক্ষার সাথে সাথে টিকিট হলুদ ও পরে লাল হয়ে যায় (রেস্টুরেন্ট সেটিংস › N মিনিট পর দেরি)। নতুন টিকিট এলে একটি বিপ শব্দ হয়।',
'Rst_Guide_Kitchen_3' => 'শুরু → খাবারে টিক দিন → বাম্প। "এই স্টেশনে সম্পন্ন" একটি যৌথ টিকিটে কেবল এই স্টেশনের খাবারগুলো শেষ করে।',
'Rst_Guide_Kitchen_4' => 'পরিবেশিত টিকিট ১৫ মিনিট থাকে যাতে ভুল হলে ফেরত আনা যায়। টিকিট ৮০ মিমি প্রিন্টারে প্রিন্ট করা যায়।',
'Rst_Guide_Kitchen_5' => 'অনলাইন স্টোর ও টেবিলের QR কোড থেকে আসা অর্ডারের টিকিটে "অনলাইন" বা "QR" চিহ্ন থাকে।',
'Rst_Guide_Bills' => 'বিল ও পেমেন্ট',
'Rst_Guide_Bills_1' => 'প্রতিটি পেমেন্ট একটি সাধারণ POS বিক্রয়: স্টক, ক্যাশ রেজিস্টার, হিসাব, লয়্যালটি পয়েন্ট ও ই-ইনভয়েসিং POS-এর মতোই কাজ করে।',
'Rst_Guide_Bills_2' => 'সার্ভিস চার্জ হলো ডাইন-ইনের (অথবা আপনার সেটিং অনুযায়ী প্রতিটি অর্ডারের) করের আগের খাবারের মূল্যের একটি শতাংশ। টিপ একটি নির্ধারিত শতাংশ বা একটি পরিমাণ।',
'Rst_Guide_Bills_3' => 'ছাড় দিতে "রেস্টুরেন্ট ছাড়" অনুমতি প্রয়োজন এবং এটি রেস্টুরেন্ট সেটিংসের সর্বোচ্চ ছাড় দ্বারা সীমিত।',
'Rst_Guide_Bills_4' => 'বিল নিষ্পত্তিকারী পেমেন্টে রাউন্ডিং আপনার ধাপ অনুযায়ী নিচের দিকে হয়, অতিথির অনুকূলে।',
'Rst_Guide_Bills_5' => 'সমানভাবে ভাগ: একটি বিক্রয়, প্রতি জনের জন্য একটি পেমেন্ট লাইন (সেন্ট পর্যন্ত ভাগ)। আইটেম অনুযায়ী ভাগ: প্রত্যেক অতিথির খাবার তাঁর নিজস্ব বিক্রয় হয়; কোনো আসনের খাবার নির্বাচন করতে আসনটি বেছে নিন।',
'Rst_Guide_Bills_6' => 'বিল দেখানোর পরে পরিবর্তিত হলে (QR কোড থেকে খাবার যোগ, টিপ পরিবর্তন), পেমেন্ট প্রত্যাখ্যাত হয়, যাতে অতিথির কাছ থেকে কখনো না দেখা কিছুর জন্য টাকা নেওয়া না হয়।',
'Rst_Guide_Bills_7' => 'পরিশোধিত খাবার ভয়েড করা যায় না। কোনো অর্ডারের অপরিশোধিত বাকি অংশ ভয়েড করা হলে অর্ডারটি পরিশোধিত হিসেবে বন্ধ হয় এবং টেবিলটি খালি করা যায়।',
'Rst_Guide_Bookings' => 'রিজার্ভেশন ও অপেক্ষমাণ তালিকা',
'Rst_Guide_Bookings_1' => 'বুকিং তার সময়কাল জুড়ে একটি টেবিল আটকে রাখে (ডিফল্ট রেস্টুরেন্ট সেটিংসে)। একটি টেবিলে দুটি বুকিং কখনো একই সময়ে পড়তে পারে না।',
'Rst_Guide_Bookings_2' => 'ফ্লোর প্ল্যান প্রতিটি টেবিলের পরবর্তী বুকিং দেখায় এবং তা শীঘ্রই আসন্ন হলে সতর্ক করে; "তাঁরা এসেছেন — বসান" দলটিকে বসায়।',
'Rst_Guide_Bookings_3' => 'অনুপস্থিতির সময় পেরোলে দেরি করা দলকে অনুপস্থিত হিসেবে চিহ্নিত করা যায়; ভুল হলে পুনরুদ্ধার করা যায়।',
'Rst_Guide_Bookings_4' => 'অপেক্ষমাণ তালিকা ওয়াক-ইন অতিথিদের জানানো অপেক্ষার সময়সহ ক্রমানুসারে রাখে। টেবিল প্রস্তুত হলে তাঁদের কল বা WhatsApp করুন, তারপর বসান।',
'Rst_Guide_Bookings_5' => 'অনলাইন বুকিং আপনার নিশ্চিত করার জন্য "বুক করা" হিসেবে আসে (সাইডবারের একটি ব্যাজ সেগুলো গণনা করে)।',
'Rst_Guide_Online' => 'অনলাইন অর্ডার, QR মেনু ও অনলাইন বুকিং',
'Rst_Guide_Online_1' => 'রেস্টুরেন্ট স্টোর থিমে অনলাইন স্টোরের হোমপেজ হয় অ্যাড-অন ও খাদ্যাভ্যাস ফিল্টারসহ আপনার মেনু; ক্রেতারা যথারীতি চেকআউটে পেমেন্ট করেন।',
'Rst_Guide_Online_2' => '"কিচেনে অনলাইন অর্ডার" ঠিক করে সেগুলো কখন কিচেন ডিসপ্লেতে পৌঁছাবে: দেওয়ার সময় (পরিশোধিত, অথবা সাইন-ইন করা ক্রেতা যিনি ডেলিভারি / পিকআপে পেমেন্ট করবেন), গ্রহণ করার সময়, অথবা কখনো না।',
'Rst_Guide_Online_3' => 'টেবিলের QR কোড (ফ্লোর সেটআপ › টেবিলের QR কোড) সেই টেবিলের জন্য মেনু খোলে। "নতুন লিংক" একটি প্রিন্ট করা কোড অকার্যকর করে।',
'Rst_Guide_Online_4' => '"QR অর্ডার সরাসরি কিচেনে পাঠান" চালু না থাকলে QR অর্ডারগুলো টেবিলের অর্ডারে ওয়েটারের পাঠানোর অপেক্ষায় থাকে। অতিথিরা কর্মীদের কাছে পেমেন্ট করেন।',
'Rst_Guide_Online_5' => 'অনলাইন বুকিং কেবল সেই সময়গুলো দেয় যখন দলের উপযোগী একটি টেবিল পুরো বুকিং জুড়ে খালি থাকে, এবং প্রতিটি ফোন নম্বরকে সর্বোচ্চ ৩টি আসন্ন বুকিংয়ে সীমিত রাখে।',
'Rst_Guide_Online_6' => 'এসবই অনলাইন স্টোরের অংশ: এটি চালু থাকতে হবে এবং আপনার প্ল্যানে অন্তর্ভুক্ত থাকতে হবে।',
'Rst_Guide_Reports' => 'ড্যাশবোর্ড ও রিপোর্ট',
'Rst_Guide_Reports_1' => 'ড্যাশবোর্ড আজকের তথ্য গত সপ্তাহের একই দিনের সাথে তুলনা করে দেখায়: বিক্রয়, বিল, অতিথি, গড় বিল, ভয়েড ও ছাড়, সাথে এই মুহূর্তে কী ঘটছে।',
'Rst_Guide_Reports_2' => 'বিক্রয় হলো রেস্টুরেন্টের বিল এবং কিচেনে পৌঁছানো অনলাইন অর্ডার। খাবারের বিক্রয় ও মার্জিন করের আগের, প্রতিটি পণ্যের ক্রয়মূল্য ব্যবহার করে।',
'Rst_Guide_Reports_3' => 'রিপোর্ট: দিন ও পেমেন্ট পদ্ধতি অনুযায়ী বিক্রয়, খাবার, ভয়েড ও বাতিল (কারণসহ), কর্মী, কিচেনের সময় ও রিজার্ভেশন — প্রতিটি Excel-এ এক্সপোর্ট করা যায়।',
'Rst_Guide_Reports_4' => 'কিছু শাখায় সীমিত কর্মীরা কেবল তাঁদের শাখাগুলো দেখেন; শাখাবিহীন অর্ডার সবার জন্য উন্মুক্ত।',
'Rst_Guide_Faq' => 'জেনে রাখা ভালো',
'Rst_Guide_Faq_1_Q' => '"পাঠান" চাপার আগেই একটি টেকঅ্যাওয়ের পেমেন্ট হয়ে গেছে। এটি কি রান্না হবে?',
'Rst_Guide_Faq_1_A' => 'হ্যাঁ। পেমেন্ট করলে এখনও না পাঠানো সব খাবার কিচেনে চলে যায়।',
'Rst_Guide_Faq_2_Q' => 'আমি কেন একটি টেবিল খালি করতে পারছি না?',
'Rst_Guide_Faq_2_A' => 'এর অর্ডারে এখনও অপরিশোধিত খাবার আছে। পেমেন্ট নিন, যা খাওয়া হয়নি তা ভয়েড করুন, অথবা অর্ডারটি বাতিল করুন (কেবল যখন এখনও কিছুই পরিশোধ হয়নি)।',
'Rst_Guide_Faq_3_Q' => 'দুটি টেবিল একসাথে জোড়া লাগানো হয়েছে। তাদের অর্ডারের কী হবে?',
'Rst_Guide_Faq_3_A' => '"টেবিল যুক্ত করুন" দ্বিতীয় টেবিলের খাবার (এবং যেকোনো পেমেন্ট) মূল টেবিলের অর্ডারে সরিয়ে নেয়; "বিচ্ছিন্ন করুন" টেবিলগুলো আবার আলাদা করে।',
'Rst_Guide_Faq_4_Q' => 'এখানে কার্ড পেমেন্টে কি Stripe ব্যবহার করা যায়?',
'Rst_Guide_Faq_4_A' => 'না। Stripe কার্ড পেমেন্টের জন্য POS কার্ড ফর্ম প্রয়োজন; কার্ড টার্মিনালের জন্য "কার্ড"-এর মতো একটি পেমেন্ট পদ্ধতি যোগ করুন এবং বিলে সেটি ব্যবহার করুন।',
'Rst_Guide_Faq_5_Q' => 'একটি খাবার কেবল একটি শাখায় স্টকে নেই।',
'Rst_Guide_Faq_5_A' => 'স্টক অর্ডারের শাখা থেকে নেওয়া হয় (টেবিলের এলাকা, নইলে রেস্টুরেন্ট সেটিংসের ডিফল্ট শাখা)। দ্রুত অর্ডার বন্ধ করতে "আজ শেষ" ব্যবহার করুন।',
'Rst_Guide_Faq_6_Q' => 'আমার কি প্রিন্টার লাগবে?',
'Rst_Guide_Faq_6_A' => 'না। বিল, রসিদ ও কিচেন টিকিট যেকোনো প্রিন্টারে ব্রাউজার থেকে প্রিন্ট হয়; ৮০ মিমি রসিদ প্রিন্টার সবচেয়ে উপযুক্ত।',
'Rst_Guide_Faq_7_Q' => 'অনলাইন স্টোরে রেস্টুরেন্টের মেনু কোথা থেকে আসে?',
'Rst_Guide_Faq_7_A' => 'একই পণ্য, ক্যাটাগরি ও অ্যাড-অন থেকে। অনলাইন স্টোর থেকে লুকানো পণ্য এবং স্টোরে না দেখানো ক্যাটাগরি অনলাইন মেনু ও QR মেনুতে থাকে না।',

// Rental — business types + website booking (Rental store theme).
'Rental_Website_Not_Ready' => 'ব্যবসার ধরন ও ওয়েবসাইট বুকিং ব্যবহার করতে সর্বশেষ আপডেট ইনস্টল করুন।',
'Rental_Business_Type' => 'ব্যবসার ধরন',
'Rental_Business_Type_Help' => 'আপনি কী ভাড়া দেন তাতে টিক দিন। আইটেম ফর্ম, ক্যাটাগরি, ফিল্টার ও আপনার ওয়েবসাইট তখন কেবল এই ধরনগুলো ও সেগুলোর ফিল্ড দেখাবে।',
'Rental_Business_Type_All' => 'কিছুই টিক দেওয়া নেই: সব ধরন উপলব্ধ।',
'Rental_Website_Booking' => 'ওয়েবসাইট বুকিং',
'Rental_Website_Theme_Off' => 'আপনার অনলাইন স্টোর অন্য থিম ব্যবহার করছে। আপনার ভাড়ার আইটেম প্রকাশ করতে স্টোর সেটিংসে ভাড়া থিম বেছে নিন।',
'Rental_Open_Store_Settings' => 'স্টোর সেটিংস খুলুন',
'Rental_Website_Booking_Help' => 'ভিজিটররা আপনার ওয়েবসাইটে তারিখ বেছে নিয়ে বুকিং অনুরোধ পাঠান। এটি রিজার্ভেশনে হোল্ড হিসেবে আসে: নিশ্চিত করুন, চুক্তিতে রূপান্তর করুন বা বাতিল করুন।',
'Rental_Website_Hold' => 'একটি অনুরোধ যতক্ষণ হোল্ড থাকবে',
'Rental_Website_Hold_Help' => 'আপনি উত্তর দেওয়া পর্যন্ত আইটেমগুলো এতক্ষণ আটকে থাকে। নিশ্চিত করলে ভাড়ার শেষ পর্যন্ত আটকে থাকে।',
'Rental_Website_Notice' => 'ন্যূনতম অগ্রিম সময়',
'Rental_Website_Notice_Help' => 'ওয়েবসাইট বুকিং কত তাড়াতাড়ি শুরু হতে পারে।',
'Rental_Website_Ahead' => 'যত আগে পর্যন্ত বুক করা যাবে',
'Rental_Website_Ahead_Help' => 'ভিজিটররা কত দিন আগে পর্যন্ত বুক করতে পারবেন।',
'Rental_Website_Login' => 'সাইন-ইন আবশ্যক',
'Rental_Website_Login_Help' => 'কেবল স্টোর অ্যাকাউন্টধারী ক্রেতারা অনুরোধ পাঠাতে পারবেন।',
'Rental_Pickup_Locations' => 'পিকআপের স্থান',
'Rental_Pickup_Locations_Help' => 'যানবাহন: ক্রেতারা পিকআপ ও ফেরতের জন্য যে স্থানগুলো বেছে নিতে পারেন। সবকিছু আপনার শাখা থেকে সংগ্রহ করা হলে খালি রাখুন।',
'Rental_Pickup_Locations_Placeholder' => 'যেমন বিমানবন্দর; শহরের কেন্দ্রীয় অফিস',
'Rental_Booking_Form_Fields' => 'বুকিং ফর্মের ফিল্ড',
'Rental_Booking_Form_Fields_Help' => 'ব্যবসার ধরন অনুযায়ী ওয়েবসাইটের বুকিং ফর্মে কী জিজ্ঞাসা করা হবে। নাম, ফোন ও ইমেইল সবসময় জিজ্ঞাসা করা হয়।',
'Rental_Field_Location_Hint' => 'কেবল পিকআপের স্থান নির্ধারিত থাকলে দেখানো হয়।',
'Rental_Website_Terms' => 'ওয়েবসাইটে ভাড়ার শর্তাবলি',
'Rental_Website_Terms_Help' => 'পূরণ করা থাকলে, অনুরোধ পাঠানোর আগে ক্রেতাদের এই শর্তাবলি মেনে নিতে হবে।',
'Rental_Mode_Required' => 'আবশ্যক',
'Rental_Mode_Optional' => 'ঐচ্ছিক',
