'Bkm_Guide_Step_Crm_Unavailable' => 'আপনার প্ল্যানে CRM থাকা ও তা চালু থাকা প্রয়োজন।',
'Bkm_Guide_Step_Portal' => 'ক্লায়েন্ট পোর্টালে বুকিং',
'Bkm_Guide_Step_Portal_Ok' => 'পোর্টাল অ্যাকাউন্ট থাকা ক্রেতারা সেখানে তাঁদের বুকিং দেখতে পান।',
'Bkm_Guide_Step_Portal_Help' => 'ক্রেতারা যাতে তাঁদের ভিজিট অনুসরণ করতে পারেন, সেজন্য ক্লায়েন্ট পোর্টাল ও এর বুকিং অংশ চালু করুন।',
'Bkm_Guide_How' => 'কীভাবে কাজ করে',
'Bkm_Guide_Website' => 'ওয়েবসাইট থেকে একটি বুকিং',
'Bkm_Guide_Website_1_T' => 'একটি সেবা বেছে নিন',
'Bkm_Guide_Website_1' => 'ক্রেতা আপনার হোম পেজের ফর্ম বা বুক পেজ থেকে শুরু করেন।',
'Bkm_Guide_Website_2_T' => 'সময় বেছে নিন বা অনুরোধ পাঠান',
'Bkm_Guide_Website_2' => 'খালি সময় আসে আপনার কর্মীদের কাজের সময়, ছুটির দিন ও অন্যান্য বুকিং থেকে; অনুরোধে শুধু পছন্দের দিন ও দিনের অংশ দেওয়া হয়।',
'Bkm_Guide_Website_3_T' => 'তাঁদের তথ্য',
'Bkm_Guide_Website_3' => 'নাম, ফোন, ইমেইল এবং আপনার ব্যবসার ধরন অনুযায়ী প্রশ্ন।',
'Bkm_Guide_Website_4_T' => 'অগ্রিম',
'Bkm_Guide_Website_4' => 'আপনি চাইলে, সময়টি ধরে রাখতে তাঁরা সঙ্গে সঙ্গে তা পরিশোধ করেন।',
'Bkm_Guide_Website_5_T' => 'আপনার অপেক্ষায়',
'Bkm_Guide_Website_5' => 'এটি অনুরোধ-এ অপেক্ষমাণ হিসেবে আসে, এবং সময়টি তাঁদের জন্য সংরক্ষিত থাকে (স্বয়ংক্রিয় নিশ্চিতকরণ চালু না থাকলে)।',
'Bkm_Guide_Website_6_T' => 'তাঁদের বুকিং পেজ',
'Bkm_Guide_Website_6' => 'তাঁরা ইমেইলের লিংক থেকে এটি অনুসরণ করেন: অবস্থা, ক্যালেন্ডারে যোগ, বাতিল, প্রস্তাবিত সময়ের উত্তর।',
'Bkm_Guide_Requests' => 'অনুরোধের উত্তর দেওয়া',
'Bkm_Guide_Requests_1' => 'অনুরোধ-এ আপনার অপেক্ষায় থাকা প্রতিটি বুকিং দেখায়, সবচেয়ে পুরোনো সংরক্ষণ আগে, মেনুতে একটি ব্যাজসহ।',
'Bkm_Guide_Requests_2' => 'আপনি খালি রাখলে নিশ্চিত করুন আপনার হয়ে একজন কর্মী বেছে নেয়, এবং সময়টি এখনো খালি কিনা যাচাই করে।',
'Bkm_Guide_Requests_3' => 'তাঁদের সময় সম্ভব না হলে অন্য সময় প্রস্তাব করুন — তাঁরা তাঁদের বুকিং পেজ থেকে তা গ্রহণ করেন।',
'Bkm_Guide_Requests_4' => 'কারণসহ প্রত্যাখ্যান করুন; ক্রেতা তা দেখতে পান।',
'Bkm_Guide_Requests_5' => 'সংরক্ষণের মেয়াদ শেষ হলে সময়টি খালি হয়; আপনি উত্তর না দেওয়া পর্যন্ত বুকিংটি থাকে।',
'Bkm_Guide_Day' => 'নির্ধারিত দিনে',
'Bkm_Guide_Day_1' => 'দিনের দৃশ্য প্রত্যেক কর্মীর বুকিং পাশাপাশি দেখায়।',
'Bkm_Guide_Day_2' => 'ক্রেতা এলে এসেছেন হিসেবে চিহ্নিত করুন।',
'Bkm_Guide_Day_3' => 'সম্পন্ন ও চার্জ করুন POS-এর মাধ্যমে বিক্রয় তৈরি করে, অগ্রিম আগেই গণনা করে।',
'Bkm_Guide_Day_4' => 'অন্যভাবে পরিশোধ হলে চার্জ ছাড়া সম্পন্ন করুন।',
'Bkm_Guide_Day_5' => 'শুরুর সময় পার হলে আসেননি হিসেবে চিহ্নিত করুন।',
'Bkm_Guide_Day_6' => 'ড্যাশবোর্ডে আজকের সময়সূচি, এখনো কী বাকি এবং কী এখনো চার্জ করা হয়নি তা দেখায়।',
'Bkm_Guide_Deposits' => 'অগ্রিম',
'Bkm_Guide_Deposits_1' => 'বুকিং সেটিংস › অগ্রিম-এ পরিমাণ নির্ধারণ করুন; একটি সেবার নিজস্ব অগ্রিম থাকতে পারে।',
'Bkm_Guide_Deposits_2' => 'ক্রেতারা অনলাইন স্টোর › পেমেন্ট গেটওয়ে-তে সেট আপ করা পেমেন্ট প্রদানকারী দিয়ে, আপনার মূল মুদ্রায় পরিশোধ করেন।',
'Bkm_Guide_Deposits_3' => 'পেমেন্টের জন্য সময়টি সংরক্ষিত থাকে; অপরিশোধিত বুকিং স্বয়ংক্রিয়ভাবে বাতিল করা যায়।',
'Bkm_Guide_Deposits_4' => 'ক্রেতা ফিরে না এলেও সম্পন্ন হওয়া পেমেন্ট স্বয়ংক্রিয়ভাবে শনাক্ত করা হয়।',
'Bkm_Guide_Deposits_5' => 'বুকিং চার্জ করার সময় অগ্রিমটি বিক্রয়ের প্রথম পেমেন্ট হয়।',
'Bkm_Guide_Deposits_6' => 'অর্থ ফেরত আপনার পেমেন্ট প্রদানকারীতে দেওয়া হয়; তারপর বুকিংয়ে অগ্রিম ফেরত হিসেবে চিহ্নিত করুন।',
'Bkm_Guide_Messages' => 'ইমেইল, WhatsApp ও রিমাইন্ডার',
'Bkm_Guide_Messages_1' => 'বুকিং গৃহীত, নিশ্চিত, প্রত্যাখ্যাত, পরিবর্তিত বা বাতিল হলে ক্রেতারা একটি ইমেইল পান।',
'Bkm_Guide_Messages_2' => 'প্রতিটি নতুন ওয়েবসাইট বুকিং, ক্রেতার বাতিল ও পরিশোধিত অগ্রিমের জন্য আপনি একটি পান।',
'Bkm_Guide_Messages_3' => 'প্রতিটি নিশ্চিত ভিজিটের আগে একটি রিমাইন্ডার যায় (বুকিং সেটিংস › নোটিফিকেশন)।',
'Bkm_Guide_Messages_4' => 'একই বার্তা সেখানে পাঠাতে "WhatsApp-এও পাঠান" চালু করুন।',
'Bkm_Guide_Messages_5' => 'প্রতিটি বার্তা বুকিংয়ে তালিকাভুক্ত থাকে, আর না পাঠানো হলে কেন পাঠানো হয়নি তাও।',
'Bkm_Guide_Customers' => 'ক্রেতা, CRM ও পোর্টাল',
'Bkm_Guide_Customers_1' => 'একটি ওয়েবসাইট বুকিং আপনার ক্রেতা তালিকায় যোগ হয়; একই ইমেইল ও ফোন দিয়ে আবার বুক করলে তাঁকে মিলিয়ে নেওয়া হয়।',
'Bkm_Guide_Customers_2' => 'আপনার প্ল্যানে CRM থাকলে বুকিং ক্রেতা বা তাঁর লিডে নোট করা যায়, এবং অনুরোধ থেকে ডিল খোলা যায়।',
'Bkm_Guide_Customers_3' => 'ক্লায়েন্ট পোর্টাল অ্যাকাউন্ট থাকা ক্রেতারা সেখানে তাঁদের বুকিং দেখতে পান এবং বাতিল বা প্রস্তাবিত সময়ের উত্তর দিতে পারেন।',
'Bkm_Guide_Customers_4' => 'সাইন-ইন করা স্টোর ক্রেতারা আমার অ্যাকাউন্ট-এ তাঁদের বুকিং পান।',
'Bkm_Guide_Roles' => 'কে কী করতে পারবেন',
'Bkm_Guide_Roles_Help' => 'প্রতিটি ভূমিকাকে শুধু প্রয়োজনীয় অনুমতি দিন (সেটিংস › গ্রুপ অনুমতি)।',
'Bkm_Guide_Job' => 'কাজ',
'Bkm_Guide_Give' => 'তাঁদের দিন',
'Bkm_Guide_Job_Front_Desk' => 'ফ্রন্ট ডেস্ক',
'Bkm_Guide_Job_Staff_Member' => 'কর্মী',
'Bkm_Guide_Job_Manager' => 'ম্যানেজার',
'Bkm_Guide_Job_Owner' => 'মালিক বা হিসাবরক্ষক',
'Bkm_Guide_Faq' => 'প্রশ্নাবলি',
'Bkm_Guide_Faq_1_Q' => 'একটি সেবা ওয়েবসাইটে দেখা যাচ্ছে না কেন?',
'Bkm_Guide_Faq_1_A' => 'এর জন্য বুকিংয়ের বিবরণ (সেবা), "ওয়েবসাইটে দেখান" চালু, পণ্যটি সক্রিয়, এবং — সময় বেছে নিতে — এটি দেন এমন অনলাইনে বুকযোগ্য কেউ থাকা প্রয়োজন।',
'Bkm_Guide_Faq_2_Q' => 'কোনো খালি সময় নেই কেন?',
'Bkm_Guide_Faq_2_A' => 'কর্মীদের কাজের সময়, ছুটির দিন, প্রতিষ্ঠানের ছুটি ও অনুমোদিত ছুটি, নোটিশের সময় এবং ক্রেতারা কত দিন আগে বুক করতে পারবেন তা যাচাই করুন।',
'Bkm_Guide_Faq_3_Q' => 'দুজন ক্রেতা কি একই সময় নিতে পারেন?',
'Bkm_Guide_Faq_3_A' => 'না। বুক করার সময় সময়টি আবার যাচাই করা হয়, এবং সংরক্ষিত বা নিশ্চিত বুকিং তা আটকে রাখে। ক্লাসে সীমা পর্যন্ত আসন ভাগ করা হয়।',
'Bkm_Guide_Faq_4_Q' => 'সংরক্ষণের মেয়াদ শেষ হলে কী হয়?',
'Bkm_Guide_Faq_4_A' => 'সময়টি আবার অন্যদের জন্য খালি হয়। আপনি উত্তর না দেওয়া পর্যন্ত বুকিংটি অনুরোধ-এ থাকে (অথবা অগ্রিম পরিশোধ না হলে বাতিল হয়)।',
'Bkm_Guide_Faq_5_Q' => 'ক্রেতাদের কি অ্যাকাউন্ট লাগবে?',
'Bkm_Guide_Faq_5_A' => 'না। তাঁরা তাঁদের বুকিং পেজের একটি ব্যক্তিগত লিংক পান। স্টোর ও পোর্টাল অ্যাকাউন্টেও তাঁদের বুকিং তালিকাভুক্ত থাকে।',
'Bkm_Guide_Faq_6_Q' => 'টাকা কোথায় যায়?',
'Bkm_Guide_Faq_6_A' => 'অগ্রিম যায় আপনার পেমেন্ট প্রদানকারীর কাছে; বাকিটা বুকিং চার্জ করার সময় POS-এ নেওয়া হয়। রিপোর্টে ওই বিক্রয় থেকে রাজস্ব গণনা করা হয়।',
'Bkm_Guide_Faq_7_Q' => 'একজন ক্রেতা ইমেইল পাননি কেন?',
'Bkm_Guide_Faq_7_A' => 'বুকিংটি খুলুন: এর বার্তা তালিকায় প্রতিটি ইমেইল পাঠানো, ব্যর্থ বা বাদ দেওয়া হয়েছে কিনা এবং কেন, তা দেখায়।',
'Bkm_Staff_Removed' => 'সরানো হয়েছে',
'Bkm_Staff_Not_Bookable' => 'আর বুকযোগ্য নয়',
'Bkm_Requests_Cut' => 'সবচেয়ে পুরোনো {n}টি দেখানো হচ্ছে। বাকিগুলো দেখতে কিছু অনুরোধের উত্তর দিন, অথবা খুঁজুন।',

// AI Assistant (Claude)
'AI_Assistant' => 'AI সহকারী',
'AI_Settings' => 'AI সহকারী সেটিংস',
'Ai_Add_To_Existing' => 'বিদ্যমানের সাথে যোগ করুন',
'Ai_Api_Key' => 'Claude API কী',
'Ai_Applied' => 'খসড়া প্রয়োগ করা হয়েছে — পর্যালোচনা করে পণ্যটি সংরক্ষণ করুন।',
'Ai_Apply_To_Form' => 'ফর্মে প্রয়োগ করুন',
'Ai_Ask' => 'সহকারীকে জিজ্ঞাসা করুন',
'Ai_Bulk_Count' => '{n}টি পণ্য নির্বাচিত',
'Ai_Bulk_Hint' => 'AI প্রতিটি পণ্যের সংরক্ষিত তথ্য ও ছবি থেকে একটি খসড়া লেখে। আপনি খসড়াগুলো পর্যালোচনা করে কোনগুলো সংরক্ষণ করবেন তা বেছে নেন।',
