'Pf_Guide_3' => 'প্রথম সফল সংযোগ পরীক্ষায় ওয়েবহুক নিবন্ধিত হয়, ফলে Printful অর্ডারের পরিবর্তন ও চালানের খবর Stocky-কে জানাতে পারে।',
'Pf_Guide_4' => 'পণ্য ট্যাব: পণ্য ইমপোর্ট করুন। আপনার মুদ্রা ছাড়া অন্য মুদ্রায় দাম দেওয়া পণ্যগুলো নিষ্ক্রিয় অবস্থায় ইমপোর্ট হয়, যতক্ষণ না আপনি সেটিংস ট্যাবে বিনিময় হার সেট করেন বা হাতে দাম দেন।',
'Pf_Guide_5' => 'সেটিংস ট্যাব: ওয়েব অর্ডার কখন Printful-এ যাবে তা বেছে নিন। অর্ডারের শুধু Printful আইটেমগুলো পাঠানো হয়; বাকি সব আপনি নিজে পাঠান।',
'Pf_Guide_6' => 'স্বয়ংক্রিয় নিশ্চিতকরণ চালু না থাকলে অর্ডারগুলো Printful-এ খসড়া হিসেবে আসে। প্রিন্ট করাতে অর্ডার ট্যাবে (বা Printful-এ) খসড়াগুলো নিশ্চিত করুন।',
'Pf_Guide_7' => 'চেকআউটে Printful-এর নিজস্ব ডেলিভারি চার্জের জন্য, স্টোর > ডেলিভারি পদ্ধতি অংশে একটি ডেলিভারি পদ্ধতি যোগ করুন এবং মূল্য নির্ধারণ Printful রেটে সেট করুন।',
'Pf_Guide_Duplicate' => 'একই পণ্য বিক্রি করে এমন কোনো Shopify বা WooCommerce শপের সাথেও এই Printful স্টোরটি সংযুক্ত করবেন না, নইলে Printful সেই অর্ডারগুলো দুবার পাবে।',
