'Ai_Gemini_Api_Key' => 'Gemini (Google) API কী',
'Ai_Gemini_Key_Help' => 'aistudio.google.com/apikey-এ একটি তৈরি করুন। এটি এনক্রিপ্ট করে সংরক্ষণ করা হয় এবং কখনো ব্রাউজারে পাঠানো হয় না।',
'Ai_Gemini_Model_Help' => 'একটি প্রস্তাবিত মডেল বেছে নিন অথবা আপনার কী ব্যবহার করতে পারে এমন যেকোনো Gemini মডেল id টাইপ করুন।',
'Mkg_Guide' => 'মার্কেটিং গাইড',
'Mkg_Guide_Subtitle' => 'আপনার চ্যানেল সেটআপ করুন, সঠিক ক্রেতাদের কাছে পৌঁছান এবং প্রতিটি বার্তার কী হলো তা দেখুন।',
'Mkg_Guide_Stuck_Alert' => '{n}টি ক্যাম্পেইন পাঠানো হচ্ছে অবস্থায় আটকে আছে',
'Mkg_Guide_Stuck_Alert_Help' => '৩০ মিনিটের বেশি সময় ধরে কিছুই পাঠানো হয়নি। আবার শুরু করতে ক্যাম্পেইনটি খুলে এখনই পাঠান-এ ক্লিক করুন; যেসব ক্রেতার কাছে ইতিমধ্যে পৌঁছানো হয়েছে তাদের আবার বার্তা পাঠানো হবে না। বারবার এমন হলে আপনার প্ল্যাটফর্ম অ্যাডমিনিস্ট্রেটরকে ব্যাকগ্রাউন্ড জব চলছে কিনা যাচাই করতে বলুন।',
'Mkg_Guide_Your_Setup' => 'আপনার সেটআপ',
'Mkg_Guide_Your_Setup_Help' => 'এই ওয়ার্কস্পেসের বর্তমান অবস্থা। প্রতিটি ধাপ সংশ্লিষ্ট পেজের লিংক দেয়।',
'Mkg_Guide_Done_N' => '{total}টির মধ্যে {done}টি সম্পন্ন',
