'Mkg_Guide_Step_Customers_Ok' => '{n} জন ক্রেতা: {email} জনের ইমেইল ঠিকানা আছে, {phone} জনের ফোন নম্বর আছে।',
'Mkg_Guide_Step_Customers_Help' => 'ইমেইল ঠিকানা বা ফোন নম্বরসহ ক্রেতা যোগ বা ইমপোর্ট করুন।',
