'Mkg_Guide_Step_Channel_Help' => 'মার্কেটিং সেটিংসে ইমেইল, SMS বা WhatsApp চালু করুন।',
'Mkg_Guide_Step_Mail' => 'ইমেইল: মেইল সার্ভার',
'Mkg_Guide_Step_Mail_Ok' => 'আপনার মেইল সার্ভার সেট করা আছে। ইমেইল ক্যাম্পেইন এর মাধ্যমেই পাঠানো হয়।',
'Mkg_Guide_Step_Mail_Help' => 'ইমেইল চালু আছে কিন্তু কোনো মেইল সার্ভার সেট করা নেই, তাই প্রতিটি ইমেইল বাদ দেওয়া হচ্ছে। মেইল সেটিংসে একটি যোগ করুন।',
'Mkg_Guide_Step_Sms' => 'SMS: গেটওয়ে',
'Mkg_Guide_Step_Sms_Ok' => 'SMS গেটওয়ে সেট করা আছে।',
'Mkg_Guide_Step_Sms_Help' => 'SMS চালু আছে কিন্তু কোনো API URL নেই, তাই প্রতিটি SMS বাদ দেওয়া হচ্ছে। মার্কেটিং সেটিংসে গেটওয়ের তথ্য পূরণ করুন।',
'Mkg_Guide_Step_Whatsapp' => 'WhatsApp: API',
'Mkg_Guide_Step_Whatsapp_Ok' => 'WhatsApp API সেট করা আছে।',
'Mkg_Guide_Step_Whatsapp_Help' => 'WhatsApp চালু আছে কিন্তু কোনো API URL নেই, তাই প্রতিটি বার্তা বাদ দেওয়া হচ্ছে। মার্কেটিং সেটিংসে API-র তথ্য পূরণ করুন।',
'Mkg_Guide_Step_Segments' => 'ক্রেতা সেগমেন্ট',
'Mkg_Guide_Step_Segments_Ok' => '{n}টি সেগমেন্ট সংরক্ষিত।',
'Mkg_Guide_Step_Segments_Help' => 'সবার বদলে শহর, শেষ ক্রয়, ক্রয়ের সংখ্যা বা মোট খরচ অনুযায়ী ক্রেতাদের লক্ষ্য করুন।',
'Mkg_Guide_Step_Templates' => 'বার্তার টেমপ্লেট',
'Mkg_Guide_Step_Templates_Ok' => '{n}টি টেমপ্লেট পুনরায় ব্যবহারের জন্য প্রস্তুত।',
'Mkg_Guide_Step_Templates_Help' => 'যে বার্তাগুলো প্রায়ই পাঠান সেগুলো সংরক্ষণ করুন এবং সেগুলো থেকে ক্যাম্পেইন শুরু করুন।',
'Mkg_Guide_Step_Schedule' => 'সময়সূচি',
'Mkg_Guide_Step_Schedule_Ok' => 'চালু। ক্যাম্পেইন পরে পাঠানোর জন্য সেট করা যায়।',
'Mkg_Guide_Step_Schedule_Help' => 'আপনার বেছে নেওয়া তারিখ ও সময়ে ক্যাম্পেইন পাঠাতে চালু করুন।',
'Mkg_Guide_Step_First' => 'আপনার প্রথম ক্যাম্পেইন পাঠান',
'Mkg_Guide_Step_First_Ok' => '{n}টি ক্যাম্পেইন পাঠানো হয়েছে।',
'Mkg_Guide_Step_First_Help' => 'একটি ক্যাম্পেইন তৈরি করুন এবং আগে একটি ছোট সেগমেন্টে পরীক্ষা করুন।',
'Mkg_Guide_Step_Health' => 'ডেলিভারির অবস্থা',
'Mkg_Guide_Step_Health_Stuck' => '{n}টি ক্যাম্পেইন পাঠানো হচ্ছে অবস্থায় আটকে আছে। আবার শুরু করতে সেগুলো খুলে এখনই পাঠান-এ ক্লিক করুন।',
'Mkg_Guide_Step_Health_Failed' => 'গত ৩০ দিনে {n}টি বার্তা ব্যর্থ হয়েছে এবং {skipped}টি বাদ দেওয়া হয়েছে। প্রতিটি ত্রুটি দেখতে একটি ক্যাম্পেইন খুলুন।',
'Mkg_Guide_Step_Health_Skipped' => 'গত ৩০ দিনে {n}টি বার্তা বাদ দেওয়া হয়েছে (ইমেইল বা ফোন নেই, চ্যানেল বন্ধ, বা সার্ভার নেই)। কারণ দেখতে একটি ক্যাম্পেইন খুলুন।',
'Mkg_Guide_Step_Health_Ok' => 'গত ৩০ দিনে কোনো ব্যর্থ বা আটকে থাকা বার্তা নেই।',
'Mkg_Guide_Flow' => 'ক্যাম্পেইন পাঠানো',
'Mkg_Guide_Flow_1_T' => 'একটি চ্যানেল সেটআপ করুন',
'Mkg_Guide_Flow_1' => 'মার্কেটিং সেটিংসে ইমেইল, SMS বা WhatsApp চালু করুন এবং এর সার্ভার বা গেটওয়ে সংযুক্ত করুন।',
'Mkg_Guide_Flow_2_T' => 'প্রাপক বেছে নিন',
'Mkg_Guide_Flow_2' => 'সব ক্রেতা, অথবা একটি সংরক্ষিত সেগমেন্ট।',
'Mkg_Guide_Flow_3_T' => 'বার্তা লিখুন',
'Mkg_Guide_Flow_3' => 'টাইপ করুন বা একটি টেমপ্লেট থেকে শুরু করুন, এবং ব্যক্তিগতকরণ ভেরিয়েবল যোগ করুন (নিচে দেখুন)।',
'Mkg_Guide_Flow_4_T' => 'এখনই পাঠান বা সময় নির্ধারণ করুন',
'Mkg_Guide_Flow_4' => 'এখনই পাঠান সঙ্গে সঙ্গে শুরু হয়; সময় নির্ধারণ আপনার বেছে নেওয়া তারিখ ও সময়ে পাঠায়।',
'Mkg_Guide_Flow_5_T' => 'প্রাপকের তালিকা তৈরি হয়',
'Mkg_Guide_Flow_5' => 'পাঠানোর মুহূর্তেই প্রতিটি মিলে যাওয়া ক্রেতাকে অপেক্ষমাণ হিসেবে যোগ করা হয়, ফলে কে পাবে তা আপনি সঙ্গে সঙ্গে দেখতে পারেন।',
'Mkg_Guide_Flow_6_T' => 'ডেলিভারি ব্যাকগ্রাউন্ডে চলে',
'Mkg_Guide_Flow_6' => 'বার্তাগুলো ব্যাচে যায় (মার্কেটিং সেটিংসে ব্যাচ সাইজ) এবং প্রতিটি ব্যাচের পর সংখ্যাগুলো হালনাগাদ হয়।',
'Mkg_Guide_Flow_7_T' => 'ফলাফল যাচাই করুন',
'Mkg_Guide_Flow_7' => 'প্রতিটি প্রাপকের অবস্থা ও ত্রুটি দেখতে ক্যাম্পেইনটি খুলুন; রিপোর্ট সব চ্যানেলের সারসংক্ষেপ দেখায়।',
'Mkg_Guide_Audience' => 'কারা এটি পাবে',
'Mkg_Guide_Audience_1' => 'সব ক্রেতা মুছে ফেলা হয়নি এমন প্রতিটি ক্রেতার কাছে পাঠায়।',
'Mkg_Guide_Audience_2' => 'একটি সেগমেন্ট শহর, শেষ ক্রয়ের তারিখ, ক্রয়ের সংখ্যা ও মোট খরচ অনুযায়ী ক্রেতাদের ফিল্টার করে। সংরক্ষণের আগে প্রিভিউ দেখায় কতজন মিলে যায়।',
'Mkg_Guide_Audience_3' => 'পাঠান-এ ক্লিক করার সময় তালিকাটি নির্দিষ্ট হয়ে যায়। পরে যোগ করা ক্রেতারা অন্তর্ভুক্ত হন না।',
'Mkg_Guide_Audience_4' => 'ইমেইল ঠিকানা (ইমেইল) বা ফোন নম্বর (SMS, WhatsApp) নেই এমন ক্রেতারা তালিকায় বাদ দেওয়া হিসেবে থাকেন।',
'Mkg_Guide_Audience_5' => 'একটি ব্যর্থ ক্যাম্পেইন আবার পাঠালে সেগমেন্ট থেকে তালিকা নতুন করে তৈরি হয় এবং সবার কাছে আবার চেষ্টা করা হয়।',
'Mkg_Guide_Audience_Leads' => 'CRM চালু থাকলে একটি সেগমেন্ট ক্রেতার বদলে CRM লিডকে লক্ষ্য করতে পারে (ট্যাগ, উৎস, অবস্থা, স্কোর ও আরও অনেক কিছু)। যেসব লিড সাবস্ক্রিপশন বাতিল করেছেন তাদের বাদ দেওয়া হয়, এবং লিডদের পাঠানো ইমেইলে সবসময় আনসাবস্ক্রাইব লিংক থাকে।',
'Mkg_Guide_Channels' => 'চ্যানেল',
'Mkg_Guide_Ch_email_1' => 'আপনার নিজস্ব মেইল সার্ভারের মাধ্যমে পাঠানো হয় (সেটিংস > মেইল সেটিংস)। প্ল্যাটফর্মের মেইলার কখনো ব্যবহৃত হয় না।',
'Mkg_Guide_Ch_email_2' => 'প্রেরকের নাম ও ঠিকানা মার্কেটিং সেটিংস থেকে আসে, নইলে মেইল সার্ভার থেকে।',
'Mkg_Guide_Ch_email_3' => 'একটি বিষয় এবং ঐচ্ছিক সংযুক্তি যোগ করুন। বার্তায় HTML থাকতে পারে।',
'Mkg_Guide_Ch_email_4' => 'ইমেইল ঠিকানা নেই এমন ক্রেতাদের বাদ দেওয়া হয়।',
'Mkg_Guide_Ch_sms_1' => 'যেকোনো HTTP SMS গেটওয়ের সাথে কাজ করে: এর API URL, কী, সেন্ডার আইডি, মেথড এবং এটি যে ফিল্ডের নাম আশা করে সেগুলো লিখুন।',
'Mkg_Guide_Ch_sms_2' => 'ফোন নম্বর আছে এমন প্রতিটি ক্রেতার কাছে একটি করে SMS যায়; বাকিদের বাদ দেওয়া হয়।',
'Mkg_Guide_Ch_sms_3' => 'আপনার গেটওয়ে প্রতিটি বার্তার জন্য চার্জ নেয়, তাই আগে একটি ছোট সেগমেন্টে পরীক্ষা করুন।',
'Mkg_Guide_Ch_whatsapp_1' => 'একটি WhatsApp HTTP গেটওয়ে, অথবা Meta WhatsApp Cloud API (graph.facebook.com) সংযুক্ত করুন।',
'Mkg_Guide_Ch_whatsapp_2' => 'কোনো ক্রেতা আপনাকে শেষবার লেখার ২৪ ঘণ্টার বেশি পরে WhatsApp শুধু Meta-অনুমোদিত টেমপ্লেট পৌঁছে দেয়।',
'Mkg_Guide_Ch_whatsapp_3' => 'Cloud API ব্যবহার করলে ক্যাম্পেইনে অনুমোদিত টেমপ্লেটটি বেছে নিন এবং এর প্যারামিটারগুলো পূরণ করুন।',
'Mkg_Guide_Ch_whatsapp_4' => 'ফোন নম্বর নেই এমন ক্রেতাদের বাদ দেওয়া হয়।',
