'Mkg_Guide_Schedule_1' => 'মার্কেটিং সেটিংসে সময়সূচি চালু করুন, তারপর ক্যাম্পেইনে সময় নির্ধারণ এবং একটি তারিখ ও সময় বেছে নিন।',
'Mkg_Guide_Schedule_2' => 'নির্ধারিত সময় হয়ে যাওয়া ক্যাম্পেইনগুলো প্রতি মিনিটে যাচাই করা হয় এবং স্বয়ংক্রিয়ভাবে পাঠানো হয়।',
'Mkg_Guide_Schedule_3' => 'এক দিনের বেশি দেরি হয়ে যাওয়া ক্যাম্পেইন দেরিতে পাঠানোর বদলে বাতিল করা হয়। এটি সম্পাদনা করে নতুন সময় বেছে নিন।',
'Mkg_Guide_Schedule_4' => 'নির্ধারিত ক্যাম্পেইন এখনো সম্পাদনা করা যায়, অথবা এখনই পাঠান দিয়ে সঙ্গে সঙ্গে পাঠানো যায়।',
