'Mkg_Guide_Status_sending' => 'বার্তাগুলো পাঠানো হচ্ছে। ৩০ মিনিট কোনো অগ্রগতি না হলে এখনই পাঠান আবার দেখা যায়, যাতে আপনি আবার শুরু করতে পারেন।',
