'Mkg_Guide_Rstatus_skipped' => 'চেষ্টা করা হয়নি: চ্যানেল বন্ধ, সার্ভার নেই, ইমেইল বা ফোন নেই, অথবা আনসাবস্ক্রাইব করেছেন।',
'Mkg_Guide_Roles' => 'কার কোন অনুমতি দরকার',
'Mkg_Guide_Roles_Help' => 'সেটিংস > অনুমতিতে প্রতিটি ভূমিকাকে শুধু প্রয়োজনীয় অনুমতি দিন। এগুলোর যেকোনো একটি থাকলেই এই গাইড খোলা যায়।',
