'Mkg_Guide_Perm_marketing_templates' => 'SMS, WhatsApp ও ইমেইল টেমপ্লেট পরিচালনা।',
'Mkg_Guide_Perm_marketing_reports' => 'মার্কেটিং রিপোর্ট খোলা।',
'Mkg_Guide_Perm_marketing_settings' => 'চ্যানেল (SMS, WhatsApp, ইমেইল প্রেরক), সময়সূচি ও ব্যাচ সাইজ সেটআপ।',
'Mkg_Guide_Faq' => 'সাধারণ প্রশ্ন',
'Mkg_Guide_Faq_1_Q' => 'আমার ক্যাম্পেইন পাঠানো হচ্ছে অবস্থায় থেকে যায় এবং কিছুই যায় না।',
'Mkg_Guide_Faq_1_A' => 'ব্যাকগ্রাউন্ড প্রেরক এটি এখনো তুলে নেয়নি। ৩০ মিনিট কোনো অগ্রগতি না হলে এখনই পাঠান বাটনটি আবার দেখা যায়: আবার শুরু করতে এতে ক্লিক করুন। বারবার এমন হলে আপনার প্ল্যাটফর্ম অ্যাডমিনিস্ট্রেটরকে ব্যাকগ্রাউন্ড জব (queue worker) চলছে কিনা যাচাই করতে বলুন।',
'Mkg_Guide_Faq_2_Q' => 'প্রাপকদের পাশে "বাদ দেওয়া হয়েছে: ইমেইল চ্যানেল নিষ্ক্রিয়" দেখাচ্ছে।',
'Mkg_Guide_Faq_2_A' => 'মার্কেটিং সেটিংসে ইমেইল চালু করুন, তারপর ক্যাম্পেইনটি আবার পাঠান।',
'Mkg_Guide_Faq_3_Q' => 'প্রাপকদের পাশে "কোনো মেইল সার্ভার কনফিগার করা নেই" দেখাচ্ছে।',
'Mkg_Guide_Faq_3_A' => 'ইমেইল ক্যাম্পেইন শুধু আপনার নিজস্ব মেইল সার্ভারের মাধ্যমে যায়। সেটিংস > মেইল সেটিংসে এটি যোগ করুন।',
'Mkg_Guide_Faq_4_Q' => 'আমার সেগমেন্টে যতজন আছে তার চেয়ে কম মানুষ বার্তাটি পেয়েছে।',
'Mkg_Guide_Faq_4_A' => 'ইমেইল ঠিকানা (ইমেইল) বা ফোন নম্বর (SMS, WhatsApp) নেই এমন ক্রেতাদের বাদ দেওয়া হয়। কাকে এবং কেন বাদ দেওয়া হয়েছে তা দেখতে ক্যাম্পেইনটি খুলুন।',
'Mkg_Guide_Faq_5_Q' => 'পাঠানো হয়েছে মানে কি ক্রেতা এটি পেয়েছেন?',
'Mkg_Guide_Faq_5_A' => 'পাঠানো হয়েছে মানে আপনার মেইল সার্ভার বা গেটওয়ে বার্তাটি গ্রহণ করেছে। ইনবক্সে পৌঁছানো, খোলা ও স্প্যাম ফিল্টারিং ট্র্যাক করা হয় না।',
'Mkg_Guide_Faq_6_Q' => 'পাঠানোর পর কি আমি ক্যাম্পেইন সম্পাদনা করতে পারি?',
'Mkg_Guide_Faq_6_A' => 'না। পাঠানো হচ্ছে ও পাঠানো হয়েছে অবস্থার ক্যাম্পেইন লক থাকে; এর বদলে একটি নতুন ক্যাম্পেইন তৈরি করুন।',
'Mkg_Guide_Faq_7_Q' => 'আমার WhatsApp বার্তাগুলো পৌঁছাচ্ছে না।',
'Mkg_Guide_Faq_7_A' => 'কোনো ক্রেতা আপনাকে শেষবার লেখার ২৪ ঘণ্টার বেশি পরে WhatsApp শুধু Meta-অনুমোদিত টেমপ্লেট পৌঁছে দেয়। WhatsApp Cloud API ব্যবহার করুন এবং ক্যাম্পেইনে একটি অনুমোদিত টেমপ্লেট বেছে নিন।',
'Mkg_Guide_Faq_8_Q' => 'আমি একটি ক্যাম্পেইন আবার পাঠালে কি ক্রেতারা এটি দুবার পাবেন?',
'Mkg_Guide_Faq_8_A' => 'আটকে থাকা ক্যাম্পেইন আবার শুরু করলে শুধু এখনো অপেক্ষমাণ প্রাপকদের কাছে পাঠানো হয়, তাই যার কাছে ইতিমধ্যে পৌঁছানো হয়েছে তাকে আবার বার্তা পাঠানো হয় না। একটি ব্যর্থ ক্যাম্পেইন আবার পাঠালে নতুন তালিকা দিয়ে প্রথম থেকে শুরু হয়।',

