'Pd_Transactions_Help' => 'কোনো ডিভাইসে পাঠানো প্রতিটি পেমেন্ট, অর্থ ফেরত ও ভয়েড। "বিক্রয় ছাড়াই অর্থ নেওয়া হয়েছে" মানে কার্ড থেকে অর্থ নেওয়া হয়েছে কিন্তু কোনো বিক্রয় সংরক্ষিত হয়নি — এটি ভয়েড করুন বা অর্থ ফেরত দিন।',
