'Pd_Refund' => 'অর্থ ফেরত দিন',
'Pd_Refund_Help' => 'পরিমাণটি ডিভাইসের মাধ্যমে ক্রেতার কার্ডে ফেরত যায়। এটি কোনো বিক্রয় ফেরত তৈরি করে না — পণ্য ফেরত এলে বিক্রয় ফেরত অংশে ফেরতটি রেকর্ড করুন।',
