'Pd_Void_Confirm_Help' => 'সম্পূর্ণ {amount} ডিভাইসে বাতিল করা হবে। সাধারণত শুধু একই দিনে, ডিভাইস তার ব্যাচ বন্ধ করার আগে সম্ভব।',
