'Pd_Wait_For_Device' => 'ডিভাইসের কাজ শেষ হওয়া পর্যন্ত অপেক্ষা করুন।',
'Pd_Line_Locked' => 'এই লাইনটি ডিভাইসে চার্জ করা হয়েছে। পরিবর্তন করতে আগে চার্জটি ভয়েড করুন।',
'Pd_Needs_Online' => 'কার্ড টার্মিনালে পেমেন্টের জন্য ইন্টারনেট সংযোগ প্রয়োজন।',
'Pd_Device_Error' => 'ডিভাইসে পৌঁছানো যায়নি।',
