'Pd_Void_Charge_Confirm' => 'ডিভাইসে {amount}-এর কার্ড পেমেন্টটি ভয়েড করবেন?',
'Pd_Void_Before_Close' => 'ডিভাইসে ইতিমধ্যে একটি কার্ড পেমেন্ট নেওয়া হয়েছে। এটি ভয়েড করে বন্ধ করবেন?',
'Pd_Installments' => 'কিস্তি',
'Pd_Single_Payment' => 'একক পেমেন্ট',
'Pd_Guide_How_Title' => 'এটি কীভাবে কাজ করে',
'Pd_Guide_How_Intro' => 'POS ডিভাইস হলো ক্যাশ কাউন্টারের পাশে থাকা একটি কার্ড টার্মিনাল বা ফিসক্যাল ক্যাশ রেজিস্টার। Stocky এতে পরিমাণ পাঠায়, ক্রেতার পেমেন্টের অপেক্ষা করে, এবং ডিভাইস অনুমোদন করার পরেই পেমেন্ট রেকর্ড করে।',
'Pd_Guide_Step_1' => 'এখানে ডিভাইসটি যোগ করুন: মডেল, গুদাম, এবং যে পেমেন্ট পদ্ধতি হিসেবে এর কার্ড পেমেন্ট রেকর্ড হবে (যেমন "ক্রেডিট কার্ড")।',
'Pd_Guide_Step_2' => 'Stocky কীভাবে এতে পৌঁছাবে তা বেছে নিন: ক্যাশিয়ারের কম্পিউটারে একটি লোকাল ব্রিজ, অথবা আপনার প্রোভাইডারের ক্লাউড API। আপনার ব্যাংক বা প্রোভাইডারের দেওয়া আইডি ও কী লিখুন।',
'Pd_Guide_Step_3' => 'সংযোগ পরীক্ষা করুন চাপুন। ব্রিজ ডিভাইস অবশ্যই সেই ক্যাশিয়ার কম্পিউটার থেকে পরীক্ষা করতে হবে যেখানে ব্রিজ চলে।',
'Pd_Guide_Step_4' => 'POS-এ সেই পেমেন্ট পদ্ধতি বেছে নিন, "ডিভাইসে চার্জ করুন" চাপুন এবং ক্রেতাকে পেমেন্ট করতে দিন। ডিভাইস অনুমোদন করলে বিক্রয় সম্পন্ন করা যায়।',
'Pd_Guide_Step_5' => 'বিক্রয় ছাড়াই নেওয়া কার্ড পেমেন্টের (যেমন, মাঝপথে ছেড়ে দেওয়া চেকআউট) জন্য লেনদেন যাচাই করুন এবং সেগুলো ভয়েড করুন বা অর্থ ফেরত দিন।',
'Pd_Guide_Bridge_Text' => 'যেসব ডিভাইস ক্যাশিয়ার PC-তে ভেন্ডরের SDK দিয়ে চলে (USB, সিরিয়াল বা LAN পেয়ারিং)। ব্রাউজার সরাসরি SDK ব্যবহার করতে পারে না, তাই একটি ছোট ব্রিজ প্রোগ্রাম এটিকে মুড়ে রাখে এবং এই কম্পিউটারে শোনে।',
'Pd_Guide_Bridge_Point_1' => 'POS ক্যাশিয়ারের ব্রাউজার থেকে প্রতিটি অনুরোধ ব্রিজ URL-এ পাঠায়; Stocky-র সার্ভারকে কখনো আপনার শপের নেটওয়ার্কে পৌঁছাতে হয় না।',
'Pd_Guide_Bridge_Point_2' => 'অনুরোধ ও উত্তরগুলো শেয়ার্ড সিক্রেট দিয়ে স্বাক্ষরিত হয়, তাই ব্রাউজার থেকে কোনো অনুমোদন জাল করা যায় না।',
'Pd_Guide_Bridge_Point_3' => 'যেসব কম্পিউটারে এই ডিভাইস দিয়ে কার্ড পেমেন্ট নেওয়া হয় তার প্রতিটিতে ব্রিজটি ইনস্টল করে চালু করুন।',
'Pd_Guide_Cloud_Text' => 'যেসব প্রোভাইডার ইন্টারনেটের মাধ্যমে ডিভাইসে পৌঁছায়। Stocky-র সার্ভার API কল করে, তাই ক্যাশিয়ারের কম্পিউটারে কিছুই ইনস্টল করতে হয় না।',
'Pd_Guide_Cloud_Point_1' => 'API URL অবশ্যই একটি পাবলিক ঠিকানায় https:// হতে হবে।',
'Pd_Guide_Cloud_Point_2' => 'ক্রেতা পেমেন্ট করার সময় Stocky প্রতি ২ সেকেন্ডে অবস্থা জানতে চায়, তাই status এন্ডপয়েন্টকে রেফারেন্স দিয়ে পেমেন্টটি চিনতে হবে; কার্ডের কাজ শেষ হওয়ার আগেই API উত্তর দিলে ("pending"), পোলিং ফলাফল নির্ধারণ করে।',
'Pd_Guide_Ide280_Title' => 'Ingenico IDE280',
'Pd_Guide_Ide280_Text' => 'IDE280 হলো কার্ড রিডারসহ একটি নতুন প্রজন্মের ফিসক্যাল ক্যাশ রেজিস্টার (YN ÖKC)। এটি সাধারণত Ingenico-র ECR / GMP3 SDK, অথবা আপনার ব্যাংকের ইন্টিগ্রেশন সার্ভিসের মাধ্যমে যুক্ত করা হয়।',
'Pd_Guide_Ide280_Point_1' => 'Ingenico / ব্যাংকের ডকুমেন্টেশন অনুযায়ী ডিভাইসটিকে ক্যাশিয়ারের কম্পিউটারের সাথে পেয়ার করুন, তারপর ব্রিজ (বা API সেটিংস) সেদিকে নির্দেশ করুন।',
'Pd_Guide_Ide280_Point_2' => 'পরিমাণ দশমিক এবং kuruş (amount_minor) উভয় রূপে পাঠানো হয়, মুদ্রা TRY / 949।',
'Pd_Guide_Ide280_Point_3' => '"পূর্ণ ফিসক্যাল রসিদ" চালু থাকলে প্রতিটি আইটেমে তার ভ্যাট হারের ডিভাইস বিভাগ থাকে — ডিভাইস যেভাবে প্রোগ্রাম করা আছে সেভাবে ভ্যাট বিভাগগুলো মিলিয়ে নিন।',
'Pd_Guide_Protocol_Title' => 'ব্রিজ / API চুক্তি',
'Pd_Guide_Protocol_Intro' => 'Stocky ব্রিজ বা API-র সাথে JSON-এ কথা বলে। নিচের পাথগুলো ডিফল্ট এবং উন্নত অংশে প্রতিটি ডিভাইসের জন্য পরিবর্তন করা যায়।',
