'Pd_Guide_When_Refund' => 'পেমেন্টের আংশিক বা সম্পূর্ণ অর্থ ফেরত।',
'Pd_Guide_Request_Title' => 'অনুরোধ',
'Pd_Guide_Request_Text' => 'বিক্রয়ের জন্য Stocky যে বডি পাঠায়। অর্থ ফেরত ও ভয়েডে মূল পেমেন্টটি "original" হিসেবে থাকে।',
'Pd_Guide_Response_Title' => 'উত্তর',
'Pd_Guide_Response_Text' => 'ফিল্ডের নামগুলো নমনীয়ভাবে পড়া হয় ("data"-র ভেতরেও); "status" বা response_code "00" ফলাফল নির্ধারণ করে। কার্ড নম্বর মাস্ক করে সংরক্ষণ করা হয়।',
'Pd_Guide_Signing_Title' => 'স্বাক্ষর (ব্রিজ)',
