'Pd_Guide_Safety_Title' => 'জেনে রাখা ভালো',
'Pd_Guide_Safety_1' => 'একই পরিমাণের অনুমোদিত ডিভাইস পেমেন্ট থাকলেই শুধু বিক্রয় সংরক্ষিত হয়; একটি ডিভাইস পেমেন্ট কখনো দুটি বিক্রয় পরিশোধ করতে পারে না।',
'Pd_Guide_Safety_2' => 'কার্ড চার্জ হওয়ার পর পেমেন্ট উইন্ডো বন্ধ করলে আগে সেই চার্জটি ভয়েড হয়।',
'Pd_Guide_Safety_3' => 'ডিভাইস সময়মতো উত্তর না দিলে পেমেন্টটি "সাড়া নেই" হিসেবে দেখায়: ডিভাইসটি যাচাই করুন, এবং কার্ড চার্জ হয়ে থাকলে লেনদেন থেকে চার্জটি ভয়েড করুন।',
'Pd_Guide_Safety_4' => 'এখানকার অর্থ ফেরত ও ভয়েড শুধু কার্ডের অর্থ সরায়; এগুলো বিক্রয় পরিবর্তন করে না। ফেরত আসা পণ্য বিক্রয় ফেরত অংশে রেকর্ড করুন।',
