'Cd_Ssl_Hint' => 'যাচাইয়ের পরে প্ল্যাটফর্ম টিম আপনার ডোমেইনের জন্য HTTPS সার্টিফিকেট ইনস্টল করে। প্যাডলক কাজ করা শুরু করলে SSL ব্যাজ নিজে থেকেই সক্রিয় হয়ে যায় (প্রতি ঘণ্টায় এবং প্রতিবার যাচাই-এ ক্লিক করলে পরীক্ষা করা হয়)। এক দিন পরেও ব্যর্থ দেখালে সাপোর্টে যোগাযোগ করুন।',
