'Cd_Err_not_verified' => 'প্রধান হিসেবে সেট করার আগে ডোমেইনটি যাচাই করুন।',
'Cd_Err_no_records' => 'এখনো কোনো DNS রেকর্ড পাওয়া যায়নি। ছড়িয়ে পড়তে কয়েক মিনিট লাগতে পারে।',
