'Cd_Guide_1' => 'আপনার মালিকানাধীন ডোমেইন যোগ করুন, যেমন shop.example.com।',
'Cd_Guide_2' => 'আপনার ডোমেইন প্রদানকারীতে (GoDaddy, Namecheap, Cloudflare...) সাইন ইন করে দেখানো DNS রেকর্ডটি তৈরি করুন।',
'Cd_Guide_3' => 'ফিরে এসে DNS যাচাই করুন-এ ক্লিক করুন। যাচাই হলে আপনার ওয়ার্কস্পেস, অনলাইন স্টোর ও ক্রেতা পোর্টাল সেই ডোমেইনে সাড়া দেবে।',
'Cd_Guide_4' => 'কাস্টম ডোমেইনের পাশাপাশি আপনার প্ল্যাটফর্ম সাবডোমেইনও কাজ করতে থাকে।',
'Cd_Cloudflare_Note' => 'Cloudflare ব্যবহারকারীরা: যাচাই সম্পন্ন না হওয়া পর্যন্ত রেকর্ডটি DNS only (ধূসর ক্লাউড) রাখুন।',
'Perm_custom_domains' => 'কাস্টম ডোমেইন (সেটিংস > কাস্টম ডোমেইন)',
'List_Too_Big_All' => 'এই তালিকায় {count}টির বেশি সারি আছে, তাই সব দেখানোর বিকল্পটি বন্ধ। প্রতি পৃষ্ঠায় ১০০টি সারি দেখানো হচ্ছে। সীমিত করতে অনুসন্ধান বা ফিল্টার ব্যবহার করুন।',
'List_Too_Big_Export' => 'এই তালিকায় {count}টির বেশি সারি আছে, যা একবারে রপ্তানির জন্য অনেক বেশি। সীমিত করতে অনুসন্ধান বা ফিল্টার ব্যবহার করুন।',
'PartiallyPaid' => 'আংশিক পরিশোধিত',
'Ord_Guide_PayAuto_Tip' => 'বিক্রয়ে পেমেন্ট রেকর্ড করা হলে নিজে থেকেই হালনাগাদ হয়। পেমেন্ট কীভাবে রেকর্ড করতে হয় দেখতে ক্লিক করুন।',
'Ord_Guide_PayAuto_Intro' => 'এই কলামে দেখায় অর্ডারের কতটা পরিশোধ হয়েছে। এটি ক্রেতার চেকআউটের পছন্দ থেকে শুরু হয়, তারপর অর্ডার নিশ্চিত করলে যে বিক্রয় তৈরি হয় তাতে পেমেন্ট রেকর্ড হওয়ার সাথে সাথে নিজে থেকেই হালনাগাদ হয়। এই পৃষ্ঠা থেকে এটি সম্পাদনা করা যায় না।',
'Ord_Guide_PayAuto_Paid' => 'সম্পূর্ণ অর্থ পাওয়া গেছে। ক্রেতা কোনো পেমেন্ট গেটওয়ের মাধ্যমে অনলাইনে পরিশোধ করলে, অর্ডার নিশ্চিত করলে বিক্রয়টি পরিশোধিত হিসেবে তৈরি হয় এবং পেমেন্ট আপনার হয়ে রেকর্ড হয়। অন্যথায় বিক্রয়ের পেমেন্টগুলো মোট অঙ্ক পূরণ করলে অবস্থা পরিশোধিত-এ বদলে যায়।',
'Ord_Guide_PayAuto_Partial' => 'বিক্রয়ে একটি পেমেন্ট রেকর্ড হয়েছে, তবে মোট অঙ্কের একটি অংশ এখনো বকেয়া।',
'Ord_Guide_PayAuto_Pending' => 'এখনো কোনো পেমেন্ট পাওয়া যায়নি: ক্যাশ অন ডেলিভারি, ব্যাংক ট্রান্সফার বা পরে-পরিশোধের অন্য কোনো পদ্ধতি। অর্ডার নিশ্চিত করলে বিক্রয়টি অপরিশোধিত হিসেবে তৈরি হয়, তাই অর্থ সংগ্রহ করার পর আপনি নিজেই তা রেকর্ড করবেন। নিচের ধাপগুলো দেখুন।',
'Ord_Guide_PayAuto_Note' => 'এখানে দেখানো পেমেন্টের অবস্থা বিক্রয়কে অনুসরণ করে: আপনি পেমেন্ট সংরক্ষণ করলে এটি নিজে থেকেই আংশিক পরিশোধিত বা পরিশোধিত হয়, আর কোনো পেমেন্ট মুছলে আগের অবস্থায় ফিরে যায়। বিক্রয়টিই হিসাবের রেকর্ড, এবং এটিই আপনার পেমেন্ট ও মুনাফা রিপোর্টে তথ্য দেয়। যা লিখেছেন তা দেখতে বা সম্পাদনা করতে বিক্রয়ে পেমেন্ট দেখুন ব্যবহার করুন।',
'Ord_LinkedSale' => 'সংযুক্ত বিক্রয়',
'Ord_LinkedSale_Missing' => 'এই অর্ডারের সাথে কোনো বিক্রয় সংযুক্ত নেই। বিক্রয়টি মুছে ফেলা হয়ে থাকতে পারে, অথবা অর্ডারকে বিক্রয়ের সাথে সংযুক্ত করার ব্যবস্থা চালুর আগেই অর্ডারটি নিশ্চিত করা হয়েছিল।',
