'Oc_Order_Statuses' => 'অর্ডারের অবস্থা',
'Oc_Order_Statuses_Help' => 'প্রতিটি OpenCart অবস্থা এখানে কী বোঝায়। এগুলো আপনার স্টোর থেকে সেট করা হয়েছে এবং কাস্টম অবস্থা ব্যবহার করলেই কেবল বদলাতে হবে।',
'Oc_Commit_Statuses' => 'সম্পন্ন বিক্রয়',
