'Oc_Paid_Statuses' => 'পরিশোধিত',
'Oc_Paid_Statuses_Help' => 'যা এখনো বকেয়া তার জন্য একটি পেমেন্ট রেকর্ড করা হয়।',
'Oc_Cancel_Statuses' => 'বাতিলকৃত',
'Oc_Cancel_Statuses_Help' => 'বিক্রয়টি উল্টে দেওয়া হয়: স্টক ফিরে আসে এবং এর পেমেন্টগুলো সরিয়ে দেওয়া হয়।',
'Oc_Variants_Linked' => 'সংযুক্ত ভ্যারিয়েন্ট',
'Oc_Push_Desc' => 'OpenCart-এ অনুপস্থিত পণ্য ও ভ্যারিয়েন্ট তৈরি করে, এবং সংযুক্তগুলোর নাম, দাম, অবস্থা ও স্টক হালনাগাদ করে। বিবরণ, ছবি ও ক্যাটাগরি শুধু তখনই সেট হয় যখন পণ্যটি নতুন বা সেগুলো নেই, তাই OpenCart-এ লেখা কনটেন্ট অপরিবর্তিত থাকে।',
'Oc_Pull_Desc' => 'OpenCart-এর পণ্য আমদানি করে, বিদ্যমান পণ্যগুলোকে model বা SKU দিয়ে মিলিয়ে এবং বাকিগুলো তৈরি করে। সংযুক্ত পণ্যগুলো OpenCart থেকে নাম ও দাম নেয়।',
'Oc_Pull_Stock' => 'নতুন পণ্যের প্রারম্ভিক স্টক হিসেবে OpenCart-এর পরিমাণ ব্যবহার করুন',
'Oc_Reset_Confirm' => 'পণ্যের সংযোগ রিসেট করবেন? অর্ডারের ইতিহাসের সংযোগ থেকে যাবে।',
'Oc_Stock_Desc' => 'প্রতিটি সংযুক্ত পণ্য ও ভ্যারিয়েন্টের স্টোর পরিমাণ এখানে থাকা স্টকের সমান করে দেয়।',
'Oc_Orders_Desc' => 'স্টোরের অর্ডারগুলো বিক্রয় হিসেবে আমদানি করে ({ref}-এর মতো রেফারেন্স)। আগে আমদানি হওয়া অর্ডারের শুধু অবস্থা ও পেমেন্ট হালনাগাদ হয়, তাই আবার আনা নিরাপদ।',
'Oc_Orders_Since' => 'যে তারিখ থেকে অর্ডার',
'Oc_Guide_1' => 'সংযোগ ট্যাবে {company} Connector ডাউনলোড করুন।',
'Oc_Guide_2' => 'আপনার OpenCart অ্যাডমিনে {installer}-এর অধীনে ফাইলটি আপলোড করে Install-এ ক্লিক করুন, তারপর {modules}-এর অধীনে মডিউলটি ইনস্টল করুন।',
'Oc_Guide_3' => '{name} মডিউলটি খুলুন, তারপর স্টোর URL ও সিক্রেট কপি করুন।',
'Oc_Guide_4' => 'এগুলো সংযোগ ট্যাবে পেস্ট করুন, সংরক্ষণ করুন এবং {test} চালান। এটি স্টোরকে জানিয়েও দেয় নতুন অর্ডার কোথায় পাঠাতে হবে।',
'Oc_Guide_5' => 'পণ্য সেট আপ করুন: স্টোরে আগে থেকে ক্যাটালগ থাকলে আনুন, {company}-তে থাকলে পাঠান। স্বয়ংক্রিয় স্টকের ওপর নির্ভর করার আগে এটি করুন, কারণ {company} স্টকের হিসাবের উৎস হয়ে যায়।',
'Oc_Guide_6' => 'ইতিহাস চাইলে সাম্প্রতিক অর্ডারগুলো একবার আনুন। এরপর থেকে অর্ডার নিজে থেকেই আসবে।',
'Oc_Identity_Title' => 'পণ্য model ও SKU দিয়ে মেলানো হয়',
'Oc_Identity_Desc' => 'এখানকার পণ্য কোড OpenCart-এর model ও SKU-এর সাথে মেলানো হয়। উভয় দিকে এগুলো একই রাখুন। এখানকার স্টকই মূল হিসাব: প্রতিটি অর্ডারের পরে এটি থেকে স্টোর হালনাগাদ হয়।',
'Oc_Options_Title' => 'ভ্যারিয়েন্ট ছাড়া অপশন',
'Oc_Options_Desc' => 'OpenCart ভ্যারিয়েন্টের নিজস্ব স্টক থাকে এবং এগুলো এখানকার ভ্যারিয়েন্টের সাথে ম্যাপ হয়। যে পণ্যে শুধু অপশন আছে, কোনো ভ্যারিয়েন্ট তৈরি করা হয়নি, সেটি একটি পণ্য হিসেবে আমদানি হয় এবং এর স্টক অপশন অনুযায়ী ভাগ হয় না।',
'Oc_Cancel_Title' => 'বাতিলকৃত অর্ডার',
'Oc_Cancel_Desc' => 'OpenCart-এ একটি অর্ডার বাতিল করলে এখানে এর বিক্রয় উল্টে যায়। বিক্রয়টি ইতিমধ্যে পৌঁছে দেওয়া হলে বা এতে ফেরত থাকলে কিছুই উল্টানো হয় না: আপনার পর্যালোচনার জন্য বিক্রয়টি এর নোটে ও লগে চিহ্নিত করা হয়।',
'Oc_Download_Connector_3' => 'OpenCart 3-এর জন্য ডাউনলোড করুন',
'Oc_Opencart3_Title' => 'OpenCart 3 স্টোর',
'Oc_Opencart3_Desc' => 'OpenCart 3-এর নিজস্ব কোনো ভ্যারিয়েন্ট নেই, শুধু অপশন আছে। একটি অপশনযুক্ত পণ্য (যেমন সাইজ) প্রতিটি অপশন মান অনুযায়ী স্টকসহ সিঙ্ক হয়, যা এখানকার ভ্যারিয়েন্টের সাথে ম্যাপ হয়। একাধিক অপশনযুক্ত পণ্যের অপশনগুলো প্রতি সমন্বয়ে স্টক ছাড়াই তৈরি হয়: এর স্টক পুরো পণ্যের ওপর রাখা হয়, এবং এর বিক্রয়ের লাইনগুলো পণ্যের বিপরীতে আসে।',
'Oc_G_Title' => 'OpenCart নির্দেশিকা',
'Oc_G_Open_Settings' => 'OpenCart সেটিংস খুলুন',
'Oc_G_Your_Setup' => 'আপনার সেটআপ',
'Oc_G_Your_Setup_Help' => 'এই ওয়ার্কস্পেস কোন পর্যায়ে আছে। আপনি এগোনোর সাথে সাথে ধাপগুলো হালনাগাদ হয়।',
'Oc_G_Step_Install' => 'আপনার স্টোরে {company} Connector ইনস্টল করুন',
'Oc_G_Step_Install_Help' => 'একটি ছোট এক্সটেনশন যা {company}-কে পণ্য, স্টক ও অর্ডারে অ্যাক্সেস দেয়। OpenCart-এর নিজের এগুলোর জন্য কোনো API নেই।',
'Oc_G_Step_Connect' => 'স্টোর সংযুক্ত করুন',
'Oc_G_Step_Connect_Help' => 'মডিউল পৃষ্ঠা থেকে স্টোর URL ও সিক্রেট সংযোগ ট্যাবে পেস্ট করুন, সংরক্ষণ করুন, তারপর সংযোগ পরীক্ষা চালান।',
'Oc_G_Step_Connect_Done' => 'সংযুক্ত: OpenCart {opencart}-এ কানেক্টর {connector}।',
'Oc_G_Step_Enable' => 'সিঙ্ক চালু করুন',
'Oc_G_Step_Enable_Help' => 'ইন্টিগ্রেশন বন্ধ থাকলে কিছুই আদানপ্রদান হয় না; স্টোর থেকে আসা ওয়েবহুক গ্রহণ স্বীকার করা হয় কিন্তু উপেক্ষা করা হয়।',
'Oc_G_Step_Products' => 'পণ্যগুলো সংযুক্ত করুন',
'Oc_G_Step_Products_Help' => 'স্টোরের ক্যাটালগ আনুন বা আপনারটি পাঠান, যাতে স্টক আদানপ্রদান শুরুর আগে উভয় দিকের প্রতিটি পণ্য সংযুক্ত থাকে।',
'Oc_G_Step_Products_Done' => '{n}টি পণ্য ও {v}টি ভ্যারিয়েন্ট সংযুক্ত।',
'Oc_G_Step_Orders' => 'অর্ডার গ্রহণ করুন',
'Oc_G_Step_Orders_Help' => 'সংযুক্ত হওয়ার পর নতুন অর্ডার নিজে থেকেই আসে। বিক্রয়-এর অধীনে এটি দেখা যায় কিনা দেখতে স্টোরে একটি পরীক্ষামূলক অর্ডার দিন।',
'Oc_G_Step_Orders_No_Webhook' => 'অর্ডার আমদানি হয়েছে, কিন্তু স্টোরের নোটিশের মাধ্যমে এখনো কোনোটি আসেনি। স্টোর এই ঠিকানায় পৌঁছাতে না পারলেও প্রতি কয়েক মিনিটের যাচাইয়ের মাধ্যমে অর্ডার আসতে থাকবে।',
'Oc_G_Step_Orders_Done' => 'স্টোর অর্ডারের নোটিশ পাঠাচ্ছে।',
'Oc_G_Install_Title' => 'কানেক্টর ইনস্টল করুন',
'Oc_G_Install_Intro' => 'আপনার OpenCart সংস্করণ বেছে নিন। কানেক্টরটি OpenCart-এর নিজস্ব এক্সটেনশন ইনস্টলারের মাধ্যমে ইনস্টল হয়; হাতে কোনো ফাইল সম্পাদনা করতে হয় না।',
'Oc_G_Opencart_4' => 'OpenCart 4.x',
'Oc_G_Opencart_3' => 'OpenCart 3.x',
'Oc_G_I4_1' => 'OpenCart 4-এর জন্য কানেক্টর ডাউনলোড করুন।',
'Oc_G_I4_2' => 'আপনার OpenCart অ্যাডমিনে {path} খুলুন, ফাইলটি আপলোড করুন এবং এর পাশে Install-এ ক্লিক করুন।',
'Oc_G_I4_3' => '{path} খুলুন, {name} খুঁজে Install-এ ক্লিক করুন, তারপর Edit-এ।',
'Oc_G_I3_1' => 'OpenCart 3-এর জন্য কানেক্টর ডাউনলোড করুন।',
'Oc_G_I3_2' => 'আপনার OpenCart অ্যাডমিনে {path} খুলুন, ফাইলটি আপলোড করুন এবং ধাপগুলো শেষ হওয়া পর্যন্ত অপেক্ষা করুন।',
'Oc_G_I3_3' => '{path} খুলুন, {name} খুঁজে Install-এ ক্লিক করুন, তারপর Edit-এ।',
'Oc_G_I_4' => 'মডিউল পৃষ্ঠায় স্টোর URL ও একটি সিক্রেট দেখায়। দুটোই কপি করুন।',
'Oc_G_I_5' => 'এখানে ফিরে এসে এগুলো সংযোগ ট্যাবে পেস্ট করুন, সংরক্ষণ করুন এবং {test} চালান। এটি স্টোরকে জানিয়েও দেয় অর্ডারের নোটিশ কোথায় পাঠাতে হবে।',
'Oc_G_Requirements' => 'স্টোরের যা প্রয়োজন',
'Oc_G_Requirements_Desc' => 'OpenCart 3.0 বা 4.0 ও তার পরের সংস্করণ, cURL-সহ PHP (যেকোনো হোস্টে সাধারণত থাকে), এবং ইন্টারনেট থেকে পৌঁছানো যায় এমন একটি স্টোর ঠিকানা। স্টোর প্রাইভেট নেটওয়ার্কে থাকলেও, এই ওয়ার্কস্পেস স্টোরে পৌঁছাতে পারলে প্রতি কয়েক মিনিটে চলা যাচাইয়ের মাধ্যমে অর্ডার আসতে থাকবে।',
'Oc_G_First_Title' => 'প্রথম সিঙ্ক',
'Oc_G_First_Shop_Has' => 'স্টোরে আগে থেকেই ক্যাটালগ আছে',
'Oc_G_First_Shop_Has_Text' => 'পণ্য ট্যাবে পণ্য আনুন। পণ্যগুলো model বা SKU দিয়ে আপনার পণ্য কোডের সাথে মেলানো হয় এবং না থাকলে তৈরি হয়; স্টোরের পরিমাণকে প্রারম্ভিক স্টক হিসেবে নিতে স্টক অপশনে টিক দিন।',
'Oc_G_First_Company_Has' => '{company}-তে ক্যাটালগ আছে',
'Oc_G_First_Company_Has_Text' => 'পণ্য পাঠান। অনুপস্থিত পণ্যগুলো স্টকসহ স্টোরে তৈরি হয়; বিদ্যমানগুলো model বা SKU দিয়ে সংযুক্ত ও হালনাগাদ হয়।',
'Oc_G_First_Both' => 'উভয় দিকেই পণ্য আছে',
'Oc_G_First_Both_Text' => 'প্রথমে আনুন, যাতে স্টোরের বিদ্যমান পণ্যগুলো ডুপ্লিকেট না হয়ে সংযুক্ত হয়, তারপর স্টোরে যা নেই তা তৈরি করতে পাঠান। উভয় দিকে পণ্য কোড ও model একই রাখুন।',
'Oc_G_Stock_Master' => 'স্টকের হিসাব {company}-এর কাছে থাকে',
'Oc_G_Stock_Master_Desc' => 'প্রথম সিঙ্কের পর স্টোরের পরিমাণ সবসময় {company} থেকে লেখা হয়। OpenCart-এ পরিমাণ সম্পাদনা করলে তার স্থায়ী কোনো প্রভাব নেই: পরবর্তী চলাচল বা ঘণ্টাভিত্তিক যাচাই তা মুছে নতুন করে লিখে দেয়।',
'Oc_G_How_Title' => 'যেভাবে কাজ করে',
'Oc_G_T_Products' => 'পণ্য',
'Oc_G_Products_1' => 'এখানকার কোড দিয়ে একটি পণ্যকে স্টোরের model ও SKU-এর সাথে মেলানো হয়। সংযোগটি মনে রাখা হয়, তাই পরে পণ্যের নাম বদলালেও তা ভাঙে না।',
'Oc_G_Products_2' => '{company} যখন একটি পণ্য পাঠায় তখন এটি model, SKU, নাম, দাম, অবস্থা ও স্টক সেট করে। বিবরণ, ছবি ও ক্যাটাগরি শুধু তখনই লেখা হয় যখন পণ্যটি স্টোরে নতুন বা সেগুলো নেই, তাই OpenCart-এ লেখা কনটেন্ট অপরিবর্তিত থাকে।',
'Oc_G_Products_3' => 'অনলাইন স্টোর থেকে লুকানো বা এখানে বিক্রয়ের জন্য নয় এমন পণ্য স্টোরে তৈরি হয় না; আগে থেকে সংযুক্ত থাকলে সেখানে সেটিকে নিষ্ক্রিয় করা হয়।',
'Oc_G_T_Variants' => 'ভ্যারিয়েন্ট ও অপশন',
'Oc_G_Variants_4' => 'OpenCart 4-এ প্রকৃত ভ্যারিয়েন্ট আছে (রং ও সাইজের পছন্দসহ একটি পণ্য), প্রতিটির নিজস্ব স্টকসহ। এগুলো উভয় দিকে আপনার ভ্যারিয়েন্টের সাথে ম্যাপ হয়, এবং প্রতিটি তার নিজস্ব model দিয়ে মেলানো হয়।',
'Oc_G_Variants_3' => 'OpenCart 3-এ কোনো ভ্যারিয়েন্ট নেই, শুধু অপশন এবং প্রতিটি অপশন মান অনুযায়ী স্টক আছে। একটি অপশনযুক্ত পণ্য (যেমন সাইজ) প্রতিটি মান অনুযায়ী স্টকসহ সিঙ্ক হয়, যা আপনার ভ্যারিয়েন্টের সাথে ম্যাপ হয়। একাধিক অপশনযুক্ত পণ্যের অপশনগুলো প্রতি সমন্বয়ে স্টক ছাড়াই তৈরি হয়: এর স্টক পুরো পণ্যের ওপর থাকে, এবং এর বিক্রয়ের লাইনগুলো পণ্যের বিপরীতে আসে।',
'Oc_G_Variants_Multi' => 'যে স্টোর পণ্যে শুধু অপশন আছে, কোনো ভ্যারিয়েন্ট তৈরি করা হয়নি, সেটি একটি পণ্য হিসেবে আমদানি হয়; বিষয়টি লগে উল্লেখ করা হয়।',
'Oc_G_T_Stock' => 'স্টক',
'Oc_G_Stock_1' => 'স্টক সুইচ চালু থাকলে এখানকার প্রতিটি চলাচল (বিক্রয়, ফেরত, ক্রয়, সমন্বয়, স্থানান্তর) পৃষ্ঠা উত্তর দেওয়ার পরে কয়েক সেকেন্ডের মধ্যে স্টোর হালনাগাদ করে, তাই ক্যাশিয়ারকে কখনো স্টোরের জন্য অপেক্ষা করতে হয় না।',
'Oc_G_Stock_2' => 'ঘণ্টায় একবার প্রতিটি সংযুক্ত পণ্য যাচাই ও সংশোধন করা হয়, যা লাইভ পাঠানোয় ধরা পড়ে না এমন বাল্ক পরিবর্তনগুলোও কভার করে। স্টক ট্যাব চাহিদামতো সবকিছু পাঠায়।',
'Oc_G_Stock_3' => 'সেবা, সবসময় স্টকে আছে চিহ্নিত পণ্য, এবং যেসব কম্বোর উপাদান সীমাহীন সেগুলো স্টোরে সবসময় পাওয়া যায় হিসেবে দেখানো হয়। শুধু একটি গুদামের হিসাব নিতে সংযোগ ট্যাবে সেই গুদাম বেছে নিন; অন্যথায় সব গুদামের যোগফল নেওয়া হয়।',
'Oc_G_T_Orders' => 'অর্ডার ও অবস্থা',
'Oc_G_Orders_1' => 'নতুন বা পরিবর্তিত অর্ডার স্টোর সঙ্গে সঙ্গে জানায় এবং স্বাক্ষরিত সংযোগের মাধ্যমে তা আবার পড়ে নেওয়া হয়, তাই নোটিশের ভেতরের কোনো তথ্যকেই বিশ্বাস করা হয় না। প্রতি কয়েক মিনিটে একটি যাচাই নোটিশে বাদ পড়া সবকিছু টেনে আনে। প্রতিটি অর্ডার OC-<order number> রেফারেন্সসহ একটি বিক্রয় হয়; ক্রেতাকে ইমেইল দিয়ে মেলানো হয় বা তৈরি করা হয়।',
'Oc_G_Col_List' => 'অবস্থার তালিকা',
'Oc_G_Col_Meaning' => 'এখানে এটি যা করে',
'Oc_G_Col_Default' => 'আপনার স্টোর থেকে সেট করা',
'Oc_G_Default_Commit' => 'OpenCart-এ যেসব অবস্থা স্টক কমায় (ডিফল্টভাবে Pending, Processing, Shipped, Complete)',
'Oc_G_Default_Paid' => 'Processing, Processed, Shipped, Complete',
'Oc_G_Default_Cancel' => 'Canceled, Denied, Failed, Refunded, Reversed, Chargeback, Expired, Voided',
'Oc_G_Orders_2' => 'প্রথম সংযোগের সময় তালিকাগুলো আপনার স্টোর থেকে পূরণ হয় এবং সংযোগ ট্যাবে পরিবর্তন করা যায়। প্রথম তালিকাটি OpenCart-এ স্টক কমানো অবস্থাগুলোর সাথে একই রাখুন, যাতে উভয় দিক একই ধাপে স্টক চলাচল করে।',
'Oc_G_Orders_3' => 'যে অর্ডারের কোনো আইটেম কোনো পণ্যের সাথে মেলে না সেটি আটকে রাখা হয়, এবং পণ্যটি স্টোরে থাকলে সেখান থেকে আমদানি করা হয়। আটকে থাকা অর্ডার প্রতিটি নির্ধারিত যাচাইয়ে আবার চেষ্টা করা হয়; বারোবার চেষ্টার পর সেগুলো লগে রাখা হয় এবং আপনার হাতে আনার জন্য রেখে দেওয়া হয়।',
'Oc_G_T_Cancel' => 'বাতিল ও অর্থ ফেরত',
'Oc_G_Cancel_1' => 'স্টোরে কোনো অর্ডার বাতিলকৃত অবস্থায় পৌঁছালে এখানে এর বিক্রয় উল্টে দেওয়া হয়: স্টক ফিরে আসে, এর পেমেন্টগুলো সরানো হয় এবং বিক্রয়টি মুছে ফেলা হয়, ঠিক যেমন বিক্রয় পৃষ্ঠায় মুছলে হতো।',
'Oc_G_Cancel_2' => 'ইতিমধ্যে পৌঁছে দেওয়া, ফেরতযুক্ত, বা কর কর্তৃপক্ষ কর্তৃক গৃহীত বিক্রয় স্টোর কখনো উল্টাতে পারে না। আপনার পর্যালোচনার জন্য এটি এর নোটে ও লগে চিহ্নিত করা হয়।',
'Oc_G_Cancel_3' => 'পরে স্টোরে অর্ডারটি পুনর্বহাল হলে এটি আবার একটি নতুন বিক্রয় হিসেবে আসে।',
'Oc_G_T_Automation' => 'স্বয়ংক্রিয়তার সুইচ',
'Oc_G_Auto_1' => 'স্বয়ংক্রিয়ভাবে অর্ডার আমদানি: অর্ডারের নোটিশ ও নির্ধারিত যাচাই। বন্ধ থাকলে অর্ডার শুধু তখনই আসে যখন আপনি অর্ডার ট্যাবে সেগুলো আনেন।',
'Oc_G_Auto_2' => 'স্বয়ংক্রিয়ভাবে স্টক পাঠানো: লাইভ স্টক হালনাগাদ ও ঘণ্টাভিত্তিক যাচাই। বন্ধ থাকলে স্টোর শুধু তখনই বদলায় যখন আপনি হাতে স্টক পাঠান।',
'Oc_G_Auto_3' => 'স্বয়ংক্রিয়ভাবে পণ্যের পরিবর্তন পাঠানো: এখানে তৈরি বা সম্পাদিত পণ্য সঙ্গে সঙ্গে স্টোর হালনাগাদ করে। বন্ধ থাকলে পণ্য ট্যাব ব্যবহার করুন।',
'Oc_G_T_Faq' => 'প্রশ্ন',
'Oc_G_Q_Secret' => 'সংযোগ পরীক্ষায় বলছে সিক্রেট মেলে না',
'Oc_G_A_Secret' => 'OpenCart-এ {company} Connector মডিউল খুলে সিক্রেটটি আবার কপি করুন; পুনরায় ইনস্টল করা মডিউল নতুন সিক্রেট পায়। পরীক্ষার আগে এটি সংযোগ ট্যাবে পেস্ট করে সংরক্ষণ করুন।',
'Oc_G_Q_Clock' => 'সংযোগ পরীক্ষায় বলছে স্টোরের ঘড়ি অনেক বেশি পার্থক্যে আছে',
'Oc_G_A_Clock' => 'স্বাক্ষরিত অনুরোধে সময় থাকে এবং দুই ঘড়ির পার্থক্য পাঁচ মিনিটের বেশি হলে তা প্রত্যাখ্যাত হয়। স্টোরের সার্ভারে তারিখ ও সময় ঠিক করুন।',
'Oc_G_Q_Redirect' => 'সংযোগ পরীক্ষায় বলছে স্টোর অন্য ঠিকানায় রিডাইরেক্ট করে',
'Oc_G_A_Redirect' => 'আপনার স্টোর ভিন্ন একটি ঠিকানায় সাড়া দেয়, সাধারণত http-এর পরিবর্তে https বা www-সহ। বার্তায় দেখানো ঠিকানাটি স্টোর URL হিসেবে ব্যবহার করুন।',
'Oc_G_Q_Not_Answering' => 'সংযোগ পরীক্ষায় বলছে কানেক্টর সাড়া দেয়নি',
'Oc_G_A_Not_Answering' => 'ঠিকানাটি কোনো OpenCart স্টোর নয়, অথবা মডিউলটি ইনস্টল করা নেই বা নিষ্ক্রিয়। স্টোর URL যাচাই করুন, তারপর দেখুন Extensions → Modules-এর অধীনে {company} Connector ইনস্টল ও চালু দেখাচ্ছে কিনা।',
'Oc_G_Q_No_Orders' => 'স্টোরে অর্ডার দেওয়া হয় কিন্তু দেখা দিতে কয়েক মিনিট লাগে',
'Oc_G_A_No_Orders' => 'স্টোর এই ওয়ার্কস্পেসে পৌঁছাতে পারে না, তাই অর্ডার শুধু নির্ধারিত যাচাইয়ের মাধ্যমে আসে। মডিউল পৃষ্ঠায় {company}-এর ঠিকানাটি দেখুন: এটি স্টোরের সার্ভার থেকে পৌঁছানোর যোগ্য হতে হবে। সংযোগ পরীক্ষা চালালে এটি আবার নিবন্ধিত হয়।',
'Oc_G_Q_Stock_Wrong' => 'স্টোরের একটি পরিমাণ ভুল',
'Oc_G_A_Stock_Wrong' => 'স্টক ট্যাবে স্টক পাঠান, যা এখানকার হিসাব থেকে প্রতিটি সংযুক্ত পণ্য নতুন করে লেখে। বারবার গরমিল হলে দেখুন স্টক সুইচ চালু আছে কিনা এবং কেউ OpenCart-এ পরিমাণ সম্পাদনা করছে কিনা।',
'Oc_G_Q_Out_Of_Stock' => 'এখানে স্টক থাকা সত্ত্বেও স্টোরে একটি পণ্য স্টক শেষ দেখাচ্ছে',
'Oc_G_A_Out_Of_Stock' => 'OpenCart 3-এ একাধিক অপশনযুক্ত পণ্যের স্টক পুরো পণ্যের ওপর থাকে; এর অপশনের বদলে স্টোরে পণ্যের পরিমাণ দেখুন। যেকোনো পণ্যের ক্ষেত্রে একবার স্টক পাঠিয়ে সেই পণ্যের লগ দেখুন।',
'Oc_G_Q_Held' => 'লগে বলছে একটি অর্ডার আটকে রাখা হয়েছে',
'Oc_G_A_Held' => 'এর একটি আইটেম এখানকার কোনো পণ্যের সাথে মেলে না এবং স্টোর থেকে আমদানি করা যায়নি, সাধারণত কারণ পণ্যটি সেখানে মুছে ফেলা হয়েছে। পণ্যটি তৈরি বা সংযুক্ত করুন, তারপর অর্ডার ট্যাবে অর্ডার আনুন।',
'Oc_G_Q_Deleted_Sale' => 'আমি একটি আমদানিকৃত বিক্রয় মুছেছিলাম এবং সেটি ফিরে এসেছে',
'Oc_G_A_Deleted_Sale' => 'অর্ডারটি স্টোরে চালু থাকা অবস্থায় পরবর্তী নোটিশ বা যাচাই এটি আবার আমদানি করে। এর বদলে স্টোরে অর্ডারটি বাতিল করুন, যা এখানে বিক্রয়টি উল্টে দেয়।',
'Oc_G_Q_Uninstall' => 'স্টোরের সংযোগ কীভাবে বিচ্ছিন্ন করব?',
'Oc_G_A_Uninstall' => 'সংযোগ ট্যাবে সিঙ্ক বন্ধ করুন; বন্ধ থাকলে কিছুই আদানপ্রদান হয় না। স্টোর থেকে ইন্টিগ্রেশন সরাতে Extensions → Modules-এর অধীনে {company} Connector আনইনস্টল করুন।',
'Oc_Full_Guide' => 'সম্পূর্ণ নির্দেশিকা খুলুন',
'Comm_Receipt_Account_Hint' => 'যে নগদ বা ব্যাংক হিসাব থেকে এই পরিশোধ যায়। এর ব্যালেন্স সেই পরিমাণ কমে এবং খতিয়ান এর বিপরীতে বিক্রয় কমিশন ব্যয় পোস্ট করে।',
'Comm_G_Q_Ledger' => 'কমিশন পরিশোধ হিসাবে কী প্রভাব ফেলে?',
