'Oc_L_D_Warnings' => 'স্টোর থেকে আসা সতর্কতা',
'Oc_L_D_Codes_Suffixed' => 'অন্য স্টোর পণ্যে আগে থেকে ব্যবহৃত কোড (এখানে code-id হিসেবে তৈরি)',
'Oc_L_D_Options' => 'অপশনযুক্ত কিন্তু ভ্যারিয়েন্টহীন পণ্য (স্টক পণ্য অনুযায়ী রাখা হয়)',
'Oc_L_D_Unmatched' => 'যেসব অর্ডার আইটেম এখানকার কোনো পণ্যের সাথে মেলে না',
'Oc_L_D_Store_Total' => 'স্টোরের পণ্য',
'Oc_L_D_Per_Page' => 'প্রতি পৃষ্ঠায় পণ্য',
'Oc_L_D_Order' => 'OpenCart অর্ডার',
'Oc_L_D_Sale' => 'বিক্রয়',
'Oc_L_D_Product_Ids' => 'সারিতে থাকা পণ্য',
'Oc_L_D_Stock_Ids' => 'সারিতে থাকা স্টক পরিবর্তন',
'Oc_L_D_Id' => 'আইডি',
'Oc_L_D_Error' => 'ত্রুটি',
'Oc_L_Act_products_pull' => 'পণ্য আনা',
'Oc_L_Act_products_push' => 'পণ্য পাঠানো',
'Oc_L_Act_inventory_push' => 'স্টক পাঠানো',
'Oc_L_Act_orders_pull' => 'অর্ডার আনা',
'Oc_L_Act_orders_catch_up' => 'নির্ধারিত অর্ডার আনা',
'Oc_L_Act_orders_import' => 'অর্ডার আমদানি',
'Oc_L_Act_orders_retry' => 'অর্ডার পুনরায় চেষ্টা',
'Oc_L_Act_orders_reverse' => 'অর্ডার বাতিল',
'Oc_L_Act_orders_review' => 'অর্ডার পর্যালোচনা প্রয়োজন',
'Oc_L_Act_webhook_order' => 'অর্ডারের বিজ্ঞপ্তি',
'Oc_L_Act_auto_sync' => 'স্বয়ংক্রিয় সিঙ্ক',
'Oc_L_Act_connect_test' => 'সংযোগ পরীক্ষা',
'Oc_L_Act_scheduled' => 'নির্ধারিত সিঙ্ক',
'Oc_L_Act_sync' => 'সিঙ্ক',
'Oc_L_H_Secret' => 'এখানে সংরক্ষিত সিক্রেট OpenCart-এর কানেক্টর মডিউলের সিক্রেটের সাথে মেলে না, তাই স্টোর প্রতিটি কল প্রত্যাখ্যান করে।',
'Oc_L_F_Secret' => 'OpenCart-এ Extensions → Modules → কানেক্টর খুলুন, সেখানে দেখানো সিক্রেটটি কপি করুন, সংযোগ ট্যাবে পেস্ট করে সংরক্ষণ করুন। মডিউল পুনরায় ইনস্টল করলে নতুন সিক্রেট তৈরি হয়।',
'Oc_L_H_Clock' => 'OpenCart সার্ভারের ঘড়ি আমাদের ঘড়ি থেকে অনেক বেশি আলাদা, তাই স্বাক্ষরিত অনুরোধগুলো মেয়াদোত্তীর্ণ দেখায়।',
'Oc_L_F_Clock' => 'হোস্টিং প্রদানকারীকে সার্ভারের সময় (NTP) ঠিক করতে বলুন। কয়েক মিনিটের পার্থক্যই সংযোগ আটকে দিতে যথেষ্ট।',
'Oc_L_H_Disabled' => 'কানেক্টর মডিউলটি OpenCart-এ ইনস্টল করা আছে কিন্তু বন্ধ।',
'Oc_L_F_Disabled' => 'OpenCart-এ Extensions → Modules → কানেক্টর খুলে Status, Enabled-এ সেট করুন।',
'Oc_L_H_Unreachable' => 'সংরক্ষিত ঠিকানায় স্টোর সাড়া দেয়নি, অথবা সেখানে কানেক্টর মডিউল ইনস্টল করা নেই।',
'Oc_L_F_Unreachable' => 'স্টোরটি অনলাইনে আছে কিনা দেখতে ব্রাউজারে স্টোর URL খুলুন, কানেক্টর মডিউলটি ইনস্টল ও চালু আছে কিনা নিশ্চিত করুন, এবং দেখুন কোনো ফায়ারওয়াল বা মেইনটেন্যান্স মোড আমাদের সার্ভার আটকাচ্ছে কিনা।',
'Oc_L_H_Redirect' => 'স্টোর ভিজিটরদের অন্য ঠিকানায় পাঠায় (যেমন http থেকে https-এ বা www-এ)।',
'Oc_L_F_Redirect' => 'বার্তায় উল্লিখিত ঠিকানাটি সংযোগ ট্যাবে স্টোর URL হিসেবে সংরক্ষণ করুন।',
'Oc_L_H_Not_Configured' => 'স্টোর URL বা সিক্রেট নেই, তাই এখনো কিছু পাঠানো যাচ্ছে না।',
'Oc_L_F_Not_Configured' => 'সংযোগ ট্যাবে স্টোর URL ও সিক্রেট পূরণ করুন, সংরক্ষণ করুন এবং সংযোগ পরীক্ষা চালান।',
'Oc_L_H_Model_Taken' => 'স্টোরে পাঠানো একটি পণ্যের কোড অন্য একটি স্টোর পণ্য বা তার কোনো ভ্যারিয়েন্ট আগে থেকেই model হিসেবে ব্যবহার করছে।',
'Oc_L_F_Model_Taken' => 'দুটি পণ্যের একটির কোড বদলান, অথবা আগে পণ্য আনুন যাতে বিদ্যমান স্টোর পণ্যটি আবার তৈরি না হয়ে সংযুক্ত হয়।',
'Oc_L_H_Model_Missing' => 'স্টোরে পাঠানো একটি পণ্যের কোনো কোড বা নাম নেই। OpenCart-এর দুটোই প্রয়োজন।',
'Oc_L_F_Model_Missing' => 'এখানে পণ্যটিকে একটি কোড ও নাম দিন, তারপর আবার পাঠান।',
'Oc_L_H_Held' => 'একটি অর্ডার পাওয়া গেছে কিন্তু এর কিছু আইটেম এখানকার কোনো পণ্যের সাথে মেলে না, তাই এটি অপেক্ষায় আছে এবং কোনো বিক্রয় তৈরি হয়নি।',
'Oc_L_F_Held' => 'অনুপস্থিত পণ্যগুলো তৈরি করুন বা আনুন (আইটেমগুলো নিচে তালিকাভুক্ত), তারপর আবার অর্ডার আনুন। আটকে থাকা অর্ডার স্বয়ংক্রিয়ভাবে কয়েকবার পুনরায় চেষ্টা করা হয়।',
'Oc_L_H_Given_Up' => 'কয়েকবার চেষ্টার পরেও একটি অর্ডার আমদানি করা যায়নি এবং আর পুনরায় চেষ্টা করা হবে না।',
'Oc_L_F_Given_Up' => 'এর পণ্যগুলো এখানে আছে কিনা নিশ্চিত করুন, তারপর অর্ডারের আগের একটি তারিখ দিয়ে অর্ডার ট্যাব থেকে হাতে অর্ডার আনুন।',
'Oc_L_H_Review' => 'এখানকার বিক্রয়টি পৌঁছে দেওয়া বা ফেরত হওয়ার পরে OpenCart-এ একটি অর্ডার বাতিল করা হয়েছে, তাই স্টক স্বয়ংক্রিয়ভাবে উল্টানো হয়নি।',
'Oc_L_F_Review' => 'বিক্রয়টি খুলে সিদ্ধান্ত নিন আইটেমগুলো ফেরত নেবেন নাকি যেমন আছে তেমন রাখবেন।',
'Oc_L_H_Reversed' => 'OpenCart-এ একটি অর্ডার বাতিল করা হয়েছে এবং এখানকার সংশ্লিষ্ট বিক্রয়টি উল্টে দিয়ে এর স্টক ফিরিয়ে আনা হয়েছে।',
'Oc_L_H_Backlog' => 'নির্ধারিত অর্ডার আনায় এক দফায় যত অর্ডার প্রক্রিয়া করা হয় তার চেয়ে বেশি পাওয়া গেছে, তাই পরের বার আবার শুরু হবে।',
'Oc_L_F_Backlog' => 'জমে থাকা অর্ডারগুলো শেষ করতে অর্ডার ট্যাব থেকে হাতে অর্ডার আনুন।',
'Oc_L_H_Paused' => 'স্টোর সাড়া দেওয়া বন্ধ করায় স্বয়ংক্রিয় পাঠানো কিছুক্ষণের জন্য থামানো হয়েছে। এর মধ্যে করা পরিবর্তনগুলো স্টোর আবার সাড়া দিলে পাঠানো হবে।',
'Oc_L_F_Paused' => 'স্টোরটি অনলাইনে আছে কিনা দেখুন। আর কিছু করার প্রয়োজন নেই; সারিটি নিজে থেকেই আবার চালু হয়।',
'Oc_L_H_Busy' => 'দুটি স্বয়ংক্রিয় পাঠানো একসাথে পড়ে যাওয়ায় একটি সরে দাঁড়িয়েছে। কিছুই হারায়নি।',
'Oc_L_H_Codes_Suffixed' => 'আনা কিছু পণ্যের কোড এখানে অন্য একটি স্টোর পণ্যের কাছে আগে থেকেই ছিল, সাধারণত কারণ নির্বাচিত কোডের ঘরটি খালি বা তাতে ক্যাটাগরির নাম আছে। কোনো দুটি পণ্য যাতে একীভূত না হয় সেজন্য এগুলো OpenCart id যুক্ত করে তৈরি হয়েছে।',
'Oc_L_F_Codes_Suffixed' => 'নিচে তালিকাভুক্ত পণ্যগুলোর জন্য OpenCart-এ কোডের ঘরটি (Model, SKU, ISBN…) পূরণ করুন, অথবা সংযোগ ট্যাবে অন্য একটি পণ্য কোডের উৎস বেছে নিন, তারপর পণ্যের সংযোগ রিসেট করে আবার আনুন।',
'Oc_L_H_Options' => 'কিছু স্টোর পণ্যের ভ্যারিয়েন্ট স্টক ছাড়া অপশন (সাইজ, রং…) আছে, তাই পুরো পণ্যের জন্য স্টক হিসাব রাখা হয়।',
'Oc_L_F_Options' => 'কিছু করার প্রয়োজন নেই। অপশন অনুযায়ী স্টক রাখতে OpenCart 4-এ সেই অপশনগুলোকে ভ্যারিয়েন্টে রূপান্তর করুন, অথবা OpenCart 3-এ প্রতি পণ্যে একটি অপশন ব্যবহার করুন।',
'Oc_L_H_Pull_Ok' => 'পণ্যের এই পৃষ্ঠাটি স্টোর থেকে পড়া হয়েছে। তৈরি মানে এখানে একটি নতুন পণ্য; হালনাগাদ মানে এটি আগে থেকেই ছিল এবং সংযুক্ত করা হয়েছে।',
'Oc_L_H_Pull_Failed' => 'এই পৃষ্ঠার কিছু পণ্য এখানে সংরক্ষণ করা যায়নি; প্রতিটি কারণসহ নিচে তালিকাভুক্ত।',
'Oc_L_F_Pull_Failed' => 'তালিকাভুক্ত পণ্যগুলো OpenCart-এ ঠিক করুন (সাধারণ কারণ নাম বা কোড না থাকা) এবং আবার আনুন। শুধু ব্যর্থগুলোই প্রভাবিত হয়।',
'Oc_L_H_Push_Warnings' => 'পণ্যগুলো স্টোরে পাঠানো হয়েছে, কিন্তু স্টোর এর কয়েকটিতে সমস্যা জানিয়েছে, যেমন এমন একটি ছবি যা এটি ডাউনলোড করতে পারেনি।',
'Oc_L_F_Push_Warnings' => 'নিচের তালিকাটি পড়ুন। ছবিগুলো স্টোরের সার্ভার থেকে পৌঁছানোর যোগ্য হতে হবে; বাকি সবকিছু যেমন পাঠানো হয়েছে তেমনই সংরক্ষিত হয়েছে।',
'Oc_L_H_Missing_Remote' => 'স্টক পাঠানো হয়েছে, কিন্তু কিছু সংযুক্ত পণ্য আর স্টোরে নেই।',
'Oc_L_F_Missing_Remote' => 'স্টোরে সেগুলো আবার তৈরি করতে পণ্য পাঠান, অথবা ইচ্ছাকৃতভাবে মুছে থাকলে পণ্যের সংযোগ রিসেট করুন।',
'Oc_L_H_Generic' => 'একটি সিঙ্ক ধাপ ব্যর্থ হয়েছে। উপরের বার্তাটি স্টোর বা সার্ভারের নিজস্ব কারণ।',
'Oc_L_F_Generic' => 'সংযোগ ট্যাবে সংযোগ পরীক্ষা চালান। সফল হলে ধাপটি আবার চেষ্টা করুন; ব্যর্থ হলে এটি যে পরামর্শ দেয় তা অনুসরণ করুন।',
'Oc_L_H_Code_Fallback' => 'এই পৃষ্ঠার কিছু পণ্য পণ্য কোডের উৎস হিসেবে নির্বাচিত ঘরে কোনো মান ছাড়া এসেছে, তাই তাদের Model (প্রায়ই একটি ক্যাটাগরির নাম) কোড হিসেবে ব্যবহৃত হয়েছে।',
'Oc_L_F_Code_Fallback' => 'নিচে "প্রতিটি ঘরযুক্ত পণ্য" দেখুন। স্টোরে মানগুলো থাকা সত্ত্বেও নির্বাচিত ঘরে ০ দেখালে স্টোর সেগুলো ভিন্ন একটি শনাক্তকারী নামে রাখে; OpenCart-এ একটি তালিকাভুক্ত পণ্য খুলুন (Data ট্যাব, Product Codes) এবং সেখানে যা দেখায় তা আমাদের পাঠান। অন্যথায় তালিকাভুক্ত পণ্যগুলোর জন্য OpenCart-এ ঘরটি পূরণ করে আবার আনুন।',
'Oc_L_H_Old_Connector' => 'স্টোরে এখনো 1.1.0-এর চেয়ে পুরোনো একটি কানেক্টর চলছে, যা শুধু Model ও SKU পাঠায়, তাই নির্বাচিত কোডের ঘরটি কখনো আসে না এবং Model ব্যবহৃত হয়েছে।',
'Oc_L_F_Old_Connector' => 'কানেক্টরটি আবার ডাউনলোড করুন, OpenCart-এ পুরোনোটি আনইনস্টল করে মুছে দিন (Extensions → Installer), নতুনটি ইনস্টল করুন, এর নতুন সিক্রেট সংযোগ ট্যাবে পেস্ট করুন এবং সংযোগ পরীক্ষা চালান। আনার আগে পৃষ্ঠায় Connector 1.1.0 দেখাতে হবে।',
