'LicK_G_Request_Help' => 'license_key সহ একটি JSON বডি পাঠান। product (পণ্যের কোড) ঐচ্ছিক এবং নিশ্চিত করে যে কী-টি আপনার পণ্যের। domain বা device_id (+ ঐচ্ছিক device_name) পাঠান — লক করা লাইসেন্স এবং সক্রিয়করণ সীমাযুক্ত লাইসেন্সের জন্য এটি আবশ্যক। প্রতিটি কলে একটি এলোমেলো nonce পাঠান এবং টোকেনে সেটি ফিরে আসছে কিনা যাচাই করুন।',
