'LicK_G_Response_Help' => 'valid কেবল তখনই true হয় যখন activate / validate উত্তর এই ডোমেইন বা ডিভাইসে ব্যবহারের অনুমতি দেয়। status লাইসেন্সের অবস্থা জানায়। প্রত্যাখ্যাত উত্তরে error ও message-ও থাকে। টোকেনে action, key_fingerprint (আপনার কী-এর SHA-256, বড় হাতের অক্ষরে রূপান্তরিত ও ট্রিম করা), identifier, nonce এবং host পুনরায় থাকে — এগুলো যাচাই করুন।',
